public class WebProcessingContextBuilderBuildTests {


    private ITestWebExchangeBuilder exchangeBuilder;
    private IWebExchange exchange;
    private WebProcessingContextBuilder builder;


    @BeforeEach
    public void setUp() {
        this.exchangeBuilder = mock(ITestWebExchangeBuilder.class);
        this.exchange = mock(IWebExchange.class);
        when(this.exchangeBuilder.buildExchange(
                any(ITest.class), anyMap(), anyMap(), anyMap(), anyMap(), any(Locale.class)))
                .thenReturn(this.exchange);
        this.builder = new WebProcessingContextBuilder(this.exchangeBuilder);
    }


    private static ITest testWith(final ITestContext context) {
        final ITest test = mock(ITest.class);
        when(test.getContext()).thenReturn(context);
        return test;
    }


    @Test
    public void buildWithNullTestReturnsNull() {
        assertNull(this.builder.build(null));
        verifyNoInteractions(this.exchangeBuilder);
    }


    @Test
    public void buildWithEmptyContextUsesDefaultLocaleAndEmptyMaps() {
        final TestContext context = new TestContext();
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertNotNull(result);
        assertEquals(WebProcessingContextBuilder.DEFAULT_LOCALE, result.getLocale());
        assertTrue(result.getVariableNames().isEmpty());

        verify(this.exchangeBuilder).buildExchange(
                eq(test), anyMap(), anyMap(), anyMap(), anyMap(),
                eq(WebProcessingContextBuilder.DEFAULT_LOCALE));
    }


    @Test
    @SuppressWarnings("unchecked")
    public void buildWithEmptyContextPassesEmptyExchangeMaps() {
        final TestContext context = new TestContext();
        final ITest test = testWith(context);

        this.builder.build(test);

        final ArgumentCaptor<Map<String, Object>> requestAttrsCaptor = ArgumentCaptor.forClass(Map.class);
        final ArgumentCaptor<Map<String, String[]>> paramsCaptor = ArgumentCaptor.forClass(Map.class);
        final ArgumentCaptor<Map<String, Object>> sessionAttrsCaptor = ArgumentCaptor.forClass(Map.class);
        final ArgumentCaptor<Map<String, Object>> applicationAttrsCaptor = ArgumentCaptor.forClass(Map.class);

        verify(this.exchangeBuilder).buildExchange(
                eq(test),
                requestAttrsCaptor.capture(),
                paramsCaptor.capture(),
                sessionAttrsCaptor.capture(),
                applicationAttrsCaptor.capture(),
                eq(WebProcessingContextBuilder.DEFAULT_LOCALE));

        assertTrue(requestAttrsCaptor.getValue().isEmpty());
        assertTrue(paramsCaptor.getValue().isEmpty());
        assertTrue(sessionAttrsCaptor.getValue().isEmpty());
        assertTrue(applicationAttrsCaptor.getValue().isEmpty());
    }


    @Test
    public void buildUsesLocaleFromExpressionResult() {
        final TestContext context = new TestContext();
        context.setLocale((variables, locale) -> "pt_BR");
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertEquals(new Locale("pt", "BR"), result.getLocale());

        verify(this.exchangeBuilder).buildExchange(
                eq(test), anyMap(), anyMap(), anyMap(), anyMap(),
                eq(new Locale("pt", "BR")));
    }


    @Test
    public void buildUsesOgnlLocaleExpression() {
        final TestContext context = new TestContext();
        context.setLocale(new OgnlTestContextExpression("'fr_FR'"));
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertEquals(Locale.FRANCE, result.getLocale());
    }


    @Test
    public void buildFallsBackToDefaultLocaleWhenExpressionResultIsNull() {
        final TestContext context = new TestContext();
        context.setLocale((variables, locale) -> null);
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertEquals(WebProcessingContextBuilder.DEFAULT_LOCALE, result.getLocale());
    }


    @Test
    public void buildResolvesVariablesAndRemovesInternalPrefixes() {
        final TestContext context = new TestContext();
        context.getVariables().put("name", (variables, locale) -> "world");
        context.getVariables().put("count", (variables, locale) -> 42);
        context.getVariables().put("arith", new OgnlTestContextExpression("3 * 4"));
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertEquals("world", result.getVariable("name"));
        assertEquals(Integer.valueOf(42), result.getVariable("count"));
        assertEquals(Integer.valueOf(12), result.getVariable("arith"));

        assertTrue(result.containsVariable("name"));
        assertFalse(result.containsVariable("param"));
        assertFalse(result.containsVariable("request"));
        assertFalse(result.containsVariable("session"));
        assertFalse(result.containsVariable("application"));
    }


    @Test
    @SuppressWarnings("unchecked")
    public void buildResolvesRequestParameterValuesAsStrings() {
        final TestContext context = new TestContext();
        context.getRequestParameters().put("p", new ITestContextExpression[]{
