                (variables, locale) -> 5,
                (variables, locale) -> null
        });
        final ITest test = testWith(context);

        this.builder.build(test);

        final ArgumentCaptor<Map<String, String[]>> paramsCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.exchangeBuilder).buildExchange(
                eq(test), anyMap(), paramsCaptor.capture(), anyMap(), anyMap(),
                eq(WebProcessingContextBuilder.DEFAULT_LOCALE));

        final Map<String, String[]> params = paramsCaptor.getValue();
        assertEquals(1, params.size());
        assertArrayEquals(new String[]{"a", "5", null}, params.get("p"));
    }


    @Test
    @SuppressWarnings("unchecked")
    public void buildResolvesRequestSessionAndApplicationAttributes() {
        final TestContext context = new TestContext();
        context.getRequestAttributes().put("ra", (variables, locale) -> "RA");
        context.getSessionAttributes().put("sa", (variables, locale) -> "SA");
        context.getApplicationAttributes().put("aa", (variables, locale) -> "AA");
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        final ArgumentCaptor<Map<String, Object>> requestAttrsCaptor = ArgumentCaptor.forClass(Map.class);
        final ArgumentCaptor<Map<String, Object>> sessionAttrsCaptor = ArgumentCaptor.forClass(Map.class);
        final ArgumentCaptor<Map<String, Object>> applicationAttrsCaptor = ArgumentCaptor.forClass(Map.class);

        verify(this.exchangeBuilder).buildExchange(
                eq(test),
                requestAttrsCaptor.capture(),
                anyMap(),
                sessionAttrsCaptor.capture(),
                applicationAttrsCaptor.capture(),
                eq(WebProcessingContextBuilder.DEFAULT_LOCALE));

        assertEquals("RA", requestAttrsCaptor.getValue().get("ra"));
        assertEquals("SA", sessionAttrsCaptor.getValue().get("sa"));
        assertEquals("AA", applicationAttrsCaptor.getValue().get("aa"));

        // Attributes are exposed through the exchange (not as plain context variables)
        assertFalse(result.containsVariable("ra"));
        assertFalse(result.containsVariable("sa"));
        assertFalse(result.containsVariable("aa"));
    }


    @Test
    public void buildReturnsContextBackedByBuiltExchange() {
        final TestContext context = new TestContext();
        final ITest test = testWith(context);

        final IContext result = this.builder.build(test);

        assertTrue(result instanceof IWebContext);
        assertSame(this.exchange, ((IWebContext) result).getExchange());
    }


    @Test
    public void buildWrapsEvaluationExceptionsInTestEngineExecutionException() {
        final RuntimeException failure = new RuntimeException("boom");
        final TestContext context = new TestContext();
        context.getVariables().put("bad", (variables, locale) -> {
            throw failure;
        });
        final ITest test = testWith(context);

        final TestEngineExecutionException exception =
                assertThrows(TestEngineExecutionException.class, () -> this.builder.build(test));

        assertSame(failure, exception.getCause());
    }


    @Test
    public void buildInvokesAdditionalProcessingHookAndHidesInternalPrefixes() {
        final RecordingWebProcessingContextBuilder recordingBuilder =
                new RecordingWebProcessingContextBuilder(this.exchangeBuilder);

        final TestContext context = new TestContext();
        context.getVariables().put("user", (variables, locale) -> "u");
        final ITest test = testWith(context);

        final IContext result = recordingBuilder.build(test);

        assertTrue(recordingBuilder.additionalProcessingCalled);
        assertEquals("u", result.getVariable("user"));
        assertEquals("byHook", result.getVariable("added"));
        assertSame(this.exchange, recordingBuilder.capturedExchange);
        assertEquals(WebProcessingContextBuilder.DEFAULT_LOCALE, recordingBuilder.capturedLocale);

        assertNotNull(recordingBuilder.capturedVariables);
        assertTrue(recordingBuilder.capturedVariables.containsKey("user"));
        assertFalse(recordingBuilder.capturedVariables.containsKey("param"));
        assertFalse(recordingBuilder.capturedVariables.containsKey("request"));
        assertFalse(recordingBuilder.capturedVariables.containsKey("session"));
        assertFalse(recordingBuilder.capturedVariables.containsKey("application"));
    }


    private static final class RecordingWebProcessingContextBuilder extends WebProcessingContextBuilder {

        private boolean additionalProcessingCalled = false;
        private Map<String, Object> capturedVariables;
        private Locale capturedLocale;
        private IWebExchange capturedExchange;

        private RecordingWebProcessingContextBuilder(final ITestWebExchangeBuilder exchangeBuilder) {
            super(exchangeBuilder);
        }

        @Override
        protected void doAdditionalVariableProcessing(
                final ITest test, final IWebExchange webExchange,
                final Locale locale, final Map<String, Object> variables) {
            this.additionalProcessingCalled = true;
            variables.put("added", "byHook");
        }

        @Override
        protected IWebContext doCreateWebContextInstance(
                final ITest test, final IWebExchange webExchange,
                final Locale locale, final Map<String, Object> variables) {
            this.capturedVariables = new HashMap<String, Object>(variables);
            this.capturedLocale = locale;
            this.capturedExchange = webExchange;
            return super.doCreateWebContextInstance(test, webExchange, locale, variables);
        }
    }
}
