    @Test
    void readsADirectIndexItemAndAppliesIteratorAndParallelizerSpecifications() {
        final TestResourceItem indexResource = new TestResourceItem(
                "suite.thindex",
                "# a comment\n" +
                "\n" +
                "alpha\n" +
                " beta [iter-3] \n" +
                "gamma [parallel-2]   \n");

        final RecordingResourceResolver resourceResolver = new RecordingResourceResolver();
        resourceResolver.put("alpha", new TestResourceContainer("alpha"));
        resourceResolver.put("beta", new TestResourceContainer("beta"));
        resourceResolver.put("gamma", new TestResourceContainer("gamma"));

        final StandardTestableResolver resolver = new StandardTestableResolver();
        resolver.setTestResourceResolver(resourceResolver);

        final ITestSequence result = resolver.resolveAsTestSequence("execution", indexResource);

        assertNotNull(result);
        assertEquals("suite.thindex", result.getName());
        assertEquals(3, result.getSize());
        assertEquals(Arrays.asList("alpha", "beta", "gamma"), resourceResolver.getRequestedNames());
        assertEquals(3, resourceResolver.getRelativeResources().size());
        for (final ITestResource relativeResource : resourceResolver.getRelativeResources()) {
            assertSame(indexResource, relativeResource);
        }
        assertEquals("alpha", result.getElements().get(0).getName());

        final ITestIterator iterator = assertInstanceOf(ITestIterator.class, result.getElements().get(1));
        assertEquals(3, iterator.getIterations());
        assertEquals("beta", iterator.getIteratedElement().getName());

        final ITestParallelizer parallelizer =
                assertInstanceOf(ITestParallelizer.class, result.getElements().get(2));
        assertEquals(2, parallelizer.getNumThreads());
        assertEquals("gamma", parallelizer.getParallelizedElement().getName());

        assertEquals(1, indexResource.getReadCount());
    }


