package org.thymeleaf.testing.templateengine.util;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

class EscapeUtilsUnescapeUnicodeTests {

    private static final char BACKSLASH = '\\';

    private static String backslash() {
        return String.valueOf(BACKSLASH);
    }

    private static String escape(final String hexDigits) {
        return backslash() + "u" + hexDigits;
    }

    private static String escapedBackslash() {
        return backslash() + backslash();
    }

    @Test
    void nullInputReturnsNull() {
        assertNull(EscapeUtils.unescapeUnicode(null));
    }

    @Test
    void textWithoutUnicodeEscapesIsReturnedUnchangedAndAsTheSameObject() {
        final String empty = new String();
        final String plain = new String("plain text with \\ and \\n and \\x0041");

        assertSame(empty, EscapeUtils.unescapeUnicode(empty));
        assertSame(plain, EscapeUtils.unescapeUnicode(plain));
    }

    @Test
    void decodesBasicUnicodeEscape() {
        assertEquals("A", EscapeUtils.unescapeUnicode(escape("0041")));
        assertEquals("Z", EscapeUtils.unescapeUnicode(escape("005A")));
    }

    @Test
    void acceptsUppercaseLowercaseAndMixedCaseHexDigits() {
        final String expected = String.valueOf((char) 0x00E1);

        assertEquals(expected, EscapeUtils.unescapeUnicode(escape("00e1")));
        assertEquals(expected, EscapeUtils.unescapeUnicode(escape("00E1")));
        assertEquals(String.valueOf((char) 0xABCD), EscapeUtils.unescapeUnicode(escape("AbCd")));
    }

    @Test
    void decodesNullAndMaximumBmpCodeUnits() {
        assertEquals(String.valueOf((char) 0x0000), EscapeUtils.unescapeUnicode(escape("0000")));
        assertEquals(String.valueOf((char) 0xFFFF), EscapeUtils.unescapeUnicode(escape("ffff")));
    }

    @Test
    void decodesUnicodeEscapesEmbeddedInText() {
        assertEquals("before-A-after", EscapeUtils.unescapeUnicode("before-" + escape("0041") + "-after"));
    }

    @Test
    void decodesMultipleUnicodeEscapes() {
        assertEquals("ABC", EscapeUtils.unescapeUnicode(escape("0041") + escape("0042") + escape("0043")));
    }

    @Test
    void decodesAdjacentSurrogateEscapesIntoOneSupplementaryCharacter() {
        final String supplementary = new String(Character.toChars(0x1F600));

        assertEquals(supplementary, EscapeUtils.unescapeUnicode(escape("D83D") + escape("DE00")));
    }

    @Test
    void consumesExactlyFourHexDigitsAndLeavesTheRestAsText() {
        assertEquals("A1", EscapeUtils.unescapeUnicode(escape("0041") + "1"));
        assertEquals("AFFFF", EscapeUtils.unescapeUnicode(escape("0041FFFF")));
    }

    @Test
    void allowsAdditionalUCharactersAfterTheEscapeMarker() {
        assertEquals("A", EscapeUtils.unescapeUnicode(backslash() + "uu0041"));
        assertEquals("A", EscapeUtils.unescapeUnicode(backslash() + "uuuu0041"));
    }

    @Test
    void leavesUnicodeEscapesWithFewerThanFourHexDigitsUntouched() {
        final String tooShort = new String(escape("12"));
        final String markerOnly = new String(escape(""));

        assertSame(tooShort, EscapeUtils.unescapeUnicode(tooShort));
        assertSame(markerOnly, EscapeUtils.unescapeUnicode(markerOnly));
    }

    @Test
    void leavesUnicodeEscapesContainingANonHexDigitUntouched() {
        final String invalid = new String(escape("12G4"));

        assertSame(invalid, EscapeUtils.unescapeUnicode(invalid));
    }

    @Test
    void continuesScanningAfterAnInvalidUnicodeEscape() {
        assertEquals(escape("12") + "A", EscapeUtils.unescapeUnicode(escape("12") + escape("0041")));
    }

    @Test
    void doesNotTreatOtherBackslashSequencesAsUnicodeEscapes() {
        final String otherEscapes = new String(backslash() + "n" + backslash() + "U0041" + backslash());

        assertSame(otherEscapes, EscapeUtils.unescapeUnicode(otherEscapes));
    }

    @Test
    void collapsesEscapedUnicodePrefixWithoutUnescapingIt() {
        final String input = "before-" + escapedBackslash() + "u0041-after";
        final String expected = "before-" + backslash() + "u0041-after";

        assertEquals(expected, EscapeUtils.unescapeUnicode(input));
    }

    @Test
    void collapsesEscapedUnicodePrefixThatHasNoHexDigits() {
        assertEquals(backslash() + "u", EscapeUtils.unescapeUnicode(escapedBackslash() + "u"));
    }

    @Test
    void stillDecodesLaterUnicodeEscapesAfterAnEscapedPrefix() {
        final String input = escapedBackslash() + "u0041" + escape("0042");
        final String expected = backslash() + "u0041B";

        assertEquals(expected, EscapeUtils.unescapeUnicode(input));
    }

    @Test
    void collapsesEachEscapedUnicodePrefixSeparately() {
        final String input = escapedBackslash() + "u" + escapedBackslash() + "u";
        final String expected = backslash() + "u" + backslash() + "u";

        assertEquals(expected, EscapeUtils.unescapeUnicode(input));
    }

    @Test
    void doubleBackslashNotFollowedByUnicodeMarkerIsLeftUntouched() {
        final String input = new String("before" + escapedBackslash() + "x0041");

        assertSame(input, EscapeUtils.unescapeUnicode(input));
    }
}
