        c.getPrologParseConfiguration().setValidateProlog(false);
        c.getPrologParseConfiguration().setXmlDeclarationPresence(ParseConfiguration.PrologPresence.ALLOWED);
        PARSER = new MarkupParser(c);
    }
    public static void main(String[] a) {
        org.thymeleaf.testing.templateengine.util.ResultCompareUtils.ResultComparison r;
        String[][] pairs = {
            {"<div>hello</div>", "<div>hello</div>"},
            {"<div>hello</div>", "<div>bye</div>"},
            {"<div>hello   world</div>", "<div>hello world</div>"},
