            {"<div class=\"a\">x</div>", "<div class=\"b\">x</div>"},
            {"<div>a</div>", "<!DOCTYPE html><div>a</div>"},
        };
        for (String[] p : pairs) {
            for (boolean lenient : new boolean[]{false, true}) {
                try {
                    r = org.thymeleaf.testing.templateengine.util.ResultCompareUtils.compareMarkupResults(p[0], p[1], lenient);
