import static org.junit.jupiter.api.Assertions.assertTrue;



/**
 * Tests for {@link ResultCompareUtils#compareMarkupResults(String, String, boolean)}.
 */
public class ResultCompareUtilsCompareMarkupResultsTests {


    private static final String MATCH_EXPLANATION = "OK";
    private static final String MISMATCH_PREFIX = "Actual result does not match expected result.";
    private static final String OBTAINED_LABEL = "Obtained:";
    private static final String EXPECTED_LABEL = "but expected:";



    private static ResultComparison compare(final String expected, final String actual, final boolean lenient) {
        return ResultCompareUtils.compareMarkupResults(expected, actual, lenient);
    }


    private static void assertMatch(final ResultComparison comparison) {
        assertNotNull(comparison, "Comparison object should never be null");
        assertTrue(
                comparison.getResult(),
                "Expected results to be reported as matching, but explanation was: ["
                        + comparison.getExplanation() + "]");
        assertEquals(MATCH_EXPLANATION, comparison.getExplanation(), "Explanation of a matching comparison");
        assertNull(comparison.getActualResult(), "Actual result should not be reported on a match");
        assertNull(comparison.getExpectedResult(), "Expected result should not be reported on a match");
    }


    private static void assertMismatch(
            final ResultComparison comparison, final String expected, final String actual) {

        assertNotNull(comparison, "Comparison object should never be null");
        assertFalse(comparison.getResult(), "Expected results to be reported as NOT matching");

        final String explanation = comparison.getExplanation();
        assertNotNull(explanation, "Explanation should be present when results do not match");
        assertTrue(
                explanation.startsWith(MISMATCH_PREFIX),
                "Explanation should start with the mismatch message, but was: [" + explanation + "]");
        assertTrue(
                explanation.contains(OBTAINED_LABEL),
                "Explanation should contain the actual fragment, but was: [" + explanation + "]");
        assertTrue(
