        when(this.acl.isGranted(this.permissions, this.sids, false)).thenReturn(true);

        final boolean result = AclAuthUtils.authorizeUsingAccessControlList(
                this.context, this.domainObject, this.permissions, this.authentication);

        assertTrue(result, "Access must be granted when the ACL grants the requested permissions");

        verify(this.sidRetrievalStrategy).getSids(this.authentication);
        verify(this.objectIdentityRetrievalStrategy).getObjectIdentity(this.domainObject);
        verify(this.aclService).readAclById(this.objectIdentity, this.sids);
