/**
 * Unit tests for
 * {@link AclAuthUtils#authorizeUsingAccessControlList(IExpressionContext, Object, List, Authentication)}.
 *
 * <p>The {@code ApplicationContext} lookup performed through {@link AuthUtils#getContext(IExpressionContext)}
 * is replaced (static mock) by a real {@link GenericApplicationContext} so that the bean-resolution
 * logic of the production code (including fallback to default strategy implementations and
 * parent-context lookups) is exercised.</p>
 */
public class AclAuthUtilsAuthorizeUsingAccessControlListTests {


    private static final String DOMAIN_OBJECT = "domainObjectInstance";


    private MockedStatic<AuthUtils> authUtilsStaticMock;
    private IExpressionContext expressionContext;
    private GenericApplicationContext applicationContext;

    private AclService aclService;
    private Acl acl;
    private Authentication authentication;
    private List<Permission> permissions;


    @BeforeEach
    public void setUp() {

        this.expressionContext = mock(IExpressionContext.class);
        this.authUtilsStaticMock = mockStatic(AuthUtils.class);

        this.applicationContext = new GenericApplicationContext();

        this.aclService = mock(AclService.class);
        this.acl = mock(Acl.class);

        this.authentication = new TestingAuthenticationToken("alice", "password", "ROLE_USER");
        this.permissions = new ArrayList<Permission>(Collections.singletonList(BasePermission.READ));

        SecurityContextHolder.clearContext();

    }


    @AfterEach
    public void tearDown() {
        SecurityContextHolder.clearContext();
        try {
            this.applicationContext.close();
        } finally {
            this.authUtilsStaticMock.close();
        }
    }




    // ---------------------------------------------------------------------
    // Helper methods
    // ---------------------------------------------------------------------

    private void registerAclServiceBean(final String beanName) {
        this.applicationContext.registerBean(beanName, AclService.class, () -> this.aclService);
    }

    private void registerSidRetrievalStrategyBean(final String beanName, final SidRetrievalStrategy strategy) {
        this.applicationContext.registerBean(beanName, SidRetrievalStrategy.class, () -> strategy);
    }

    private void registerObjectIdentityRetrievalStrategyBean(
            final String beanName, final ObjectIdentityRetrievalStrategy strategy) {
        this.applicationContext.registerBean(beanName, ObjectIdentityRetrievalStrategy.class, () -> strategy);
    }

    /*
     * Refreshes the application context and makes AuthUtils.getContext(...) return it.
     */
    private void startContext() {
        this.applicationContext.refresh();
        useApplicationContext(this.applicationContext);
    }

    private void useApplicationContext(final ApplicationContext context) {
        this.authUtilsStaticMock
                .when(() -> AuthUtils.getContext(any(IExpressionContext.class)))
                .thenReturn(context);
    }

    private boolean authorize(final Object domainObject, final List<Permission> perms, final Authentication auth) {
        return AclAuthUtils.authorizeUsingAccessControlList(
                this.expressionContext, domainObject, perms, auth);
    }

    @SuppressWarnings("unchecked")
    private List<Sid> captureSidsFromReadAclById() {
        final ArgumentCaptor<List<Sid>> sidsCaptor = ArgumentCaptor.forClass(List.class);
        verify(this.aclService).readAclById(any(ObjectIdentity.class), sidsCaptor.capture());
        return sidsCaptor.getValue();
    }

    private ObjectIdentity captureObjectIdentityFromReadAclById() {
        final ArgumentCaptor<ObjectIdentity> oidCaptor = ArgumentCaptor.forClass(ObjectIdentity.class);
        verify(this.aclService).readAclById(oidCaptor.capture(), anyList());
        return oidCaptor.getValue();
    }

    private void stubAclGrant(final boolean granted) {
        when(this.aclService.readAclById(any(ObjectIdentity.class), anyList())).thenReturn(this.acl);
        when(this.acl.isGranted(anyList(), anyList(), eq(Boolean.FALSE))).thenReturn(granted);
    }




