    @Test
    public void testNullAuthenticationReturnsFalse() {

        registerAclServiceBean("aclService");
        stubAclGrant(true);
        startContext();

        assertFalse(authorize(DOMAIN_OBJECT, this.permissions, null));

        // The context is always resolved (and therefore the passed expression context used)
        this.authUtilsStaticMock.verify(() -> AuthUtils.getContext(this.expressionContext));

        // No ACL is read at all when there is no authenticated user
        verifyNoInteractions(this.aclService);
        verifyNoInteractions(this.acl);

    }


    @Test
    public void testNullAuthenticationWithEmptyApplicationContextReturnsFalse() {

        // No AclService, SidRetrievalStrategy nor ObjectIdentityRetrievalStrategy beans exist
        startContext();

        assertFalse(authorize(DOMAIN_OBJECT, this.permissions, null));

    }


    @Test
    public void testNullAuthenticationTakesPrecedenceOverNullDomainObject() {

