        this.bindStatus = mock(IThymeleafBindStatus.class);
        this.modelFactory = mock(IModelFactory.class);
        this.hiddenTagModel = mock(IModel.class);
        this.hiddenTag = mock(IStandaloneElementTag.class);

        when(this.context.getIdentifierSequences()).thenReturn(new IdentifierSequences());
        when(this.context.getModelFactory()).thenReturn(this.modelFactory);
        when(this.modelFactory.createModel()).thenReturn(this.hiddenTagModel);
        when(this.modelFactory.createStandaloneElementTag(
                anyString(), anyMap(), any(AttributeValueQuotes.class), anyBoolean(), anyBoolean()))
                .thenReturn(this.hiddenTag);

        final Map<TemplateMode, Set<IElementProcessor>> processorsByTemplateMode =
                new EnumMap<TemplateMode, Set<IElementProcessor>>(TemplateMode.class);
        final Set<IElementProcessor> noProcessors = new LinkedHashSet<IElementProcessor>();
        for (final TemplateMode templateMode : TemplateMode.values()) {
            processorsByTemplateMode.put(templateMode, noProcessors);
        }
        this.attributeDefinitions = new AttributeDefinitions(processorsByTemplateMode);

    }


