                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals(
                attributes("type", "hidden", "name", "_user.active", "value", "on"),
                attributesCaptor.getValue());

        verify(this.hiddenTagModel).add(this.hiddenTag);
        verify(this.structureHandler).insertBefore(this.hiddenTagModel);
