    @Test
    public void testRequestDataValueProcessorIsAppliedToCheckboxAndHiddenValues() {

        stubTagAttributes(attributes("type", "checkbox"));
        when(this.bindStatus.getExpression()).thenReturn("user.active");
        when(this.bindStatus.getValue()).thenReturn(Boolean.TRUE);
        when(this.bindStatus.getValueType()).thenReturn((Class<?>) Boolean.class);

        final IThymeleafRequestContext requestContext = mock(IThymeleafRequestContext.class);
        final IThymeleafRequestDataValueProcessor requestDataValueProcessor =
                mock(IThymeleafRequestDataValueProcessor.class);
        when(this.context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT)).thenReturn(requestContext);
        when(requestContext.getRequestDataValueProcessor()).thenReturn(requestDataValueProcessor);
        when(requestDataValueProcessor.processFormFieldValue(anyString(), anyString(), anyString()))
                .thenAnswer(invocation -> "P(" + invocation.getArgument(0) + "," + invocation.getArgument(1) + "," +
                        invocation.getArgument(2) + ")");

        process(true);

        verify(requestDataValueProcessor).processFormFieldValue("user.active", "true", "checkbox");
        verify(requestDataValueProcessor).processFormFieldValue("_user.active", "on", "hidden");

        verify(this.structureHandler).setAttribute("value", "P(user.active,true,checkbox)");

        final ArgumentCaptor<Map<String, String>> attributesCaptor = mapCaptor();
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals(
                attributes("type", "hidden", "name", "_user.active", "value", "P(_user.active,on,hidden)"),
                attributesCaptor.getValue());

    }


    // --------------------------------------------------------------------------------------------
    // Helpers
    // --------------------------------------------------------------------------------------------

    private void process(final boolean renderHiddenMarkersBeforeCheckboxes) {

        final SpringInputCheckboxFieldTagProcessor processor =
                new SpringInputCheckboxFieldTagProcessor(DIALECT_PREFIX, renderHiddenMarkersBeforeCheckboxes);
        processor.setAttributeDefinitions(this.attributeDefinitions);
        processor.doProcess(
                this.context, this.tag, FIELD_ATTRIBUTE_NAME, FIELD_ATTRIBUTE_VALUE, this.bindStatus,
                this.structureHandler);

    }


    private void stubTagAttributes(final Map<String, String> tagAttributes) {

        when(this.tag.getAttributeValue(any(AttributeName.class))).thenAnswer(invocation -> {
            final AttributeName attributeName = invocation.getArgument(0);
            return tagAttributes.get(attributeName.getAttributeName());
        });
        when(this.tag.hasAttribute(any(AttributeName.class))).thenAnswer(invocation -> {
            final AttributeName attributeName = invocation.getArgument(0);
            return Boolean.valueOf(tagAttributes.containsKey(attributeName.getAttributeName()));
        });

    }


    private static Map<String, String> attributes(final String... pairs) {

        if (pairs.length % 2 != 0) {
            throw new IllegalArgumentException("An even number of arguments is required");
        }
        final Map<String, String> result = new LinkedHashMap<String, String>(pairs.length / 2, 1.0f);
        for (int i = 0; i < pairs.length; i += 2) {
            result.put(pairs[i], pairs[i + 1]);
        }
        return result;

    }


    @SuppressWarnings("unchecked")
    private static ArgumentCaptor<Map<String, String>> mapCaptor() {
        return (ArgumentCaptor<Map<String, String>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(Map.class);
    }


}
