    private static final String EXPECTED_MESSAGE =
            "View name contains an expression and so does either the URL path or the request parameters " +
            "or contents. This is forbidden in order to reduce the possibilities that direct user input " +
            "is executed as a part of the view name.";


    private static IWebRequest mockRequest(
            final String pathWithinApplication,
            final Map<String, String[]> parameterMap,
            final Map<String, String[]> cookieMap,
            final Map<String, String[]> headerMap) {

        final IWebRequest request = mock(IWebRequest.class);
        when(request.getPathWithinApplication()).thenReturn(pathWithinApplication);
        when(request.getParameterMap()).thenReturn(parameterMap);
        when(request.getCookieMap()).thenReturn(cookieMap);
        when(request.getHeaderMap()).thenReturn(headerMap);
        return request;
    }


    private static Map<String, String[]> singleValueMap(final String name, final String value) {
        final Map<String, String[]> map = new HashMap<String, String[]>();
        map.put(name, new String[] {value});
