    // ------------------------------------------------------------------------------

    @Test
    public void testAllKindsOfExpressionsInViewNameAreDetected() {

        final String[] expressionViewNames = new String[] {
                "${user.name}",
                "*{user.name}",
                "#{messages.key}",
                "@{/link}",
                "~{fragment}",
                "|literal|",
                "a__b__c"
        };

        for (final String expressionViewName : expressionViewNames) {
            final IWebRequest request = mockRequest("/app/${something}", null, null, null);
            final TemplateProcessingException exception = assertUnsafeRequest(expressionViewName, request);
            assertEquals(EXPECTED_MESSAGE, exception.getMessage(), "Failed for view name: " + expressionViewName);
        }

    }


    // ------------------------------------------------------------------------------
    // Exception type/message characteristics
    // ------------------------------------------------------------------------------

    @Test
    public void testExceptionMessageMentionsTheForbiddenPractice() {

        final IWebRequest request = mockRequest("/app/${user.name}", null, null, null);

        final TemplateProcessingException exception = assertUnsafeRequest("${user.name}", request);

        assertTrue(exception.getMessage().contains("is forbidden"));
        assertTrue(exception.getMessage().contains("direct user input"));
        assertTrue(exception.getMessage().contains("view name"));

    }

}
