package org.thymeleaf.spring5.util;

import java.util.stream.Stream;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;


public class SpringStandardExpressionUtilsContainsExternalAccessTests {


    static Stream<Arguments> objectInstantiationExpressions() {
        return Stream.of(
                Arguments.of("new Foo()"),
                Arguments.of("new java.lang.String()"),
                Arguments.of("${new Foo()}"),
                Arguments.of("prefix + new Foo()"),
                Arguments.of("foo(new Bar())"),
                Arguments.of("NEW Foo()"),
                Arguments.of("new\tFoo()"),
                Arguments.of("new\nFoo()"),
                Arguments.of("new   Foo()"),
                Arguments.of("new "),
                Arguments.of("new\n"),
                Arguments.of("n\u0000ew Foo()")
        );
    }

    @DisplayName("Detects object instantiation with the 'new' keyword")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("objectInstantiationExpressions")
    public void detectsObjectInstantiation(final String expression) {
        assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    static Stream<Arguments> paramAccessExpressions() {
        return Stream.of(
                Arguments.of("${param.foo}"),
                Arguments.of("${param['foo']}"),
                Arguments.of("param.foo"),
                Arguments.of("foo + param.bar"),
                Arguments.of("param "),
                Arguments.of("param."),
                Arguments.of("x.param.foo"),
                Arguments.of("#{param.foo}"),
                Arguments.of("PARAM.foo"),
                Arguments.of("param\t.foo"),
                Arguments.of("param\n.foo")
        );
    }

    @DisplayName("Detects parameter access with the 'param' keyword")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("paramAccessExpressions")
    public void detectsParamAccess(final String expression) {
        assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    static Stream<Arguments> staticMethodExpressions() {
        return Stream.of(
                Arguments.of("T(java.lang.Math)"),
                Arguments.of("${T(java.lang.Math).abs(-1)}"),
                Arguments.of("t(java.lang.String)"),
                Arguments.of("T (java.lang.Math)"),
                Arguments.of("T\t(java.lang.Math)"),
                Arguments.of("T\n(java.lang.Math)"),
                Arguments.of("x + T(y)"),
                Arguments.of("(T(foo))"),
                Arguments.of("foo.T(bar)"),
                Arguments.of("T()"),
                Arguments.of("T("),
                Arguments.of(" T(foo)")
        );
    }

    @DisplayName("Detects static method invocation markers")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("staticMethodExpressions")
    public void detectsStaticMethodInvocation(final String expression) {
        assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    static Stream<Arguments> beanReferenceExpressions() {
        return Stream.of(
                Arguments.of("@bean"),
                Arguments.of("${@bean}"),
                Arguments.of("x + @bean"),
                Arguments.of("@bean.property"),
                Arguments.of("@_bean"),
                Arguments.of("@a1"),
                Arguments.of("@Bean"),
                Arguments.of(" @bean"),
                Arguments.of("@bean()")
        );
    }

    @DisplayName("Detects Spring bean references")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("beanReferenceExpressions")
    public void detectsBeanReference(final String expression) {
        assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    static Stream<Arguments> safeExpressions() {
        return Stream.of(
                Arguments.of(""),
                Arguments.of("   "),
                Arguments.of("${foo.bar}"),
                Arguments.of("${foo.bar()}"),
                Arguments.of("cat(dog)"),
                Arguments.of("newspaper"),
                Arguments.of("parameter"),
                Arguments.of("${#strings.isEmpty(name)}"),
                Arguments.of("${user.name}"),
                Arguments.of("a + b * c"),
                Arguments.of("${list[0]}")
        );
    }

    @DisplayName("Does not report external access for safe expressions")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("safeExpressions")
    public void doesNotDetectExternalAccessInSafeExpressions(final String expression) {
        assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    static Stream<Arguments> keywordLikeIdentifiersAndBoundaries() {
        return Stream.of(
                // "new" embedded in or followed by an identifier character
                Arguments.of("newFoo()"),
                Arguments.of("renew Foo()"),
                Arguments.of("xnew Foo()"),
                Arguments.of("_new Foo()"),
                Arguments.of("9new Foo()"),
                Arguments.of("new"),
                Arguments.of("new("),
                Arguments.of("new.foo"),
                Arguments.of("new-foo"),
                Arguments.of("news feed"),
                // "param" embedded in or followed by an identifier character
                Arguments.of("params.foo"),
                Arguments.of("xparam.foo"),
                Arguments.of("parameter"),
                Arguments.of("a_param.foo"),
                Arguments.of("param"),
                Arguments.of("paramx.y"),
                Arguments.of("9param.foo"),
                Arguments.of("param_foo"),
                // "t(" embedded in a larger identifier
                Arguments.of("xt(foo)"),
                Arguments.of("at(foo)"),
                Arguments.of("method(foo)"),
                Arguments.of("test(foo)"),
                Arguments.of("_t(foo)"),
                Arguments.of("9t(foo)"),
                Arguments.of("art(x)"),
                Arguments.of("Tfoo(x)"),
                // '@' not starting a bean reference
                Arguments.of("@"),
                Arguments.of("@ bean"),
                Arguments.of("@ foo"),
                Arguments.of("x@bean"),
                Arguments.of("9@bean"),
                Arguments.of("_@bean"),
                Arguments.of("email@domain"),
                Arguments.of("@-bean"),
                Arguments.of("@.bean")
        );
    }

    @DisplayName("Does not mistake keyword-like text or non-boundary markers for external access")
    @ParameterizedTest(name = "[{index}] expression = {0}")
    @MethodSource("keywordLikeIdentifiersAndBoundaries")
    public void doesNotDetectFalsePositives(final String expression) {
        assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
    }


    @Test
    @DisplayName("A null expression causes a NullPointerException")
    public void nullExpressionThrowsNullPointerException() {
        assertThrows(NullPointerException.class, () -> SpringStandardExpressionUtils.containsExternalAccess(null));
    }
}
