    @Test
    public void testNullExpressionContentThrowsBeforeTouchingConfiguration() {

        final Map<String,Object> variables = new HashMap<String,Object>();
        final IExpressionContext context = newContext(this.configuration, variables);

        final IStandardVariableExpression expression = mock(IStandardVariableExpression.class);
        when(expression.getExpression()).thenReturn(null);
        when(expression.getUseSelectionAsRoot()).thenReturn(false);

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> this.evaluator.evaluate(context, expression, StandardExpressionExecutionContext.NORMAL));

        assertEquals("Expression content is null, which is not allowed", exception.getMessage());
        assertNull(exception.getCause());
        verify(context, never()).getConfiguration();
    }




