    @Test
    public void testTypeConversionUsesBindStatusWhenExpressionIsBound() {

        final IThymeleafRequestContext requestContext = mock(IThymeleafRequestContext.class);
        when(requestContext.getErrors(eq("user"), eq(false))).thenReturn(Optional.of(mock(Errors.class)));

        final IThymeleafBindStatus bindStatus = mock(IThymeleafBindStatus.class);
        when(bindStatus.getValue()).thenReturn(Integer.valueOf(42));
        when(bindStatus.getEditor()).thenReturn(null);
        when(requestContext.getBindStatus(eq("user.name"), eq(false))).thenReturn(bindStatus);

        final Map<String,Object> variables = new HashMap<String,Object>();
        variables.put(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT, requestContext);
        final IExpressionContext context = newContext(this.configuration, variables);

        // No conversion service registered: reaching the conversion stage would fail, which allows
        // verifying that the bound object path short-circuits the whole evaluation.
        final Object result = this.evaluator.evaluate(
                context, new VariableExpression("user.name"),
                StandardExpressionExecutionContext.NORMAL.withTypeConversion());

        assertEquals("42", result);
        verify(requestContext).getBindStatus(eq("user.name"), eq(false));
    }


