    private static String fullMessage(final Throwable throwable) {
        final StringBuilder message = new StringBuilder();
        Throwable current = throwable;
        final Set<String> visited = new LinkedHashSet<String>();
        while (current != null && visited.add(current.getClass().getName() + "@" + current.getMessage())) {
            if (current.getMessage() != null) {
                message.append(current.getMessage()).append(" | ");
            }
            current = current.getCause();
        }
        return message.toString();
    }




