    @Test
    public void testParsedExpressionIsCachedInTheVariableExpression() {

        final Map<String,Object> variables = new HashMap<String,Object>();
        variables.put("greeting", "first");
        final IExpressionContext context = newContext(this.configuration, variables);

        final VariableExpression expression = new VariableExpression("greeting");

        assertEquals("first", this.evaluator.evaluate(
                context, expression, StandardExpressionExecutionContext.NORMAL));
        assertNull(expression.getCachedExpression());

        // NOTE: the cache is only populated through the engine-level expression cache; when no cache manager
