    private IThymeleafBindStatus bindStatus;
    private IModelFactory modelFactory;
    private IModel hiddenTagModel;
    private IStandaloneElementTag hiddenTag;

    private SpringInputCheckboxFieldTagProcessor processor;


    @BeforeEach
    void setUp() {
        this.context = mock(ITemplateContext.class);
        this.tag = mock(IProcessableElementTag.class);
        this.structureHandler = mock(IElementTagStructureHandler.class);
        this.bindStatus = mock(IThymeleafBindStatus.class);
        this.modelFactory = mock(IModelFactory.class);
        this.hiddenTagModel = mock(IModel.class);
        this.hiddenTag = mock(IStandaloneElementTag.class);

        when(this.context.getIdentifierSequences()).thenReturn(new IdentifierSequences());
        when(this.context.getModelFactory()).thenReturn(this.modelFactory);
        when(this.modelFactory.createModel()).thenReturn(this.hiddenTagModel);
        when(this.modelFactory.createStandaloneElementTag(
                eq("input"), anyMap(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true)))
                .thenReturn(this.hiddenTag);

        this.processor = new SpringInputCheckboxFieldTagProcessor("th");
        final AttributeDefinitions attributeDefinitions = new AttributeDefinitions(Collections.emptyMap());
        this.processor.setAttributeDefinitions(attributeDefinitions);
    }


    @Test
    void booleanTrueSetsCheckedValueAndInsertsHiddenMarkerBeforeCheckbox() {
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue("id")).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).setAttribute("id", "notify-checkbox");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.structureHandler, never()).removeAttribute("checked");
        verify(this.context, never()).getIdentifierSequences();

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals(Map.of("type", "hidden", "name", "_notify", "value", "on"), attributesCaptor.getValue());

        verify(this.hiddenTagModel).add(same(this.hiddenTag));
        verify(this.structureHandler).insertBefore(same(this.hiddenTagModel));
        verify(this.structureHandler, never()).insertImmediatelyAfter(any(IModel.class), eq(false));
    }


    @Test
    void primitiveFalseRemovesCheckedAndStillAddsHiddenMarker() {
        bind("notify", Boolean.FALSE, boolean.class);

        process();

        verify(this.structureHandler).setAttribute("id", "notify1");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).removeAttribute("checked");
        verify(this.structureHandler, never()).setAttribute(eq("checked"), anyString());

        verify(this.hiddenTagModel).add(same(this.hiddenTag));
        verify(this.structureHandler).insertBefore(same(this.hiddenTagModel));
    }


    @Test
    void stringBoundValueIsConvertedForBooleanBinding() {
        bind("notify", "true", Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.structureHandler, never()).removeAttribute("checked");
    }


    @Test
    void lowercaseFalseStringIsConvertedToUncheckedBoolean() {
        bind("notify", "false", Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).removeAttribute("checked");
        verify(this.structureHandler, never()).setAttribute(eq("checked"), anyString());
    }


