        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, this::process);

        assertEquals(
                "Attribute \"value\" is required in \"input(checkbox)\" tags when binding to non-boolean values",
                exception.getMessage());
        verify(this.structureHandler, never()).setAttribute(anyString(), anyString());
        verify(this.structureHandler, never()).removeAttribute(anyString());
        verify(this.context, never()).getModelFactory();
        verifyNoInteractions(this.modelFactory);
    }


    @Test
    void disabledCheckboxGetsFieldAttributesButNoHiddenMarker() {
