        when(this.tag.getAttributeValue("id")).thenReturn("disabled-checkbox");
        when(this.tag.hasAttribute("disabled")).thenReturn(true);

        process();

        verify(this.structureHandler).setAttribute("id", "disabled-checkbox");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.context, never()).getModelFactory();
        verifyNoInteractions(this.modelFactory);
        verify(this.structureHandler, never()).insertBefore(any(IModel.class));
        verify(this.structureHandler, never()).insertImmediatelyAfter(any(IModel.class), eq(false));
    }


    @Test
    void hiddenMarkerCanBeInsertedImmediatelyAfterCheckbox() {
        this.processor = new SpringInputCheckboxFieldTagProcessor("th", false);
        this.processor.setAttributeDefinitions(new AttributeDefinitions(Collections.emptyMap()));
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue("id")).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).insertImmediatelyAfter(same(this.hiddenTagModel), eq(false));
        verify(this.structureHandler, never()).insertBefore(any(IModel.class));
    }


    @Test
    void generatedIdentifiersUseFieldNameAndIncrementForEachOccurrence() {
        bind("user[name]", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue("id")).thenReturn("   ");

        process();
        process();

        final ArgumentCaptor<String> idCaptor = ArgumentCaptor.forClass(String.class);
        verify(this.structureHandler, times(2)).setAttribute(eq("id"), idCaptor.capture());
        assertEquals(List.of("username1", "username2"), idCaptor.getAllValues());
        verify(this.structureHandler, times(2)).setAttribute("name", "user[name]");
    }


    @Test
    void nullExpressionUsesEmptyNameAndGeneratedIdentifier() {
        bind(null, Boolean.TRUE, Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("id", "1");
        verify(this.structureHandler).setAttribute("name", "");

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals("_", attributesCaptor.getValue().get("name"));
    }


    @Test
    void requestDataValueProcessorProcessesVisibleAndHiddenFieldValues() {
        final IThymeleafRequestContext requestContext = mock(IThymeleafRequestContext.class);
        final IThymeleafRequestDataValueProcessor requestDataValueProcessor =
                mock(IThymeleafRequestDataValueProcessor.class);
        when(this.context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT))
                .thenReturn(requestContext);
        when(requestContext.getRequestDataValueProcessor()).thenReturn(requestDataValueProcessor);
        when(requestDataValueProcessor.processFormFieldValue("notify", "true", "checkbox"))
                .thenReturn("processed-visible-value");
        when(requestDataValueProcessor.processFormFieldValue("_notify", "on", "hidden"))
                .thenReturn("processed-hidden-value");
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue("id")).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).setAttribute("value", "processed-visible-value");

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals("processed-hidden-value", attributesCaptor.getValue().get("value"));
        verify(requestDataValueProcessor).processFormFieldValue("notify", "true", "checkbox");
        verify(requestDataValueProcessor).processFormFieldValue("_notify", "on", "hidden");
    }


    private void bind(final String expression, final Object value, final Class<?> valueType) {
        when(this.bindStatus.getExpression()).thenReturn(expression);
        when(this.bindStatus.getValue()).thenReturn(value);
        when(this.bindStatus.getValueType()).thenReturn(valueType);
    }


    private void process() {
        this.processor.doProcess(
                this.context,
                this.tag,
                FIELD_ATTRIBUTE_NAME,
                "*{field}",
                this.bindStatus,
                this.structureHandler);
    }

}
