class SpringInputCheckboxFieldTagProcessorDoProcessTests {

    private static final AttributeName FIELD_ATTRIBUTE_NAME = AttributeNames.forHTMLName("field");
    private static final AttributeName ID_ATTRIBUTE_NAME = AttributeNames.forHTMLName("id");
    private static final AttributeName VALUE_ATTRIBUTE_NAME = AttributeNames.forHTMLName("value");
    private static final AttributeName CHECKED_ATTRIBUTE_NAME = AttributeNames.forHTMLName("checked");
    private static final AttributeName DISABLED_ATTRIBUTE_NAME = AttributeNames.forHTMLName("disabled");

    private ITemplateContext context;
    private IProcessableElementTag tag;
    private IElementTagStructureHandler structureHandler;
    private IThymeleafBindStatus bindStatus;
    private IModelFactory modelFactory;
    private IModel hiddenTagModel;
    private IStandaloneElementTag hiddenTag;

    private SpringInputCheckboxFieldTagProcessor processor;


    @BeforeEach
    void setUp() {
        this.context = mock(ITemplateContext.class);
        this.tag = mock(IProcessableElementTag.class);
        this.structureHandler = mock(IElementTagStructureHandler.class);
        this.bindStatus = mock(IThymeleafBindStatus.class);
        this.modelFactory = mock(IModelFactory.class);
        this.hiddenTagModel = mock(IModel.class);
        this.hiddenTag = mock(IStandaloneElementTag.class);

        when(this.context.getIdentifierSequences()).thenReturn(new IdentifierSequences());
        when(this.context.getModelFactory()).thenReturn(this.modelFactory);
        when(this.modelFactory.createModel()).thenReturn(this.hiddenTagModel);
        when(this.modelFactory.createStandaloneElementTag(
                eq("input"), anyMap(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true)))
                .thenReturn(this.hiddenTag);

        this.processor = new SpringInputCheckboxFieldTagProcessor("th");
        final AttributeDefinitions attributeDefinitions = new AttributeDefinitions(Collections.emptyMap());
        this.processor.setAttributeDefinitions(attributeDefinitions);
    }


    @Test
    void booleanTrueSetsCheckedValueAndInsertsHiddenMarkerImmediatelyAfterCheckbox() {
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).setAttribute("id", "notify-checkbox");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.structureHandler, never()).removeAttribute(any(AttributeName.class));
        verify(this.context, never()).getIdentifierSequences();

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals(Map.of("type", "hidden", "name", "_notify", "value", "on"), attributesCaptor.getValue());

        verify(this.hiddenTagModel).add(same(this.hiddenTag));
        verify(this.structureHandler).insertImmediatelyAfter(same(this.hiddenTagModel), eq(false));
        verify(this.structureHandler, never()).insertBefore(any(IModel.class));
    }


    @Test
    void primitiveFalseRemovesCheckedAndStillAddsHiddenMarker() {
        bind("notify", Boolean.FALSE, boolean.class);

        process();

        verify(this.structureHandler).setAttribute("id", "notify1");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).removeAttribute(CHECKED_ATTRIBUTE_NAME);
        verify(this.structureHandler, never()).setAttribute(eq("checked"), anyString());

        verify(this.hiddenTagModel).add(same(this.hiddenTag));
        verify(this.structureHandler).insertImmediatelyAfter(same(this.hiddenTagModel), eq(false));
    }


    @Test
    void stringBoundValueIsConvertedForBooleanBinding() {
        bind("notify", "true", Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.structureHandler, never()).removeAttribute(any(AttributeName.class));
    }


    @Test
    void lowercaseFalseStringIsConvertedToUncheckedBoolean() {
        bind("notify", "false", Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).removeAttribute(CHECKED_ATTRIBUTE_NAME);
        verify(this.structureHandler, never()).setAttribute(eq("checked"), anyString());
    }


    @Test
    void nullBooleanBoundValueIsTreatedAsUnchecked() {
        bind("notify", null, Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).removeAttribute(CHECKED_ATTRIBUTE_NAME);
        verify(this.hiddenTagModel).add(same(this.hiddenTag));
    }


    @Test
    void nonBooleanMatchingValueIsSelectedAndKeepsOriginalTagValue() {
        bind("flavour", "A&B", String.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("flavour-checkbox");
        when(this.tag.getAttributeValue(VALUE_ATTRIBUTE_NAME)).thenReturn("A&amp;B");

        process();

        verify(this.structureHandler).setAttribute("id", "flavour-checkbox");
        verify(this.structureHandler).setAttribute("name", "flavour");
        verify(this.structureHandler).setAttribute("value", "A&amp;B");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.structureHandler, never()).removeAttribute(any(AttributeName.class));
    }


    @Test
    void nonBooleanNonMatchingValueIsNotSelected() {
        bind("flavour", "vanilla", String.class);
        when(this.tag.getAttributeValue(VALUE_ATTRIBUTE_NAME)).thenReturn("chocolate");

        process();

        verify(this.structureHandler).setAttribute("value", "chocolate");
        verify(this.structureHandler).removeAttribute(CHECKED_ATTRIBUTE_NAME);
        verify(this.structureHandler, never()).setAttribute(eq("checked"), anyString());
    }


    @Test
    void nonBooleanBindingWithoutValueAttributeFailsBeforeChangingStructure() {
        bind("flavour", "vanilla", String.class);

        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, this::process);

        assertEquals(
                "Attribute \"value\" is required in \"input(checkbox)\" tags when binding to non-boolean values",
                exception.getMessage());
        verify(this.structureHandler, never()).setAttribute(anyString(), anyString());
        verify(this.structureHandler, never()).removeAttribute(any(AttributeName.class));
        verify(this.context, never()).getModelFactory();
        verifyNoInteractions(this.modelFactory);
    }


    @Test
    void disabledCheckboxGetsFieldAttributesButNoHiddenMarker() {
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("disabled-checkbox");
        when(this.tag.hasAttribute(DISABLED_ATTRIBUTE_NAME)).thenReturn(true);

        process();

        verify(this.structureHandler).setAttribute("id", "disabled-checkbox");
        verify(this.structureHandler).setAttribute("name", "notify");
        verify(this.structureHandler).setAttribute("value", "true");
        verify(this.structureHandler).setAttribute("checked", "checked");
        verify(this.context, never()).getModelFactory();
        verifyNoInteractions(this.modelFactory);
        verify(this.structureHandler, never()).insertBefore(any(IModel.class));
        verify(this.structureHandler, never()).insertImmediatelyAfter(any(IModel.class), eq(false));
    }


    @Test
    void hiddenMarkerCanBeInsertedBeforeCheckbox() {
        this.processor = new SpringInputCheckboxFieldTagProcessor("th", true);
        this.processor.setAttributeDefinitions(new AttributeDefinitions(Collections.emptyMap()));
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).insertBefore(same(this.hiddenTagModel));
        verify(this.structureHandler, never()).insertImmediatelyAfter(any(IModel.class), eq(false));
    }


    @Test
    void generatedIdentifiersUseFieldNameAndIncrementForEachOccurrence() {
        bind("user[name]", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("   ");

        process();
        process();

        final ArgumentCaptor<String> idCaptor = ArgumentCaptor.forClass(String.class);
        verify(this.structureHandler, times(2)).setAttribute(eq("id"), idCaptor.capture());
        assertEquals(List.of("username1", "username2"), idCaptor.getAllValues());
        verify(this.structureHandler, times(2)).setAttribute("name", "user[name]");
    }


    @Test
    void nullExpressionUsesEmptyNameAndGeneratedIdentifier() {
        bind(null, Boolean.TRUE, Boolean.class);

        process();

        verify(this.structureHandler).setAttribute("id", "1");
        verify(this.structureHandler).setAttribute("name", "");

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals("_", attributesCaptor.getValue().get("name"));
    }


    @Test
    void requestDataValueProcessorProcessesVisibleAndHiddenFieldValues() {
        final IThymeleafRequestContext requestContext = mock(IThymeleafRequestContext.class);
        final IThymeleafRequestDataValueProcessor requestDataValueProcessor =
                mock(IThymeleafRequestDataValueProcessor.class);
        when(this.context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT))
                .thenReturn(requestContext);
        when(requestContext.getRequestDataValueProcessor()).thenReturn(requestDataValueProcessor);
        when(requestDataValueProcessor.processFormFieldValue("notify", "true", "checkbox"))
                .thenReturn("processed-visible-value");
        when(requestDataValueProcessor.processFormFieldValue("_notify", "on", "hidden"))
                .thenReturn("processed-hidden-value");
        bind("notify", Boolean.TRUE, Boolean.class);
        when(this.tag.getAttributeValue(ID_ATTRIBUTE_NAME)).thenReturn("notify-checkbox");

        process();

        verify(this.structureHandler).setAttribute("value", "processed-visible-value");

        @SuppressWarnings("unchecked")
        final ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(this.modelFactory).createStandaloneElementTag(
                eq("input"), attributesCaptor.capture(), eq(AttributeValueQuotes.DOUBLE), eq(false), eq(true));
        assertEquals("processed-hidden-value", attributesCaptor.getValue().get("value"));
        verify(requestDataValueProcessor).processFormFieldValue("notify", "true", "checkbox");
        verify(requestDataValueProcessor).processFormFieldValue("_notify", "on", "hidden");
    }


    private void bind(final String expression, final Object value, final Class<?> valueType) {
        when(this.bindStatus.getExpression()).thenReturn(expression);
        when(this.bindStatus.getValue()).thenReturn(value);
        doReturn(valueType).when(this.bindStatus).getValueType();
    }


    private void process() {
        this.processor.doProcess(
                this.context,
                this.tag,
                FIELD_ATTRIBUTE_NAME,
                "*{field}",
                this.bindStatus,
                this.structureHandler);
    }

