package org.thymeleaf.spring6.util;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.thymeleaf.exceptions.TemplateProcessingException;
import org.thymeleaf.web.IWebRequest;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SpringRequestUtilsCheckViewNameNotInRequestTests {

    private static final String DANGEROUS_VIEW_NAME_MESSAGE =
            "View name contains an expression and so does either the URL path or the request parameters " +
            "or contents. This is forbidden in order to reduce the possibilities that direct user input " +
            "is executed as a part of the view name.";


    @Test
    void doesNothingWhenViewNameContainsNoExpressionEvenIfRequestIsDangerous() {

        final StubWebRequest request = new StubWebRequest(
                "/app/%24%7Buser%7D",
                Map.of("q", new String[] {"${username}"}),
                Map.of("session", new String[] {"#{token}"}),
                Map.of("accept", new String[] {"@{/admin}"}));

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("views/home", request));
    }


    @ParameterizedTest
    @ValueSource(strings = {
            "home",
            "views/home",
            "$value",
            "*value",
            "#value",
            "@value",
            "~value",
            "|only-one-pipe",
            "_only_one_underscore_",
            "a $ b * c # d @ e ~ f"
    })
    void doesNothingWhenViewNameMerelyResemblesAnExpression(final String viewName) {

        final StubWebRequest request = new StubWebRequest(
                "/app/${user}",
                Map.of("q", new String[] {"*{user}"}),
                Map.of("session", new String[] {"#{user}"}),
                Map.of("accept", new String[] {"@{/user}"}));

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest(viewName, request));
    }


    @Test
    void doesNothingWhenOnlyViewNameContainsAnExpressionAndRequestDataIsClean() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Collections.emptyMap(),
                Collections.emptyMap(),
                Collections.emptyMap());

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void doesNothingWhenOnlyViewNameContainsAnExpressionAndRequestMapsAreNull() {

        final StubWebRequest request = new StubWebRequest("/app/user/42", null, null, null);

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void throwsWhenViewNameAndPathBothContainExpressions() {

        final StubWebRequest request = cleanRequest("/app/users/${userId}");

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/${userId}", request));

        assertEquals(DANGEROUS_VIEW_NAME_MESSAGE, exception.getMessage());
    }


    @Test
    void throwsWhenEncodedPathContainsAnExpression() {

        final StubWebRequest request = cleanRequest("/app/users/%24%7BuserId%7D");

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/${userId}", request));

        assertEquals(DANGEROUS_VIEW_NAME_MESSAGE, exception.getMessage());
    }


    @Test
    void throwsWhenPathContainsAnExpressionEvenIfItIsNotPresentInViewName() {

        final StubWebRequest request = cleanRequest("/app/${otherValue}");

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));

        assertEquals(DANGEROUS_VIEW_NAME_MESSAGE, exception.getMessage());
    }


    @ParameterizedTest
    @ValueSource(strings = {
            "${value}",
            "*{value}",
            "#{value}",
            "@{value}",
            "~{value}",
            "__value__",
            "|value|"
    })
    void throwsWhenAContainedParameterValueContainsAnyThymeleafExpression(final String expression) {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Map.of("q", new String[] {expression}),
                Collections.emptyMap(),
                Collections.emptyMap());

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("views/detail/" + expression, request));

        assertEquals(DANGEROUS_VIEW_NAME_MESSAGE, exception.getMessage());
    }


    @Test
    void throwsWhenContainedParameterValueIsFoundInALaterEntry() {

        final Map<String, String[]> parameters = new LinkedHashMap<>();
        parameters.put("safe", new String[] {"plain text", "${notInViewName}"});
        parameters.put("dangerous", new String[] {"${username}"});

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42", parameters, Collections.emptyMap(), Collections.emptyMap());

        assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void doesNothingWhenParameterContainsExpressionThatIsNotContainedInViewName() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Map.of("q", new String[] {"${otherValue}"}),
                Collections.emptyMap(),
                Collections.emptyMap());

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void parameterMatchingIsCaseInsensitiveAndIgnoresWhitespace() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Map.of("q", new String[] {"  ${UserName}  "}),
                Collections.emptyMap(),
                Collections.emptyMap());

        assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("Views/${username}", request));
    }


    @Test
    void throwsWhenAContainedCookieValueContainsAnExpression() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Collections.emptyMap(),
                Map.of("session", new String[] {"plain", "${username}"}),
                Collections.emptyMap());

        assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void doesNothingWhenCookieContainsExpressionThatIsNotContainedInViewName() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Collections.emptyMap(),
                Map.of("session", new String[] {"#{otherValue}"}),
                Collections.emptyMap());

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void throwsWhenAContainedHeaderValueContainsAnExpression() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Collections.emptyMap(),
                Collections.emptyMap(),
                Map.of("X-Preferred-View", new String[] {"plain", "@{/users/${username}}" }));

        assertThrows(
                TemplateProcessingException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest("users/@{/users/${username}}", request));
    }


    @Test
    void doesNothingWhenHeaderContainsExpressionThatIsNotContainedInViewName() {

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                Collections.emptyMap(),
                Collections.emptyMap(),
                Map.of("X-Preferred-View", new String[] {"~{other-template}"}));

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void skipsNullArraysAndNullValuesInParameterCookieAndHeaderMaps() {

        final Map<String, String[]> dangerousValuesWithNulls = new LinkedHashMap<>();
        dangerousValuesWithNulls.put("null-array", null);
        dangerousValuesWithNulls.put("null-value", new String[] {null});
        dangerousValuesWithNulls.put("empty-values", new String[0]);

        final StubWebRequest request = new StubWebRequest(
                "/app/user/42",
                dangerousValuesWithNulls,
                dangerousValuesWithNulls,
                dangerousValuesWithNulls);

        assertDoesNotThrow(() ->
                SpringRequestUtils.checkViewNameNotInRequest("users/${username}", request));
    }


    @Test
    void rejectsNullViewName() {

        final StubWebRequest request = cleanRequest("/app/user/42");

        assertThrows(
                NullPointerException.class,
                () -> SpringRequestUtils.checkViewNameNotInRequest(null, request));
    }


    private static StubWebRequest cleanRequest(final String pathWithinApplication) {
        return new StubWebRequest(
                pathWithinApplication,
                Collections.emptyMap(),
                Collections.emptyMap(),
                Collections.emptyMap());
    }


    private static final class StubWebRequest implements IWebRequest {

        private final String pathWithinApplication;
        private final Map<String, String[]> parameterMap;
        private final Map<String, String[]> cookieMap;
        private final Map<String, String[]> headerMap;

        private StubWebRequest(
                final String pathWithinApplication,
                final Map<String, String[]> parameterMap,
                final Map<String, String[]> cookieMap,
                final Map<String, String[]> headerMap) {
            this.pathWithinApplication = pathWithinApplication;
