package org.thymeleaf.spring6.util;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.EmptySource;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Tests for {@link SpringStandardExpressionUtils#containsExternalAccess(String)}.
 *
 * <p>
 *   The method is a lexical detector used in restricted mode: it returns {@code true} when the (normalized)
 *   expression contains an object instantiation ({@code new ...}), a static method invocation marker
 *   ({@code T(...)}), a {@code param} access, or a {@code @}-prefixed (bean / link) reference.
 * </p>
 */
@DisplayName("SpringStandardExpressionUtils.containsExternalAccess")
public class SpringStandardExpressionUtilsContainsExternalAccessTests {


    @Nested
    @DisplayName("Expressions without external access")
    class InnocentExpressions {

        @ParameterizedTest(name = "[{index}] \"{0}\" is not flagged")
        @ValueSource(strings = {
                "hello",
                "${user.name}",
                "${1 + 2}",
                "user.name",
                "${#strings.toUpperCase(x)}",
                "${x > 4 and y < 3}",
                "th:if",
                "${list.isEmpty()}",
                "some text with spaces"
        })
        void plainExpressionsAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @Test
        @DisplayName("Empty expression is not flagged")
        void emptyExpressionIsNotFlagged() {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(""));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" is blank but not flagged")
        @ValueSource(strings = {" ", "\t", "\n", "\r\n", "\t\n ", "   \t \n  "})
        void blankExpressionsAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] single char \"{0}\" is not flagged")
        @ValueSource(strings = {"@", "(", "T", "t", "n", "w", "$", "."})
        void singleCharactersAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @Test
        @DisplayName("Very long harmless expression is not flagged")
        void longHarmlessExpressionIsNotFlagged() {
            final String expression = "abcdefghij".repeat(1000);
            assertEquals(10000, expression.length());
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

    }


    @Nested
    @DisplayName("Object instantiation (\"new\")")
    class ObjectInstantiation {

        @ParameterizedTest(name = "[{index}] \"{0}\" contains an instantiation")
        @ValueSource(strings = {
                "new ",
                "new\t",
                "new\n",
                "new Foo()",
                "${new Foo()}",
                "${new java.lang.Object()}",
                "${ new java.lang.Object() }",
                "a new X",
                "(new X)",
                "New Object()",
                "nEw X",
                "brand new day",
                "new )",
                "${new Foo()} ${other}"
        })
        void instantiationsAreFlagged(final String expression) {
            assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" does not contain an instantiation")
        @ValueSource(strings = {
                // the keyword needs some whitespace after it, otherwise it is part of a larger token
                "new",
                " new",
                "newX",
                "new${x}",
                "new'x'",
                "new\"x\"",
                "new)",
                "new.",
                "new,Foo()",
                "new;Foo()",
                // non-breaking space is not whitespace for Character.isWhitespace(char)
                "new\u00a0X",
                // the keyword cannot be part of a larger identifier
                "renew X",
                "xnew X",
                "enew X",
                "neww X",
                "ne\tw X",
                "n e w X"
        })
        void lookalikesAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @Test
        @DisplayName("Keyword split by a control character is glued back together by normalization")
        void controlCharactersAreIgnored() {
            assertAll(
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess("\u0001new Foo()")),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess("\u007fnew Foo()")),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess("\u009fnew Foo()")));
        }

    }


    @Nested
    @DisplayName("Static method marker (\"T(...)\")")
    class StaticMethodMarker {

        @ParameterizedTest(name = "[{index}] \"{0}\" contains a static marker")
        @ValueSource(strings = {
                "T()",
                "${T(java.lang.Runtime).getRuntime()}",
                "${T (java.lang.Runtime)}",
                "t(",
                "t (",
                " T(",
                "a.t(",
                "t\t(",
                "t\n(",
                "t t (",
                "${T((x))}"
        })
        void staticMarkersAreFlagged(final String expression) {
            assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" does not contain a static marker")
        @ValueSource(strings = {
                "T",
                "(",
                "tt(",
                "tt (",
                "xT(",
                "xt(",
                "T/*x*/(",
                "${T}",
                "${T}(",
                "${T.class}",
                // non-breaking space is not whitespace for Character.isWhitespace(char)
                "t\u00a0("
        })
        void lookalikesAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

    }


    @Nested
    @DisplayName("\"param\" access")
    class ParamAccess {

        @ParameterizedTest(name = "[{index}] \"{0}\" contains a param access")
        @ValueSource(strings = {
                "param ",
                " param ",
                "param\t",
                "param(",
                "${param.x}",
                "${param}",
                "${ param.x }",
                "x.param.y",
                "param param"
        })
        void paramAccessesAreFlagged(final String expression) {
            assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" does not contain a param access")
        @ValueSource(strings = {
                "param",
                " param",
                "paramx",
                "param1",
                "xparam",
                "xparam(",
                "myparam",
                "${xparam.y}"
        })
        void lookalikesAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

    }


    @Nested
    @DisplayName("Bean and link references (\"@\")")
    class BeanReferences {

        @ParameterizedTest(name = "[{index}] \"{0}\" contains a bean reference")
        @ValueSource(strings = {
                "@bean",
                "@b",
                " @b",
                "@1",
                "@_x",
                "a.@b",
                "x/@bean",
                "${@bean.doSomething()}",
                "${{@bean}}",
                "@{/path(x=@bean)}"
        })
        void beanReferencesAreFlagged(final String expression) {
            assertTrue(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" does not contain a bean reference")
        @ValueSource(strings = {
                "@",
                "@ ",
                " @",
                "abc@",
                "a@b",
                "@ bean",
                "@${x}",
                "@{/path}",
                "@{/path(x=1)}",
                "${'@'}"
        })
        void lookalikesAreNotFlagged(final String expression) {
            assertFalse(SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

    }


    @Nested
    @DisplayName("Combined and case handling")
    class CombinedAndCaseHandling {

        @Test
        @DisplayName("Several forbidden constructs in the same expression are flagged")
        void combinedExpressionsAreFlagged() {
            assertAll(
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(
                            "${new X()} + ${T(Y).z()}")),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(
                            "${@bean.call(new Foo())}")),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(
                            "${param.x} == ${T(java.lang.Math)#abs(-1)}")));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" -> {1}")
        @CsvSource({
                "new Object(), true",
                "NEW OBJECT(), true",
                "nEw ObJeCt(), true",
                "T(java.lang.Runtime), true",
                "t(JAVA.LANG.RUNTIME), true",
                "@bean, true",
                "@BEAN, true",
                "PARAM(, true",
                "new object(), true",
                "NEWOBJECT(), false",
                "XNEW Y, false",
                "T (java.lang.Runtime), true",
                "TT(, false",
                "USER.NAME, false"
        })
        void detectionIsCaseInsensitive(final String expression, final boolean expected) {
            assertEquals(expected, SpringStandardExpressionUtils.containsExternalAccess(expression));
        }

        @ParameterizedTest(name = "[{index}] \"{0}\" and its lowercase form give the same result")
        @ValueSource(strings = {"NEW FOO()", "T(JAVA.LANG.MATH)", "@BEAN", "PARAM.X", "RENEW X", "NEWX"})
        void upperAndLowercaseFormsAgree(final String upperCaseExpression) {
            final String lowerCaseExpression = upperCaseExpression.toLowerCase(java.util.Locale.ROOT);
            assertEquals(
                    SpringStandardExpressionUtils.containsExternalAccess(lowerCaseExpression),
                    SpringStandardExpressionUtils.containsExternalAccess(upperCaseExpression));
        }

        @Test
        @DisplayName("Detection does not depend on invocation order or repetition")
        void resultIsStableAcrossInvocations() {
            final String dangerous = "${new Foo()}";
            final String harmless = "${foo.bar}";
            assertAll(
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(dangerous)),
                    () -> assertFalse(SpringStandardExpressionUtils.containsExternalAccess(harmless)),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(dangerous)),
                    () -> assertFalse(SpringStandardExpressionUtils.containsExternalAccess(harmless)),
                    () -> assertTrue(SpringStandardExpressionUtils.containsExternalAccess(dangerous)));
        }

    }


    @Nested
    @DisplayName("Invalid input")
    class InvalidInput {

        @Test
        @DisplayName("A null expression raises a NullPointerException")
        void nullExpressionThrowsNullPointerException() {
