private static <T> T newProxy(final Class<T> iface, final Object... nameValuePairs) {
    final Map<String,Object> values = new HashMap<>();
    for (int i=0;i<nameValuePairs.length;i+=2) values.put((String)nameValuePairs[i], nameValuePairs[i+1]);
    return iface.cast(Proxy.newProxyInstance(
        iface.getClassLoader(), new Class<?>[]{iface},
        (proxy, method, args) -> {
            final String m = method.getName();
            if ("toString".equals(m)) return iface.getSimpleName() + "Stub";
            if ("hashCode".equals(m)) return System.identityHashCode(proxy);
            if ("equals".equals(m)) return proxy == args[0];
            if (values.containsKey(m)) return values.get(m);
            final Class<?> rt = method.getReturnType();
            if (rt == boolean.class) return Boolean.FALSE;
            if (rt == int.class) return Integer.valueOf(0);
            if (rt == long.class) return Long.valueOf(0L);
            if (rt == double.class) return Double.valueOf(0d);
            if (rt == float.class) return Float.valueOf(0f);
            if (rt == short.class) return Short.valueOf((short)0);
            if (rt == byte.class) return Byte.valueOf((byte)0);
            if (rt == char.class) return Character.valueOf('\0');
            return null;
        }));
}
```

