    @Test
    public void testBuildWithNullDialectConfigurationSet() {

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> DialectSetConfiguration.build(null));

        assertEquals("Dialect configuration set cannot be null", exception.getMessage());

    }


    @Test
    public void testBuildWithEmptyDialectConfigurationSet() {

        final Set<DialectConfiguration> configurations = new LinkedHashSet<DialectConfiguration>();

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations);

        assertNotNull(configuration.getDialectConfigurations());
        assertTrue(configuration.getDialectConfigurations().isEmpty());
        assertNotSame(configurations, configuration.getDialectConfigurations());

        assertNotNull(configuration.getDialects());
        assertTrue(configuration.getDialects().isEmpty());

        assertFalse(configuration.isStandardDialectPresent());
        assertNull(configuration.getStandardDialectPrefix());

        assertNotNull(configuration.getExecutionAttributes());
        assertTrue(configuration.getExecutionAttributes().isEmpty());
        assertFalse(configuration.hasExecutionAttribute("anyAttribute"));
        assertNull(configuration.getExecutionAttribute("anyAttribute"));

        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());

        final IExpressionObjectFactory expressionObjectFactory = configuration.getExpressionObjectFactory();
        assertNotNull(expressionObjectFactory);
        assertNull(expressionObjectFactory.getAllExpressionObjectNames());
        assertNull(expressionObjectFactory.buildObject(null, "anyObject"));
        assertFalse(expressionObjectFactory.isCacheable("anyObject"));

        for (final TemplateMode templateMode : ALL_TEMPLATE_MODES) {
            assertTrue(configuration.getTemplateBoundariesProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCDATASectionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCommentProcessors(templateMode).isEmpty());
            assertTrue(configuration.getDocTypeProcessors(templateMode).isEmpty());
            assertTrue(configuration.getElementProcessors(templateMode).isEmpty());
            assertTrue(configuration.getProcessingInstructionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getTextProcessors(templateMode).isEmpty());
            assertTrue(configuration.getXMLDeclarationProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPreProcessors(templateMode).isEmpty());
            assertTrue(configuration.getPostProcessors(templateMode).isEmpty());
        }

    }


    @Test
    public void testProcessorAndPrePostProcessorGettersDoNotAcceptNullTemplateMode() {

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(new LinkedHashSet<DialectConfiguration>());

        final List<Consumer<TemplateMode>> getters = new ArrayList<Consumer<TemplateMode>>();
        getters.add(configuration::getTemplateBoundariesProcessors);
        getters.add(configuration::getCDATASectionProcessors);
        getters.add(configuration::getCommentProcessors);
        getters.add(configuration::getDocTypeProcessors);
        getters.add(configuration::getElementProcessors);
        getters.add(configuration::getProcessingInstructionProcessors);
        getters.add(configuration::getTextProcessors);
        getters.add(configuration::getXMLDeclarationProcessors);
        getters.add(configuration::getPreProcessors);
        getters.add(configuration::getPostProcessors);

        for (final Consumer<TemplateMode> getter : getters) {
            final IllegalArgumentException exception =
                    assertThrows(IllegalArgumentException.class, () -> getter.accept(null));
            assertEquals("Template mode cannot be null", exception.getMessage());
        }

    }


