        final TestPlainDialect firstDialect = new TestPlainDialect("first");
        final TestPlainDialect secondDialect = new TestPlainDialect("second");

        final Set<DialectConfiguration> configurations = configurations(
                new DialectConfiguration(firstDialect),
                new DialectConfiguration("prefix", secondDialect));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations);

        assertNotSame(configurations, configuration.getDialectConfigurations());
        assertEquals(configurations, configuration.getDialectConfigurations());
        assertEquals(
                Arrays.asList(firstDialect, secondDialect),
                new ArrayList<IDialect>(configuration.getDialects()));
        assertEquals(2, configuration.getDialects().size());

