        final TestTextProcessor precedence10 = new TestTextProcessor(TemplateMode.HTML, 10);
        final TestTextProcessor precedence20 = new TestTextProcessor(TemplateMode.HTML, 20);

        // Deliberately unsorted insertion order
        final TestProcessorDialect dialect = new TestProcessorDialect(
