        final TestProcessorDialect lowDialectPrecedence =
                new TestProcessorDialect("low", 5, processors(processorOfLowDialectPrecedence));
        final TestProcessorDialect highDialectPrecedence =
                new TestProcessorDialect("high", 20, processors(processorOfHighDialectPrecedence));

        // The dialect with the highest dialect precedence is added first, so insertion order is not the expected one
        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(highDialectPrecedence),
