package org.thymeleaf.context;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.thymeleaf.IEngineConfiguration;
import org.thymeleaf.engine.TemplateData;
import org.thymeleaf.inline.IInliner;
import org.thymeleaf.model.ICDATASection;
import org.thymeleaf.model.IComment;
import org.thymeleaf.model.IText;
import org.thymeleaf.templatemode.TemplateMode;

class EngineContextGetStringRepresentationByLevelTests {

    @Test
    void emptyContextShowsRootLevelAndTemplateData() {
        final EngineContext context = createContext(null);

        assertEquals("{0:{}(template)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void emptyVariablesMapAlsoShowsRootLevelAndTemplateData() {
        final EngineContext context = createContext(Collections.<String, Object>emptyMap());

        assertEquals("{0:{}(template)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void rootVariablesAreSortedByNameAndPreserveNullValues() {
        final Map<String, Object> variables = new LinkedHashMap<String, Object>();
        variables.put("zeta", Boolean.TRUE);
        variables.put("alpha", Integer.valueOf(1));
        variables.put("beta", null);

        final EngineContext context = createContext(variables);

        assertEquals(
                "{0:{alpha=1,beta=null,zeta=true}(template)}[0]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void variablesAreGroupedByLevelAndLevelsAreShownFromInnermostToRoot() {
        final EngineContext context = createContext(Collections.<String, Object>singletonMap("root", "R"));
        context.increaseLevel();
        context.setVariable("z", Integer.valueOf(2));
        context.setVariable("a", Integer.valueOf(1));

        assertEquals(
                "{1:{a=1,z=2},0:{root=R}(template)}[1]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void removalAtNestedLevelIsShownWhenItRemovesALowerLevelVariable() {
        final EngineContext context = createContext(Collections.<String, Object>singletonMap("root", "R"));
        context.increaseLevel();
        context.setVariable("shared", "level1");
        context.increaseLevel();
        context.setVariable("fromLevel2", Integer.valueOf(3));
        context.removeVariable("shared");

        assertEquals(
                "{2:{fromLevel2=3,shared=(*removed*)},1:{shared=level1},0:{root=R}(template)}[2]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void levelContainingOnlyAnIneffectiveRemovalIsOmitted() {
        final EngineContext context = createContext(Collections.<String, Object>singletonMap("root", "R"));
        context.increaseLevel();
        context.setVariable("temporary", Integer.valueOf(1));
        context.removeVariable("temporary");

        assertEquals("{0:{root=R}(template)}[1]", context.getStringRepresentationByLevel());
    }

    @Test
    void removalAtRootActuallyRemovesTheVariable() {
        final EngineContext context = createContext(null);
        context.setVariable("removed", "value");
        context.removeVariable("removed");

        assertEquals("{0:{}(template)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void metadataAtRootIsAppendedAfterVariablesInDocumentedOrder() {
        final EngineContext context = createContext(null);
        context.setSelectionTarget("user");
        context.setInliner(new NamedInliner("INLINE"));
        context.setTemplateData(templateData("other"));

        assertEquals(
                "{0:{}<user>[INLINE](other)}[0]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void metadataAtNestedLevelCausesAnOtherwiseEmptyLevelToBeShown() {
        final EngineContext context = createContext(null);
        context.increaseLevel();
        context.setSelectionTarget("nested");

        assertEquals(
                "{1:<nested>,0:{}(template)}[1]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void explicitNullSelectionTargetIsRepresentedAsNull() {
        final EngineContext context = createContext(null);
        context.setSelectionTarget(null);

        assertEquals("{0:{}<null>(template)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void disabledInlinerUsesTheNoOpSentinelInTheRepresentation() {
        final EngineContext context = createContext(null);
        context.setInliner(null);

        assertEquals("{0:{}[NOOP](template)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void emptyIntermediateLevelsAreNotShownButCurrentLevelIsReported() {
        final EngineContext context = createContext(null);
        context.increaseLevel();
        context.increaseLevel();

        assertEquals("{0:{}(template)}[2]", context.getStringRepresentationByLevel());
    }

    @Test
    void contextWithoutTemplateDataStillShowsTheRootLevelMap() {
        final EngineContext context = new EngineContext(
                mock(IEngineConfiguration.class), null, null, Locale.ENGLISH, null);

        assertEquals("{0:{}}[0]", context.getStringRepresentationByLevel());
    }

    private static EngineContext createContext(final Map<String, Object> variables) {
        return new EngineContext(
                mock(IEngineConfiguration.class),
                templateData("template"),
                null,
                Locale.ENGLISH,
                variables);
    }

    private static TemplateData templateData(final String template) {
        return new TemplateData(template, null, null, TemplateMode.HTML, null);
    }

    private static final class NamedInliner implements IInliner {

        private final String name;

        private NamedInliner(final String name) {
            this.name = name;
        }

        @Override
        public String getName() {
            return this.name;
        }

        @Override
        public CharSequence inline(final ITemplateContext context, final IText text) {
            return text;
        }

        @Override
        public CharSequence inline(final ITemplateContext context, final ICDATASection cdataSection) {
            return cdataSection;
        }

        @Override
        public CharSequence inline(final ITemplateContext context, final IComment comment) {
            return comment;
        }
    }
}
