class WebEngineContextGetStringRepresentationByLevelTests {

    @Test
    void representsEmptyContextAtLevelZeroWithTemplateData() {
        final RecordingWebExchange exchange = new RecordingWebExchange();
        final WebEngineContext context = context(exchange, null, "base");

        assertEquals("{0:{}(base)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void representsRequestAttributesAtLevelZeroInInsertionOrder() {
        final Map<String, Object> variables = new LinkedHashMap<>();
        variables.put("first", 1);
        variables.put("second", 2);

