        assertEquals("{0:{first=1, second=2}(base)}[0]", context.getStringRepresentationByLevel());
    }

    @Test
    void representsOneLevelOfChangesAndRestoresRequestAttributesAtRootLevel() {
        final Map<String, Object> variables = new LinkedHashMap<>();
        variables.put("a", 1);
        variables.put("b", 2);
        final WebEngineContext context = context(new RecordingWebExchange(), variables, "base");

        context.increaseLevel();
        context.setVariable("a", 10);
        context.setVariable("c", 3);

        assertEquals(
                "{1:{a=10, c=3},0:{a=1, b=2}(base)}[1]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void collapsesChangesAcrossNestedLevelsAndKeepsLayerOrder() {
        final Map<String, Object> variables = new LinkedHashMap<>();
        variables.put("a", 0);
        variables.put("b", "B");
        final WebEngineContext context = context(new RecordingWebExchange(), variables, "base");

        context.increaseLevel();
        context.setVariable("a", 1);
        context.increaseLevel();
        context.setVariable("a", 2);
        context.setVariable("c", true);

        assertEquals(
                "{2:{a=2, c=true},1:{a=1},0:{a=0, b=B}(base)}[2]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void ignoresNoOpVariableAssignments() {
        final Map<String, Object> variables = new LinkedHashMap<>();
        variables.put("a", 1);
        final WebEngineContext context = context(new RecordingWebExchange(), variables, "base");

        context.increaseLevel();
        context.setVariable("a", 1);

        assertEquals("{0:{a=1}(base)}[1]", context.getStringRepresentationByLevel());
    }

    @Test
