    private IteratedGatheringModelProcessable create(final Object iteratedObject) {
        return create(iteratedObject, null, SkipBody.PROCESS, false);
    }


    private IteratedGatheringModelProcessable create(
            final Object iteratedObject,
            final Text precedingWhitespace,
            final SkipBody skipBody,
            final boolean skipCloseTag) {
        return new IteratedGatheringModelProcessable(
                this.configuration,
                this.processorTemplateHandler,
                this.context,
                this.modelController,
                this.flowController,
                skipBody,
                skipCloseTag,
                new ProcessorExecutionVars(),
                ITER_VAR,
                STATUS_VAR,
                iteratedObject,
                precedingWhitespace);
    }


    private static void gatherTexts(final IteratedGatheringModelProcessable processable, final String... texts) {
        for (final String text : texts) {
            processable.gatherText(new Text(text));
        }
    }


    private SetVariableRecorder recordSetVariables() {
        final SetVariableRecorder recorder = new SetVariableRecorder();
        doAnswer(recorder).when(this.context).setVariable(anyString(), any());
        return recorder;
    }


    private List<String> captureHandledTexts() {
        final List<String> handledTexts = new ArrayList<String>();
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(final InvocationOnMock invocation) {
                handledTexts.add(((IText) invocation.getArgument(0)).getText());
                return null;
            }
        }).when(this.processorTemplateHandler).handleText(any(IText.class));
        return handledTexts;
    }


    private static final class SetVariableRecorder implements Answer<Void> {

        private final List<String> names = new ArrayList<String>();
        private final List<Object> iterValues = new ArrayList<Object>();
        private final List<Integer> statusIndexes = new ArrayList<Integer>();
        private final List<Object> statusCurrents = new ArrayList<Object>();
        private final List<Integer> statusSizes = new ArrayList<Integer>();

        @Override
        public Void answer(final InvocationOnMock invocation) {
            final String name = invocation.getArgument(0);
            final Object value = invocation.getArgument(1);
            this.names.add(name);
            if (ITER_VAR.equals(name)) {
                this.iterValues.add(value);
            } else if (STATUS_VAR.equals(name)) {
                final IterationStatusVar status = (IterationStatusVar) value;
                this.statusIndexes.add(Integer.valueOf(status.getIndex()));
                this.statusCurrents.add(status.getCurrent());
                this.statusSizes.add(status.getSize());
            }
            return null;
        }
    }

}
