        verify(this.context, never()).setVariable(anyString(), any());
        verify(this.processorTemplateHandler, never()).setCurrentGatheringModel(any(IGatheringModelProcessable.class));
        verify(this.processorTemplateHandler, never()).handleText(any(IText.class));
        verify(this.modelController, never()).skip(any(SkipBody.class), anyBoolean());
    }


