    private final StandardLinkBuilder builder = new StandardLinkBuilder();



    // ----------------------------------------------------------------------
    // Context / base argument validation
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("Null expression context is rejected with an IllegalArgumentException")
    public void testNullContextIsRejected() {
        final IllegalArgumentException ex = assertThrows(
                IllegalArgumentException.class,
                () -> this.builder.buildLink(null, "foo", null));
        assertEquals("Expression context cannot be null", ex.getMessage());
    }

    @Test
    @DisplayName("Null expression context is rejected even for a null link base")
    public void testNullContextIsRejectedBeforeNullBase() {
