    }

    @Test
    @DisplayName("A null link base produces a null link even when parameters are specified")
    public void testNullBaseWithParametersReturnsNull() {
        final Map<String, Object> parameters = new LinkedHashMap<>();
        parameters.put("a", "1");
        assertNull(this.builder.buildLink(new ExpressionContextStub(), null, parameters));
        assertEquals(1, parameters.size(), "Parameters must not be touched when base is null");
    }

    @Test
    @DisplayName("An empty link base is returned as an empty link")
    public void testEmptyBase() {
        assertEquals("", this.builder.buildLink(new ExpressionContextStub(), "", null));
    }



    // ----------------------------------------------------------------------
    // 'javascript:' filtering
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("'javascript:' links are forbidden")
    public void testJavaScriptLinksAreForbidden() {
        final TemplateProcessingException ex = assertThrows(
                TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "javascript:alert(1)", null));
        assertTrue(ex.getMessage().contains("'javascript:' is forbidden"),
                "Unexpected exception message: " + ex.getMessage());
    }

    @Test
    @DisplayName("'javascript:' detection is case insensitive")
    public void testJavaScriptLinksAreForbiddenCaseInsensitive() {
        assertThrows(TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "JAVASCRIPT:void(0)", null));
        assertThrows(TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "JavaScript:alert(1)", null));
    }

    @Test
    @DisplayName("'javascript' without the colon is a valid (base relative) link base")
    public void testJavaScriptWithoutColonIsAllowed() {
        assertEquals("javascript", this.builder.buildLink(new ExpressionContextStub(), "javascript", null));
        assertEquals("javascript:a", this.builder.buildLink(new ExpressionContextStub(),
                "javascript:a".substring(0, 10), null));
    }

    @Test
    @DisplayName("'javascript:' links are forbidden also in web contexts")
    public void testJavaScriptLinksAreForbiddenInWebContext() {
