        assertEquals("http://www.example.com/path?x=1",
                this.builder.buildLink(context, "http://www.example.com/path?x=1", null));
        assertEquals("https://www.example.com/", this.builder.buildLink(context, "https://www.example.com/", null));
        assertEquals("mailto:someone@example.com",
                this.builder.buildLink(context, "mailto:someone@example.com", null));
        assertEquals("MAILTO:someone@example.com",
                this.builder.buildLink(context, "MAILTO:someone@example.com", null));
    }

    @Test
    @DisplayName("Protocol-relative links ('//...') are considered absolute and returned unmodified")
    public void testProtocolRelativeLinks() {
        assertEquals("//cdn.example.com/lib.js", this.builder.buildLink(
                new ExpressionContextStub(), "//cdn.example.com/lib.js", null));
    }

    @Test
    @DisplayName("A one-character base is a base-relative link")
