        assertEquals("foo/bar", this.builder.buildLink(context, "foo/bar", null));
        assertEquals("../foo", this.builder.buildLink(context, "../foo", null));
        assertEquals("foo bar", this.builder.buildLink(context, "foo bar", null));
    }

    @Test
