        assertEquals("/foo/bar", this.builder.buildLink(context, "~/foo/bar", null));
        assertEquals("/", this.builder.buildLink(context, "~/", null));
    }

    @Test
    @DisplayName("Context-relative links are rejected when the context is not a web context")
    public void testContextRelativeLinkRequiresWebContext() {
