        assertEquals("Expression context cannot be null", ex.getMessage());
    }

    @Test
    @DisplayName("Null expression context is rejected even for a null link base")
    public void testNullContextIsRejectedBeforeNullBase() {
        assertThrows(IllegalArgumentException.class, () -> this.builder.buildLink(null, null, null));
    }

    @Test
    @DisplayName("A null link base produces a null link")
    public void testNullBaseReturnsNull() {
