    }

    @Test
    @DisplayName("A null link base produces a null link even when parameters are specified")
    public void testNullBaseWithParametersReturnsNull() {
        final Map<String, Object> parameters = new LinkedHashMap<>();
        parameters.put("a", "1");
        assertNull(this.builder.buildLink(new ExpressionContextStub(), null, parameters));
        assertEquals(1, parameters.size(), "Parameters must not be touched when base is null");
    }

    @Test
    @DisplayName("An empty link base is returned as an empty link")
