    // ----------------------------------------------------------------------

    @Test
    @DisplayName("'javascript:' links are forbidden")
    public void testJavaScriptLinksAreForbidden() {
        final TemplateProcessingException ex = assertThrows(
                TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "javascript:alert(1)", null));
        assertTrue(ex.getMessage().contains("'javascript:' is forbidden"),
                "Unexpected exception message: " + ex.getMessage());
    }

    @Test
    @DisplayName("'javascript:' detection is case insensitive")
    public void testJavaScriptLinksAreForbiddenCaseInsensitive() {
        assertThrows(TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "JAVASCRIPT:void(0)", null));
        assertThrows(TemplateProcessingException.class,
                () -> this.builder.buildLink(new ExpressionContextStub(), "JavaScript:alert(1)", null));
    }

    @Test
