    @Test
    @DisplayName("Non-String parameter values are converted with toString()")
    public void testNonStringParameterValues() {
        final Map<String, Object> parameters = new LinkedHashMap<>();
        parameters.put("n", Integer.valueOf(42));
        parameters.put("d", Double.valueOf(1.5));
        assertEquals("foo?n=42&d=1.5",
                this.builder.buildLink(new ExpressionContextStub(), "foo", parameters));
    }

    @Test
    @DisplayName("The parameters map received as an argument is not modified")
    public void testParametersMapIsDefensivelyCopied() {
        final Map<String, Object> parameters = new LinkedHashMap<>();
        parameters.put("var", "x");
        parameters.put("other", "y");

        assertEquals("foo/x?other=y", this.builder.buildLink(new ExpressionContextStub(), "foo/{var}", parameters));

        assertEquals(2, parameters.size());
        assertEquals("x", parameters.get("var"));
        assertEquals("y", parameters.get("other"));
