        assertEquals("foo?a=b&c=d#frag",
                this.builder.buildLink(new ExpressionContextStub(), "foo?a=b#frag", parameters));
        assertEquals("http://example.com/x?c=d#frag",
                this.builder.buildLink(new ExpressionContextStub(), "http://example.com/x#frag", parameters));
