    @Test
    @DisplayName("Resolves a message found in the only template of the stack")
    public void resolvesMessageFromSingleTemplateInStack() {

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true)), null, "greeting", null, true, true, true);

        assertEquals("Hello", result);
        assertEquals(Arrays.asList("home|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("Falls back to nested templates, in stack order, when the key is absent from parents")
    public void fallsBackToNestedTemplateWhenKeyNotFoundInParents() {

        this.resolver.putTemplateMessages("home", EN, messages("other", "Other"));
        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from fragment", result);
        // top-down traversal: "home" first, then "fragment"
        assertEquals(Arrays.asList("home|en", "fragment|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("The first (container) template in the stack overrides nested templates")
    public void firstTemplateInStackOverridesNestedTemplates() {

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello from container"));
        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from container", result);
        // nested template must not even be examined once the key is found
        assertEquals(Arrays.asList("home|en"), this.resolver.getTemplateInvocations());

    }


