    private static Map<String, String> messages(final String key, final String value) {
        final Map<String, String> messages = new HashMap<String, String>();
        messages.put(key, value);
        return messages;
    }


    private static TemplateData template(final String template, final boolean cacheable) {
        final ICacheEntryValidity validity = cacheable ?
                AlwaysValidCacheEntryValidity.INSTANCE : NonCacheableCacheEntryValidity.INSTANCE;
        return new TemplateData(
                template, (Set<String>) null, new StringTemplateResource("<html></html>"),
                TemplateMode.HTML, validity);
    }


    private static ITemplateContext context(final Locale locale, final TemplateData... templateStack) {
        return context(locale, Arrays.asList(templateStack));
    }


    private static ITemplateContext context(final Locale locale, final List<TemplateData> templateStack) {
        return (ITemplateContext) Proxy.newProxyInstance(
                ITemplateContext.class.getClassLoader(),
                new Class<?>[] {ITemplateContext.class},
                (proxy, method, args) -> {
                    if ("getLocale".equals(method.getName())) {
                        return locale;
                    }
                    if ("getTemplateStack".equals(method.getName())) {
                        return templateStack;
                    }
                    if ("toString".equals(method.getName())) {
                        return "ITemplateContext[" + locale + "]";
                    }
                    if ("hashCode".equals(method.getName())) {
                        return Integer.valueOf(System.identityHashCode(proxy));
                    }
                    if ("equals".equals(method.getName())) {
                        return Boolean.valueOf(proxy == args[0]);
                    }
                    throw new UnsupportedOperationException(
                            "Unexpected call on test template context: " + method.getName());
                });
    }




