    }




    /**
     * A {@link StandardMessageResolver} whose message sources are fully controlled by the test,
     * and which records every call to the protected resolution hooks.
     */
    static final class RecordingMessageResolver extends StandardMessageResolver {

        private final Map<String, Map<Locale, Map<String, String>>> templateMessages =
                new LinkedHashMap<String, Map<Locale, Map<String, String>>>();
        private final Map<Class<?>, Map<Locale, Map<String, String>>> originMessages =
                new LinkedHashMap<Class<?>, Map<Locale, Map<String, String>>>();

        private final List<String> templateInvocations = new ArrayList<String>();
        private final List<String> originInvocations = new ArrayList<String>();

        private ITemplateResource lastTemplateResource = null;


        RecordingMessageResolver() {
            super();
        }


        void putTemplateMessages(final String template, final Locale locale, final Map<String, String> messages) {
            Map<Locale, Map<String, String>> byLocale = this.templateMessages.get(template);
            if (byLocale == null) {
                byLocale = new LinkedHashMap<Locale, Map<String, String>>();
                this.templateMessages.put(template, byLocale);
            }
            byLocale.put(locale, messages);
        }


        void putOriginMessages(final Class<?> origin, final Locale locale, final Map<String, String> messages) {
            Map<Locale, Map<String, String>> byLocale = this.originMessages.get(origin);
            if (byLocale == null) {
                byLocale = new LinkedHashMap<Locale, Map<String, String>>();
                this.originMessages.put(origin, byLocale);
            }
            byLocale.put(locale, messages);
        }


        List<String> getTemplateInvocations() {
            return Collections.unmodifiableList(this.templateInvocations);
        }


        List<String> getOriginInvocations() {
            return Collections.unmodifiableList(this.originInvocations);
        }


        ITemplateResource getLastTemplateResource() {
            return this.lastTemplateResource;
        }


        @Override
        protected Map<String, String> resolveMessagesForTemplate(
                final String template, final ITemplateResource templateResource, final Locale locale) {

            this.templateInvocations.add(template + "|" + locale.toString());
            this.lastTemplateResource = templateResource;

            final Map<Locale, Map<String, String>> byLocale = this.templateMessages.get(template);
            if (byLocale == null) {
                return null;
            }
            return byLocale.get(locale);
        }


        @Override
        protected Map<String, String> resolveMessagesForOrigin(final Class<?> origin, final Locale locale) {

            this.originInvocations.add(origin.getSimpleName() + "|" + locale.toString());

            final Map<Locale, Map<String, String>> byLocale = this.originMessages.get(origin);
            if (byLocale == null) {
                return null;
            }
            return byLocale.get(locale);
        }

    }

