/**
 * Tests for {@link StandardMessageResolver#resolveMessage(ITemplateContext, Class, String, Object[], boolean, boolean, boolean)}.
 *
 * <p>
 *   The production class offers protected extension points ({@code resolveMessagesForTemplate},
 *   {@code resolveMessagesForOrigin}) that are used here as observable seams: the message sources
 *   are fully controlled by the test, so the assertions are about the resolution cascade
 *   (template -&gt; origin -&gt; defaults), its short-circuit flags, and its caching behaviour.
 * </p>
 */
public class StandardMessageResolverResolveMessageTests {


    private static final Locale EN = Locale.ENGLISH;
    private static final Locale ES = new Locale("es", "ES");
    private static final Locale DE = Locale.GERMANY;


    private RecordingMessageResolver resolver;


    @BeforeEach
    public void setUp() {
        this.resolver = new RecordingMessageResolver();
    }




    // ---------------------------------------------------------------------
    // TEMPLATE-BASED RESOLUTION
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("Resolves a message found in the only template of the stack")
    public void resolvesMessageFromSingleTemplateInStack() {

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true)), null, "greeting", null, true, true, true);

        assertEquals("Hello", result);
        assertEquals(Arrays.asList("home|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("Falls back to nested templates, in stack order, when the key is absent from parents")
    public void fallsBackToNestedTemplateWhenKeyNotFoundInParents() {

        this.resolver.putTemplateMessages("home", EN, messages("other", "Other"));
        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from fragment", result);
        // top-down traversal: "home" first, then "fragment"
        assertEquals(Arrays.asList("home|en", "fragment|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("The first (container) template in the stack overrides nested templates")
    public void firstTemplateInStackOverridesNestedTemplates() {

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello from container"));
        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from container", result);
        // nested template must not even be examined once the key is found
        assertEquals(Arrays.asList("home|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("Empty template stack skips template-based resolution")
    public void emptyTemplateStackFallsThroughToOrigin() {

        this.resolver.putOriginMessages(SampleOrigin.class, EN, messages("greeting", "Hello from origin"));

        final String result = this.resolver.resolveMessage(
                context(EN), SampleOrigin.class, "greeting", null, true, true, true);

        assertEquals("Hello from origin", result);
        assertTrue(this.resolver.getTemplateInvocations().isEmpty());

    }


    @Test
    @DisplayName("Messages of a cacheable template are only resolved once per locale")
    public void cachesMessagesOfCacheableTemplates() {

        final ITemplateContext context = context(EN, template("home", true));

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello"));
        assertEquals("Hello", this.resolver.resolveMessage(context, null, "greeting", null, true, true, true));

        // If the (now cached) message map were resolved again, "Goodbye" would be returned
        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Goodbye"));
        assertEquals("Hello", this.resolver.resolveMessage(context, null, "greeting", null, true, true, true));

        assertEquals(Arrays.asList("home|en"), this.resolver.getTemplateInvocations());

    }


    @Test
    @DisplayName("Messages of a non-cacheable template are resolved on every call")
    public void doesNotCacheMessagesOfNonCacheableTemplates() {

        final ITemplateContext context = context(EN, template("home", false));

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Hello"));
        assertEquals("Hello", this.resolver.resolveMessage(context, null, "greeting", null, true, true, true));

        this.resolver.putTemplateMessages("home", EN, messages("greeting", "Goodbye"));
        assertEquals("Goodbye", this.resolver.resolveMessage(context, null, "greeting", null, true, true, true));

        assertEquals(Arrays.asList("home|en", "home|en"), this.resolver.getTemplateInvocations());

    }


    @Test
