    @Test
    @DisplayName("Falls back to nested templates, in stack order, when the key is absent from parents")
    public void fallsBackToNestedTemplateWhenKeyNotFoundInParents() {

        this.resolver.putTemplateMessages("home", EN, messages("other", "Other"));
        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from fragment", result);
