        this.resolver.putTemplateMessages("fragment", EN, messages("greeting", "Hello from fragment"));

        final String result = this.resolver.resolveMessage(
                context(EN, template("home", true), template("fragment", true)),
                null, "greeting", null, true, true, true);

        assertEquals("Hello from container", result);
