package org.thymeleaf.standard.expression;

import java.math.BigDecimal;

import org.junit.jupiter.api.Test;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.ExpressionContext;
import org.thymeleaf.context.IExpressionContext;
import org.thymeleaf.exceptions.TemplateProcessingException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;


/**
 * Tests for the dispatching performed by {@code ComplexExpression.executeComplex(...)}: every
 * recognized {@link ComplexExpression} implementation must be delegated to its corresponding
 * executor, and anything else must be rejected with a {@link TemplateProcessingException}.
 */
public class ComplexExpressionExecuteComplexTests {


    private static final StandardExpressionExecutionContext EXEC_CONTEXT =
            StandardExpressionExecutionContext.NORMAL;

    /*
     * A real (but empty) expression context built on top of a default Thymeleaf engine, so that
     * the standard variable expression evaluator and conversion service are available to the
     * delegated executors.
     */
    private static final IExpressionContext CONTEXT =
            new ExpressionContext(new TemplateEngine().getConfiguration());




    @Test
    public void additionExpressionIsDelegatedToAdditionExecutor() {
        final ComplexExpression expression =
                new AdditionExpression(operand(Integer.valueOf(2)), operand(Integer.valueOf(3)));
        assertBigDecimalEquals("5", execute(expression));
    }


    @Test
    public void additionExpressionWithNonNumericOperandsProducesLiteralConcatenation() {
        final ComplexExpression expression = new AdditionExpression(operand("hello"), operand("world"));
        final Object result = execute(expression);
        assertTrue(result instanceof LiteralValue, "Expected a LiteralValue but got: " + result);
        assertEquals("helloworld", ((LiteralValue) result).getValue());
    }


    @Test
    public void subtractionExpressionIsDelegatedToSubtractionExecutor() {
        final ComplexExpression expression =
                new SubtractionExpression(operand(Integer.valueOf(10)), operand(Integer.valueOf(4)));
        assertBigDecimalEquals("6", execute(expression));
    }


    @Test
    public void multiplicationExpressionIsDelegatedToMultiplicationExecutor() {
        final ComplexExpression expression =
                new MultiplicationExpression(operand(Integer.valueOf(6)), operand(Integer.valueOf(7)));
        assertBigDecimalEquals("42", execute(expression));
    }


    @Test
    public void divisionExpressionIsDelegatedToDivisionExecutor() {
        final ComplexExpression expression =
                new DivisionExpression(operand(Integer.valueOf(10)), operand(Integer.valueOf(4)));
        assertBigDecimalEquals("2.5", execute(expression));
    }


    @Test
    public void divisionExpressionWithNonNumericOperandsRaisesDivisionExecutorError() {
        final ComplexExpression expression = new DivisionExpression(operand("a"), operand("b"));
        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, () -> execute(expression));
        assertEquals("Cannot execute division: operands are \"a\" and \"b\"", exception.getMessage());
    }


    @Test
    public void remainderExpressionIsDelegatedToRemainderExecutor() {
        final ComplexExpression expression =
                new RemainderExpression(operand(Integer.valueOf(10)), operand(Integer.valueOf(3)));
        assertBigDecimalEquals("1", execute(expression));
    }


    @Test
    public void conditionalExpressionIsDelegatedToConditionalExecutorWhenConditionIsTrue() {
        final ComplexExpression expression = new ConditionalExpression(
                expression(Boolean.TRUE), expression("then-value"), expression("else-value"));
        assertEquals("then-value", execute(expression));
    }


    @Test
    public void conditionalExpressionIsDelegatedToConditionalExecutorWhenConditionIsFalse() {
        final ComplexExpression expression = new ConditionalExpression(
                expression(Boolean.FALSE), expression("then-value"), expression("else-value"));
        assertEquals("else-value", execute(expression));
    }


    @Test
    public void defaultExpressionIsDelegatedToDefaultExecutorWhenQueriedValueIsNull() {
        final ComplexExpression expression =
                new DefaultExpression(expression(null), expression(Integer.valueOf(42)));
        assertEquals(Integer.valueOf(42), execute(expression));
    }


    @Test
    public void defaultExpressionIsDelegatedToDefaultExecutorWhenQueriedValueIsNotNull() {
        final ComplexExpression expression =
                new DefaultExpression(expression("present-value"), failingExpression());
        assertEquals("present-value", execute(expression));
    }


    @Test
    public void minusExpressionIsDelegatedToMinusExecutor() {
        final ComplexExpression expression = new MinusExpression(expression(Integer.valueOf(5)));
        assertBigDecimalEquals("-5", execute(expression));
    }


    @Test
    public void negationExpressionIsDelegatedToNegationExecutor() {
        assertEquals(Boolean.FALSE, execute(new NegationExpression(expression(Boolean.TRUE))));
        assertEquals(Boolean.TRUE, execute(new NegationExpression(expression(Boolean.FALSE))));
    }


    @Test
    public void andExpressionIsDelegatedToAndExecutor() {
        final ComplexExpression expression =
                new AndExpression(operand(Boolean.TRUE), operand(Boolean.TRUE));
        assertEquals(Boolean.TRUE, execute(expression));
    }


    @Test
    public void andExpressionShortCircuitsOnLeftFalse() {
        final ComplexExpression expression = new AndExpression(operand(Boolean.FALSE), failingOperand());
        assertEquals(Boolean.FALSE, execute(expression));
    }


    @Test
    public void orExpressionIsDelegatedToOrExecutor() {
        final ComplexExpression expression =
                new OrExpression(operand(Boolean.FALSE), operand(Boolean.TRUE));
        assertEquals(Boolean.TRUE, execute(expression));
    }


    @Test
    public void orExpressionShortCircuitsOnLeftTrue() {
        final ComplexExpression expression = new OrExpression(operand(Boolean.TRUE), failingOperand());
        assertEquals(Boolean.TRUE, execute(expression));
    }


    @Test
    public void equalsExpressionIsDelegatedToEqualsExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new EqualsExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(5)))));
        assertEquals(Boolean.FALSE, execute(
                new EqualsExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(6)))));
    }


    @Test
    public void notEqualsExpressionIsDelegatedToNotEqualsExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new NotEqualsExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(6)))));
        assertEquals(Boolean.FALSE, execute(
                new NotEqualsExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(5)))));
    }


    @Test
    public void greaterThanExpressionIsDelegatedToGreaterThanExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new GreaterThanExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(3)))));
        assertEquals(Boolean.FALSE, execute(
                new GreaterThanExpression(operand(Integer.valueOf(3)), operand(Integer.valueOf(5)))));
    }


    @Test
    public void greaterOrEqualToExpressionIsDelegatedToGreaterOrEqualToExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new GreaterOrEqualToExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(5)))));
        assertEquals(Boolean.FALSE, execute(
                new GreaterOrEqualToExpression(operand(Integer.valueOf(4)), operand(Integer.valueOf(5)))));
    }


    @Test
    public void lessThanExpressionIsDelegatedToLessThanExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new LessThanExpression(operand(Integer.valueOf(3)), operand(Integer.valueOf(5)))));
        assertEquals(Boolean.FALSE, execute(
                new LessThanExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(3)))));
    }


    @Test
    public void lessThanExpressionWithNullOperandRaisesLessThanExecutorError() {
        final ComplexExpression expression = new LessThanExpression(operand(null), operand(Integer.valueOf(5)));
        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, () -> execute(expression));
        assertEquals("Cannot execute LESS THAN comparison: operands are \"null\" and \"5\"", exception.getMessage());
    }


    @Test
    public void lessOrEqualToExpressionIsDelegatedToLessOrEqualToExecutor() {
        assertEquals(Boolean.TRUE, execute(
                new LessOrEqualToExpression(operand(Integer.valueOf(5)), operand(Integer.valueOf(5)))));
        assertEquals(Boolean.FALSE, execute(
                new LessOrEqualToExpression(operand(Integer.valueOf(6)), operand(Integer.valueOf(5)))));
    }


    @Test
    public void unrecognizedComplexExpressionIsRejected() {
        final ComplexExpression expression = new UnrecognizedComplexExpression();
        final TemplateProcessingException exception =
                assertThrows(TemplateProcessingException.class, () -> execute(expression));
        assertEquals(
                "Unrecognized complex expression: " + UnrecognizedComplexExpression.class.getName(),
                exception.getMessage());
    }




    private static Object execute(final ComplexExpression expression) {
        return ComplexExpression.executeComplex(CONTEXT, expression, EXEC_CONTEXT);
    }


    private static void assertBigDecimalEquals(final String expected, final Object actual) {
        assertTrue(actual instanceof BigDecimal, "Expected a BigDecimal result but got: " + actual);
        assertEquals(
                0, new BigDecimal(expected).compareTo((BigDecimal) actual),
                "Expected a numeric value of " + expected + " but got: " + actual);
    }


    /*
     * Operand that is NOT an Expression, so it is executed through the plain
     * IStandardExpression#execute(...) contract (relevant for AdditionExpression, which bypasses
     * literal-unwrapping only for Expression operands).
     */
    private static IStandardExpression operand(final Object value) {
        return new IStandardExpression() {

            @Override
            public String getStringRepresentation() {
                return String.valueOf(value);
            }

            @Override
            public Object execute(final IExpressionContext context) {
                return value;
            }

            @Override
            public Object execute(final IExpressionContext context,
                    final StandardExpressionExecutionContext expContext) {
                return value;
            }

        };
    }


    private static IStandardExpression failingOperand() {
        return new IStandardExpression() {

            @Override
            public String getStringRepresentation() {
                return "FAILING_OPERAND";
            }

            @Override
            public Object execute(final IExpressionContext context) {
                throw new IllegalStateException("This operand should not have been evaluated");
            }

            @Override
            public Object execute(final IExpressionContext context,
                    final StandardExpressionExecutionContext expContext) {
                throw new IllegalStateException("This operand should not have been evaluated");
            }

        };
    }


    private static Expression expression(final Object value) {
        return new ConstantExpression(value);
    }


    private static Expression failingExpression() {
        return new Expression() {

            @Override
            public String getStringRepresentation() {
                return "FAILING_EXPRESSION";
            }

            @Override
            public Object execute(final IExpressionContext context) {
                throw new IllegalStateException("This expression should not have been evaluated");
            }

            @Override
            public Object execute(final IExpressionContext context,
                    final StandardExpressionExecutionContext expContext) {
                throw new IllegalStateException("This expression should not have been evaluated");
            }

        };
    }




    private static final class ConstantExpression extends Expression {

        private static final long serialVersionUID = 1L;

        private final Object value;

        ConstantExpression(final Object value) {
            super();
            this.value = value;
        }

        @Override
        public String getStringRepresentation() {
            return String.valueOf(this.value);
        }

        @Override
        public Object execute(final IExpressionContext context) {
            return this.value;
        }

        @Override
        public Object execute(final IExpressionContext context,
                final StandardExpressionExecutionContext expContext) {
            return this.value;
        }

    }




    private static final class UnrecognizedComplexExpression extends ComplexExpression {

        private static final long serialVersionUID = 1L;

        @Override
        public String getStringRepresentation() {
            return "unrecognized";
        }

    }

}
