        assertEquals("yes", thenExpression.getValue().getValue());

        final TextLiteralExpression elseExpression =
                assertInstanceOf(TextLiteralExpression.class, conditional.getElseExpression());
        assertEquals("no", elseExpression.getValue().getValue());

        assertEquals("true? 'yes' : 'no'", conditional.getStringRepresentation());
    }

