        assertEquals(Boolean.FALSE, condition.getValue());

        final TextLiteralExpression thenExpression =
                assertInstanceOf(TextLiteralExpression.class, conditional.getThenExpression());
        assertEquals("only-then", thenExpression.getValue().getValue());

        assertSame(VariableExpression.NULL_VALUE, conditional.getElseExpression());
