        if (state.hasExpressionAt(nodeIndex)) {
            return state;
        }

        /*
         * STEP 7: Try composing this node as a GREATER or LESSER expression
         */

        if (GreaterLesserExpression.composeGreaterLesserExpression(state, nodeIndex) == null) {
