package org.thymeleaf.standard.expression;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;


/**
 * Unit tests for {@code ExpressionParsingUtil.compose(ExpressionParsingState, int)}.
 *
 * The behaviour of the method is observed through the state it returns (or the {@code null} it
 * returns on error), the expression placed at the composed node, and the expressions that are
 * produced for each of the supported expression kinds.
 */
public class ExpressionParsingUtilComposeTests {


    private static String placeholder(final int index) {
        return String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR) + index + String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR);
    }


    private static ExpressionParsingState stateOf(final String... nodeInputs) {
        final ExpressionParsingState state = new ExpressionParsingState();
        for (final String nodeInput : nodeInputs) {
            state.addNode(nodeInput);
        }
        return state;
    }


    private static ExpressionParsingState decomposeState(final String input) {
        final ExpressionParsingState state = ExpressionParsingUtil.decompose(input);
        assertNotNull(state, "Decomposition should succeed for input: " + input);
        return state;
    }


    private static Expression composeInput(final String input) {
        final ExpressionParsingState state = decomposeState(input);
        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 0);
        assertNotNull(result, "Composition should succeed for input: " + input);
        assertTrue(result.hasExpressionAt(0), "Node 0 should hold an expression for input: " + input);
        return result.get(0).getExpression();
    }


    // -------------------------------------------------------------------------
    // Invalid state / node index handling
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() returns null for a null state")
    public void composeReturnsNullForNullState() {
        assertNull(ExpressionParsingUtil.compose(null, 0));
    }


    @Test
    @DisplayName("compose() returns null when the state has no nodes")
    public void composeReturnsNullForEmptyState() {
        assertNull(ExpressionParsingUtil.compose(new ExpressionParsingState(), 0));
    }


    @Test
    @DisplayName("compose() returns null when nodeIndex is equal to or greater than the state size")
    public void composeReturnsNullWhenNodeIndexIsOutOfBounds() {
        final ExpressionParsingState state = stateOf(placeholder(0));

        assertNull(ExpressionParsingUtil.compose(state, 1));
        assertNull(ExpressionParsingUtil.compose(state, 2));
        assertNull(ExpressionParsingUtil.compose(state, Integer.MAX_VALUE));

        // The state must not have been modified by the out-of-bounds calls
        assertEquals(1, state.size());
        assertTrue(state.hasStringAt(0));
    }


    @Test
    @DisplayName("compose() returns the state untouched when the node already holds an expression")
    public void composeReturnsStateWhenNodeAlreadyHasExpression() {
        final GenericTokenExpression token = new GenericTokenExpression("alreadyAnExpression");
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(token);

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 0);

        assertSame(state, result);
        assertEquals(1, state.size());
        assertTrue(state.hasExpressionAt(0));
        assertSame(token, state.get(0).getExpression());
    }


    @Test
    @DisplayName("compose() returns the state untouched when a non-root node already holds an expression")
    public void composeReturnsStateWhenNonRootNodeAlreadyHasExpression() {
        final BooleanTokenExpression token = new BooleanTokenExpression(Boolean.TRUE);
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(placeholder(1));
        state.addNode(token);

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 1);

        assertSame(state, result);
        assertFalse(state.hasExpressionAt(0));
        assertTrue(state.hasStringAt(0));
        assertSame(token, state.get(1).getExpression());
    }


    @Test
    @DisplayName("compose() accepts the last valid node index")
    public void composeAcceptsLastValidNodeIndex() {
        final BooleanTokenExpression token = new BooleanTokenExpression(Boolean.FALSE);
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(placeholder(1));
        state.addNode(token);

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 1);

        assertSame(state, result);
        assertSame(token, state.get(1).getExpression());
    }


    // -------------------------------------------------------------------------
    // Empty / whitespace input
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() returns null for empty or whitespace-only node input")
    public void composeReturnsNullForEmptyOrWhitespaceInput() {
        assertNull(ExpressionParsingUtil.compose(stateOf(""), 0));
        assertNull(ExpressionParsingUtil.compose(stateOf("   "), 0));
        assertNull(ExpressionParsingUtil.compose(stateOf("\t"), 0));
        assertNull(ExpressionParsingUtil.compose(stateOf(" \n \r "), 0));
    }


    // -------------------------------------------------------------------------
    // STEP 1: simple index placeholders
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() substitutes a placeholder with an expression already held by the referenced node")
    public void composeSubstitutesPlaceholderWithExistingExpression() {
        final BooleanTokenExpression referenced = new BooleanTokenExpression(Boolean.TRUE);
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(placeholder(1));
        state.addNode(referenced);

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 0);

        assertSame(state, result);
        assertTrue(state.hasExpressionAt(0));
        assertSame(referenced, state.get(0).getExpression());
        assertSame(referenced, state.get(1).getExpression());
        assertEquals(2, state.size());
    }


    @Test
    @DisplayName("compose() recursively composes a node referenced through chained placeholders")
    public void composeSubstitutesPlaceholderThroughPlaceholderChain() {
        final NumberTokenExpression number = new NumberTokenExpression("42");
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(placeholder(1));
        state.addNode(placeholder(2));
        state.addNode(number);

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 0);

        assertSame(state, result);
        assertTrue(state.hasExpressionAt(0));
        assertTrue(state.hasExpressionAt(1));
        assertSame(number, state.get(1).getExpression());
        assertSame(number, state.get(0).getExpression());
        assertEquals("42", state.get(0).getExpression().getStringRepresentation());
    }


    @Test
    @DisplayName("compose() parses a complex expression referenced through a placeholder")
    public void composeSubstitutesPlaceholderWithComposedComplexExpression() {
        final ExpressionParsingState state = new ExpressionParsingState();
        state.addNode(placeholder(1));
        state.addNode(placeholder(2) + " + " + placeholder(3));
        state.addNode(new NumberTokenExpression("1"));
        state.addNode(new NumberTokenExpression("2"));

        final ExpressionParsingState result = ExpressionParsingUtil.compose(state, 0);

        assertSame(state, result);
        assertTrue(result.hasExpressionAt(0));
        assertInstanceOf(AdditionExpression.class, result.get(0).getExpression());
        assertEquals("1 + 2", result.get(0).getExpression().getStringRepresentation());
        assertInstanceOf(AdditionExpression.class, result.get(1).getExpression());
        assertSame(result.get(1).getExpression(), result.get(0).getExpression());
    }


    @Test
    @DisplayName("compose() returns null when a placeholder points beyond the available nodes")
    public void composeReturnsNullWhenPlaceholderReferencesMissingNode() {
        final ExpressionParsingState state = stateOf(placeholder(5));

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
        assertFalse(state.hasExpressionAt(0));
    }


    @Test
    @DisplayName("compose() returns null when a placeholder points to a node that cannot be composed")
    public void composeReturnsNullWhenPlaceholderReferencedNodeCannotBeComposed() {
        final ExpressionParsingState state = stateOf(placeholder(1), "");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
        assertFalse(state.hasExpressionAt(0));
        assertTrue(state.hasStringAt(1));
        assertFalse(state.hasExpressionAt(1));
    }


    @Test
    @DisplayName("compose() treats placeholder-like input with non-numeric content as a regular expression")
    public void composeReturnsNullForPlaceholderWithNonNumericContent() {
        assertNull(ExpressionParsingUtil.compose(stateOf(placeholder(1)), 0));
        assertNull(ExpressionParsingUtil.compose(stateOf(String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR) + "-1" + String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR)), 0));

        final String withSpaces = String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR) + " 1 " + String.valueOf(Expression.PARSING_PLACEHOLDER_CHAR);
        assertNull(ExpressionParsingUtil.compose(stateOf(withSpaces), 0));
    }


    // -------------------------------------------------------------------------
    // Simple expressions reached through the placeholder mechanism
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes plain text as a generic token expression")
    public void composeComposesGenericToken() {
        final Expression expression = composeInput("hello");

        assertInstanceOf(GenericTokenExpression.class, expression);
        assertEquals("hello", expression.getStringRepresentation());
    }


    @Test
    @DisplayName("compose() composes numeric and boolean literals as token expressions")
    public void composeComposesNumberAndBooleanTokens() {
        final Expression number = composeInput("42");
        assertInstanceOf(NumberTokenExpression.class, number);
        assertEquals("42", number.getStringRepresentation());

        final Expression decimal = composeInput("3.14");
        assertInstanceOf(NumberTokenExpression.class, decimal);
        assertEquals("3.14", decimal.getStringRepresentation());

        final Expression bool = composeInput("true");
        assertInstanceOf(BooleanTokenExpression.class, bool);
        assertEquals("true", bool.getStringRepresentation());
    }


    // -------------------------------------------------------------------------
    // STEP 2: conditional expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes a conditional expression with then and else branches")
    public void composeComposesConditionalExpression() {
        final Expression expression = composeInput("${condition} ? 'yes' : 'no'");

        final ConditionalExpression conditional = assertInstanceOf(ConditionalExpression.class, expression);
        assertInstanceOf(VariableExpression.class, conditional.getConditionExpression());
        assertEquals("${condition}", conditional.getConditionExpression().getStringRepresentation());
        assertInstanceOf(TextLiteralExpression.class, conditional.getThenExpression());
        assertEquals("'yes'", conditional.getThenExpression().getStringRepresentation());
        assertInstanceOf(TextLiteralExpression.class, conditional.getElseExpression());
        assertEquals("'no'", conditional.getElseExpression().getStringRepresentation());
    }


    @Test
    @DisplayName("compose() composes a conditional expression without an explicit else branch")
    public void composeComposesConditionalExpressionWithoutElseBranch() {
        final Expression expression = composeInput("${condition} ? 'yes'");

        final ConditionalExpression conditional = assertInstanceOf(ConditionalExpression.class, expression);
        assertInstanceOf(VariableExpression.class, conditional.getConditionExpression());
        assertInstanceOf(TextLiteralExpression.class, conditional.getThenExpression());
        assertEquals("'yes'", conditional.getThenExpression().getStringRepresentation());
        // The implicit else branch is the null variable expression
        assertInstanceOf(VariableExpression.class, conditional.getElseExpression());
    }


    @Test
    @DisplayName("compose() returns null for malformed conditional expressions")
    public void composeReturnsNullForMalformedConditionalExpression() {
        final ExpressionParsingState state = decomposeState("${a} ? 'x' : 'y' : 'z'");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    // -------------------------------------------------------------------------
    // STEP 3: default expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes a default (Elvis) expression")
    public void composeComposesDefaultExpression() {
        final Expression expression = composeInput("${name} ?: 'anonymous'");

        final DefaultExpression defaultExpression = assertInstanceOf(DefaultExpression.class, expression);
        assertInstanceOf(VariableExpression.class, defaultExpression.getQueriedExpression());
        assertEquals("${name}", defaultExpression.getQueriedExpression().getStringRepresentation());
        assertInstanceOf(TextLiteralExpression.class, defaultExpression.getDefaultExpression());
        assertEquals("'anonymous'", defaultExpression.getDefaultExpression().getStringRepresentation());
    }


    @Test
    @DisplayName("compose() returns null when the default expression has no default operand")
    public void composeReturnsNullForDefaultExpressionWithoutDefaultOperand() {
        final ExpressionParsingState state = decomposeState("${name} ?:");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    // -------------------------------------------------------------------------
    // STEP 4: OR expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes an OR expression")
    public void composeComposesOrExpression() {
        final Expression expression = composeInput("${a} or ${b}");

        final OrExpression or = assertInstanceOf(OrExpression.class, expression);
        assertInstanceOf(VariableExpression.class, or.getLeft());
        assertInstanceOf(VariableExpression.class, or.getRight());
        assertEquals("${a}", or.getLeft().getStringRepresentation());
        assertEquals("${b}", or.getRight().getStringRepresentation());
        assertEquals("${a} or ${b}", or.getStringRepresentation());
    }


    @Test
    @DisplayName("compose() returns null when an OR operand is not allowed")
    public void composeReturnsNullWhenOrOperandIsNotAllowed() {
        final ExpressionParsingState state = decomposeState("true or aGenericToken");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    // -------------------------------------------------------------------------
    // STEP 5: AND expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes an AND expression")
    public void composeComposesAndExpression() {
        final Expression expression = composeInput("${a} and ${b}");

        final AndExpression and = assertInstanceOf(AndExpression.class, expression);
        assertInstanceOf(VariableExpression.class, and.getLeft());
        assertInstanceOf(VariableExpression.class, and.getRight());
        assertEquals("${a} and ${b}", and.getStringRepresentation());
    }


    // -------------------------------------------------------------------------
    // STEP 6: equals / not equals expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes equals and not-equals expressions")
    public void composeComposesEqualsAndNotEqualsExpressions() {
        final Expression equals = composeInput("${a} == 1");
        assertInstanceOf(EqualsExpression.class, equals);
        assertEquals("${a} == 1", equals.getStringRepresentation());

        final Expression notEquals = composeInput("${a} != 1");
        assertInstanceOf(NotEqualsExpression.class, notEquals);
        assertEquals("${a} != 1", notEquals.getStringRepresentation());

        final Expression wordedEquals = composeInput("${a} eq 1");
        assertInstanceOf(EqualsExpression.class, wordedEquals);
        assertEquals("${a} eq 1", wordedEquals.getStringRepresentation());

        final Expression wordedNotEquals = composeInput("${a} ne 1");
        assertInstanceOf(NotEqualsExpression.class, wordedNotEquals);
        assertEquals("${a} ne 1", wordedNotEquals.getStringRepresentation());
    }


    // -------------------------------------------------------------------------
    // STEP 7: greater / lesser expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes greater and lesser comparison expressions")
    public void composeComposesGreaterLesserExpressions() {
        final Expression greater = composeInput("2 > 1");
        assertInstanceOf(GreaterThanExpression.class, greater);
        assertEquals("2 > 1", greater.getStringRepresentation());

        final Expression greaterOrEqual = composeInput("2 >= 2");
        assertInstanceOf(GreaterOrEqualToExpression.class, greaterOrEqual);
        assertEquals("2 >= 2", greaterOrEqual.getStringRepresentation());

        final Expression lesser = composeInput("1 < 2");
        assertInstanceOf(LessThanExpression.class, lesser);
        assertEquals("1 < 2", lesser.getStringRepresentation());

        final Expression lesserOrEqual = composeInput("2 <= 2");
        assertInstanceOf(LessOrEqualToExpression.class, lesserOrEqual);
        assertEquals("2 <= 2", lesserOrEqual.getStringRepresentation());
    }


    // -------------------------------------------------------------------------
    // STEP 8: addition / subtraction expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes addition and subtraction expressions")
    public void composeComposesAdditionSubtractionExpressions() {
        final Expression addition = composeInput("1 + 2");
        assertInstanceOf(AdditionExpression.class, addition);
        assertEquals("1 + 2", addition.getStringRepresentation());

        final Expression subtraction = composeInput("5 - 2");
        assertInstanceOf(SubtractionExpression.class, subtraction);
        assertEquals("5 - 2", subtraction.getStringRepresentation());
    }


    @Test
    @DisplayName("compose() returns null for an incomplete addition expression")
    public void composeReturnsNullForIncompleteAddition() {
        final ExpressionParsingState state = decomposeState("1 +");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    @Test
    @DisplayName("compose() returns null when an addition operand has an invalid type")
    public void composeReturnsNullWhenAdditionOperandIsNotAllowed() {
        final ExpressionParsingState state = decomposeState("1 + true");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    // -------------------------------------------------------------------------
    // STEP 9: multiplication / division / remainder expressions
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("compose() composes multiplication, division and remainder expressions")
    public void composeComposesMultiplicationDivisionRemainderExpressions() {
        final Expression multiplication = composeInput("2 * 3");
        assertInstanceOf(MultiplicationExpression.class, multiplication);
        assertEquals("2 * 3", multiplication.getStringRepresentation());

        final Expression division = composeInput("6 / 3");
        assertInstanceOf(DivisionExpression.class, division);
        assertEquals("6 / 3", division.getStringRepresentation());

        final Expression wordedDivision = composeInput("6 div 3");
        assertInstanceOf(DivisionExpression.class, wordedDivision);
        assertEquals("6 div 3", wordedDivision.getStringRepresentation());

        final Expression remainder = composeInput("7 % 2");
        assertInstanceOf(RemainderExpression.class, remainder);
        assertEquals("7 % 2", remainder.getStringRepresentation());

        final Expression wordedRemainder = composeInput("7 mod 2");
        assertInstanceOf(RemainderExpression.class, wordedRemainder);
        assertEquals("7 mod 2", wordedRemainder.getStringRepresentation());
    }


    @Test
    @DisplayName("compose() returns null when a multiplication operand has an invalid type")
    public void composeReturnsNullWhenMultiplicationOperandIsNotAllowed() {
        final ExpressionParsingState state = decomposeState("2 * 'text'");

        assertNull(ExpressionParsingUtil.compose(state, 0));
        assertTrue(state.hasStringAt(0));
    }


    // -------------------------------------------------------------------------
    // STEP 10: minus expressions
    // -------------------------------------------------------------------------

    @Test
