        assertInstanceOf(AdditionExpression.class, addition);
        assertEquals("1 + 2", addition.getStringRepresentation());

        final Expression subtraction = composeInput("5 - 2");
        assertInstanceOf(SubtractionExpression.class, subtraction);
        assertEquals("5 - 2", subtraction.getStringRepresentation());
    }


