package org.thymeleaf.standard.expression;

public class Probe4 {
    public static void main(String[] args) {
        String[] inputs = {
            "t :: f (a=~{x :: y})",
            "t :: f ('a,b' , 3)",
            "t :: f (a=1, )",
            "t :: f ( , )",
            "t ::f",
            "t:: f",
            ":: frag (a=1)",
            ":: frag (1,2)",
            "(a=1) :: f",
            "template :: frag   (a=1)   ",
            "t :: f (a=1,b=2) (c=3)",
            "t :: f (a=1)(b=2)(c=3)",
        };
        for (String in : inputs) Probe.probe(in);
        System.out.println("== round trips ==");
        for (String in : inputs) {
            FragmentExpression fe = FragmentExpression.parseFragmentExpressionContent(in);
            String rep = fe == null ? "null" : fe.getStringRepresentation();
            FragmentExpression rt = fe == null ? null : FragmentExpression.parseFragmentExpression(rep);
            System.out.println(in + " -> " + rep + " -> " + (rt == null ? "null" : rt.getStringRepresentation()));
        }
    }
}
EOF
