        public void stringRepresentationIsParseableBackToAnEquivalentExpression(final String input) {
            final FragmentExpression expression = parse(input);
            final String representation = expression.getStringRepresentation();

            final FragmentExpression reparsed = FragmentExpression.parseFragmentExpression(representation);

            assertNotNull(reparsed, "Representation [" + representation + "] could not be parsed back");
            assertEquals(representation, reparsed.getStringRepresentation());
            assertEquals(expression.hasFragmentSelector(), reparsed.hasFragmentSelector());
            assertEquals(expression.hasParameters(), reparsed.hasParameters());
        }


        private List<String> assignationsOrNull(final FragmentExpression expression) {
            if (!expression.hasParameters()) {
                return null;
            }
            return assignationsOf(expression);
