    @Nested
    @DisplayName("Stability and round-tripping through the string representation")
    class RoundTrip {


        @ParameterizedTest(name = "input [{0}]")
        @ValueSource(strings = {
                "template",
                "template :: frag",
                ":: frag",
                "'t' :: 'f'",
                "${var}",
                "template :: ${var}",
                "template :: frag (a=1)",
                "t :: f (a=1, b=${y}, c='z')",
                "template :: frag (1,2)",
                "template (a=1)",
                "template (1,2)",
                "(1,2)",
                "template :: frag ()",
                "a'b",
                "t :: f (a=1)(b=2)",
                "t :: f(a='(')",
                "t :: f ('a, b')",
                "t :: f (1+2)",
                ":: frag (a=1)"})
        public void parsingTwiceProducesEquivalentExpressions(final String input) {
            final FragmentExpression first = parse(input);
            final FragmentExpression second = parse(input);

            assertEquals(first.getStringRepresentation(), second.getStringRepresentation());
            assertEquals(first.hasSyntheticParameters(), second.hasSyntheticParameters());
            assertEquals(assignationsOrNull(first), assignationsOrNull(second));
        }


        @ParameterizedTest(name = "input [{0}]")
        @ValueSource(strings = {
                "template",
                "template :: frag",
                ":: frag",
                "'t' :: 'f'",
                "${var}",
                "template :: ${var}",
                "template :: frag (a=1)",
                "t :: f (a=1, b=${y}, c='z')",
                "template :: frag (1,2)",
                "template (a=1)",
                "template (1,2)",
                "(1,2)",
                "template :: frag ()",
                "a'b",
                "t :: f (a=1)(b=2)",
                "t :: f(a='(')",
                "t :: f ('a, b')",
                "t :: f (1+2)",
                ":: frag (a=1)"})
        public void stringRepresentationIsParseableBackToAnEquivalentExpression(final String input) {
            final FragmentExpression expression = parse(input);
            final String representation = expression.getStringRepresentation();

            final FragmentExpression reparsed = FragmentExpression.parseFragmentExpression(representation);

            assertNotNull(reparsed, "Representation [" + representation + "] could not be parsed back");
            assertEquals(representation, reparsed.getStringRepresentation());
            assertEquals(expression.hasFragmentSelector(), reparsed.hasFragmentSelector());
            assertEquals(expression.hasParameters(), reparsed.hasParameters());
        }


        private List<String> assignationsOrNull(final FragmentExpression expression) {
            if (!expression.hasParameters()) {
                return null;
            }
            return assignationsOf(expression);
        }


    }


