/**
 * Tests for {@link FragmentExpression#parseFragmentExpressionContent(String)}, the parser that receives the
 * <em>content</em> of a fragment expression (i.e. what lives between the {@code ~{} braces, with no braces).
 */
public class FragmentExpressionParseFragmentExpressionContentTests {


    private static FragmentExpression parse(final String input) {
        final FragmentExpression expression = FragmentExpression.parseFragmentExpressionContent(input);
        assertNotNull(expression, "Expected a parsed FragmentExpression for input [" + input + "]");
        return expression;
    }

    private static String representationOf(final IStandardExpression expression) {
        assertNotNull(expression, "Expected a non-null expression");
        return expression.getStringRepresentation();
    }

    private static List<String> assignationsOf(final FragmentExpression expression) {
        final AssignationSequence parameters = expression.getParameters();
        assertNotNull(parameters, "Expected a non-null assignation sequence");
        final List<String> result = new ArrayList<String>();
        for (final Assignation assignation : parameters.getAssignations()) {
            result.add(assignation.getStringRepresentation());
        }
        return result;
    }

    private static List<String> leftsOf(final FragmentExpression expression) {
        final List<String> result = new ArrayList<String>();
        for (final Assignation assignation : expression.getParameters().getAssignations()) {
            result.add(representationOf(assignation.getLeft()));
        }
        return result;
    }

    private static List<String> rightsOf(final FragmentExpression expression) {
        final List<String> result = new ArrayList<String>();
        for (final Assignation assignation : expression.getParameters().getAssignations()) {
            result.add(representationOf(assignation.getRight()));
        }
        return result;
    }




