        @ValueSource(strings = {"", " ", "   ", "\t", "\n", "\r", " \t\r\n ", "\n\n\n"})
        public void blankInputsReturnTheSharedEmptyFragmentExpression(final String input) {
            assertSame(
                    FragmentExpression.EMPTY_FRAGMENT_EXPRESSION,
                    FragmentExpression.parseFragmentExpressionContent(input));
        }


        @Test
        public void blankInputReturnsTheEmptyRepresentation() {
            assertEquals("~{}", parse("   ").getStringRepresentation());
        }


    }




