@Nested
@DisplayName("Parameters as an assignation sequence")
class AssignationParameters {


    @Test
    public void singleAssignationParameter() {
        final FragmentExpression expression = parse("template :: frag (a=1)");

        assertEquals("template", representationOf(expression.getTemplateName()));
        assertEquals("frag", representationOf(expression.getFragmentSelector()));
        assertTrue(expression.hasParameters());
        assertFalse(expression.hasSyntheticParameters());
        assertEquals(1, expression.getParameters().size());
        assertEquals(Arrays.asList("a=1"), assignationsOf(expression));
        assertEquals(Arrays.asList("a"), leftsOf(expression));
        assertEquals(Arrays.asList("1"), rightsOf(expression));
        assertEquals("~{template :: frag (a=1)}", expression.getStringRepresentation());
    }


    @Test
    public void severalAssignationParametersOfDifferentKinds() {
        final FragmentExpression expression = parse("t :: f (a=1, b=${y}, c='z')");

        assertTrue(expression.hasParameters());
        assertFalse(expression.hasSyntheticParameters());
        assertEquals(3, expression.getParameters().size());
        assertEquals(Arrays.asList("a=1", "b=${y}", "c='z'"), assignationsOf(expression));
        assertEquals(Arrays.asList("a", "b", "c"), leftsOf(expression));
        assertEquals(Arrays.asList("1", "${y}", "'z'"), rightsOf(expression));
        assertEquals("~{t :: f (a=1,b=${y},c='z')}", expression.getStringRepresentation());
    }


    @Test
    public void repeatedParameterNamesAreKeptAsSeparateAssignations() {
        final FragmentExpression expression = parse("t :: f (a=1, a=2)");

        assertEquals(2, expression.getParameters().size());
        assertEquals(Arrays.asList("a=1", "a=2"), assignationsOf(expression));
        assertFalse(expression.hasSyntheticParameters());
    }


    @Test
    public void parametersCanBeAFragmentExpression() {
        final FragmentExpression expression = parse("t :: f (a=~{x :: y})");

        assertEquals(Arrays.asList("a=~{x :: y}"), assignationsOf(expression));
        assertFalse(expression.hasSyntheticParameters());
        assertEquals("~{t :: f (a=~{x :: y})}", expression.getStringRepresentation());
    }


    @Test
    public void unnecessaryWhitespaceIsRemovedEverywhere() {
        final FragmentExpression expression = parse(" t  ::  f  (  a  =  1  ) ");

        assertEquals("t", representationOf(expression.getTemplateName()));
        assertEquals("f", representationOf(expression.getFragmentSelector()));
        assertEquals(Arrays.asList("a=1"), assignationsOf(expression));
        assertEquals("~{t :: f (a=1)}", expression.getStringRepresentation());
    }


    @ParameterizedTest(name = "input [{0}]")
    @ValueSource(strings = {"t :: f (a=1,)", "t :: f (,a=1)", "t :: f (a=1, )"})
    public void emptyAssignationsProducedByTrailingOrLeadingCommasAreIgnored(final String input) {
        final FragmentExpression expression = parse(input);

        assertEquals(1, expression.getParameters().size());
        assertEquals(Arrays.asList("a=1"), assignationsOf(expression));
        assertFalse(expression.hasSyntheticParameters());
        assertEquals("~{t :: f (a=1)}", expression.getStringRepresentation());
    }


    @Test
    public void parenthesisGroupWithOnlyCommasProducesAnEmptyParameterSequence() {
        final FragmentExpression expression = parse("t :: f ( , )");

        assertNotNull(expression.getParameters());
        assertEquals(0, expression.getParameters().size());
        assertFalse(expression.hasParameters());
        assertFalse(expression.hasSyntheticParameters());
        assertEquals("~{t :: f}", expression.getStringRepresentation());
    }


    @Test
    public void parenthesisContentWithEscapedQuoteIsParsedAsASingleAssignation() {
        final FragmentExpression expression = parse("t :: f (a='it\\'s')");

        assertEquals(1, expression.getParameters().size());
        assertEquals(Arrays.asList("a='it\\'s'"), assignationsOf(expression));
        assertEquals(Arrays.asList("'it\\'s'"), rightsOf(expression));
        assertFalse(expression.hasSyntheticParameters());
        assertEquals("~{t :: f (a='it\\'s')}", expression.getStringRepresentation());
    }


    @Test
    public void parenthesisInsideQuotedValueDoesNotBreakTheParameterGroup() {
        final FragmentExpression expression = parse("t :: f(a='(')");

        assertEquals("t", representationOf(expression.getTemplateName()));
        assertEquals("f", representationOf(expression.getFragmentSelector()));
        assertEquals(Arrays.asList("a='('"), assignationsOf(expression));
        assertFalse(expression.hasSyntheticParameters());
    }


}




