package org.thymeleaf.standard.expression;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.thymeleaf.exceptions.TemplateProcessingException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;


public class FragmentSignatureUtilsProcessParametersTests {


    private static FragmentSignature signature(final String name, final String... parameterNames) {
        return new FragmentSignature(name, Arrays.asList(parameterNames));
    }

    private static FragmentSignature signatureWithoutParameters(final String name) {
        return new FragmentSignature(name, null);
    }

    private static Map<String, Object> parameters(final Object... keyValues) {
        final Map<String, Object> result = new HashMap<String, Object>();
        for (int i = 0; i < keyValues.length; i += 2) {
            result.put((String) keyValues[i], keyValues[i + 1]);
        }
        return result;
    }


    @Test
    public void testNullFragmentSignatureThrowsIllegalArgumentException() {

        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> FragmentSignatureUtils.processParameters(
                        null, parameters("a", "value"), false));

        assertEquals("Fragment signature cannot be null", exception.getMessage());
    }


    @Test
    public void testNullSpecifiedParametersAndSignatureWithoutParametersReturnsNull() {

        assertNull(FragmentSignatureUtils.processParameters(
                signatureWithoutParameters("frag"), null, false));
    }


    @Test
    public void testEmptySpecifiedParametersAndSignatureWithEmptyParameterListReturnsNull() {

        assertNull(FragmentSignatureUtils.processParameters(
                signature("frag"), new HashMap<String, Object>(), false));
    }


    @Test
    public void testEmptySpecifiedParametersAndSyntheticParametersReturnsNullIfSignatureHasNoParameters() {

        // The null/empty check takes precedence: there is nothing to assign, so no exception is raised.
        assertNull(FragmentSignatureUtils.processParameters(
                signatureWithoutParameters("frag"), Collections.<String, Object>emptyMap(), true));
    }


    @Test
    public void testNullSpecifiedParametersButSignatureDeclaresParametersThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a", "b"), null, false));

        assertTrue(exception.getMessage().contains("frag (a,b)"));
        assertTrue(exception.getMessage().contains(
                "declares parameters, but fragment selection did not specify any parameters"));
    }


    @Test
    public void testEmptySpecifiedParametersButSignatureDeclaresParametersThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a"), new HashMap<String, Object>(), true));

        assertTrue(exception.getMessage().contains("frag (a)"));
        assertTrue(exception.getMessage().contains(
                "declares parameters, but fragment selection did not specify any parameters"));
    }


    @Test
    public void testSyntheticParametersWithSignatureWithoutParametersThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signatureWithoutParameters("frag"),
                        parameters("_arg0", "value"), true));

        assertTrue(exception.getMessage().contains("frag"));
        assertTrue(exception.getMessage().contains("declares no parameters"));
        assertTrue(exception.getMessage().contains("synthetic manner"));
    }


    @Test
    public void testSyntheticParametersWithFewerSpecifiedThanDeclaredThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a", "b"),
                        parameters("_arg0", "value"), true));

        assertTrue(exception.getMessage().contains("frag (a,b)"));
        assertTrue(exception.getMessage().contains("declares 2 parameters"));
        assertTrue(exception.getMessage().contains("specifies 1 parameters"));
    }


    @Test
    public void testSyntheticParametersWithMoreSpecifiedThanDeclaredThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a"),
                        parameters("_arg0", "value0", "_arg1", "value1"), true));

        assertTrue(exception.getMessage().contains("frag (a)"));
        assertTrue(exception.getMessage().contains("declares 1 parameters"));
        assertTrue(exception.getMessage().contains("specifies 2 parameters"));
    }


    @Test
    public void testSyntheticParametersAreAssignedToSignatureNamesInOrder() {

        final Map<String, Object> specified = parameters("_arg0", "alpha", "_arg1", 42);
        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signature("frag", "first", "second"), specified, true);

        assertNotSame(specified, result);
        assertEquals(2, result.size());
        assertEquals("alpha", result.get("first"));
        assertEquals(Integer.valueOf(42), result.get("second"));
        assertTrue(result.containsKey("first"));
        assertTrue(result.containsKey("second"));
        // Synthetic keys must not leak into the processed parameters.
        assertFalse(result.containsKey("_arg0"));
        assertFalse(result.containsKey("_arg1"));
    }


    @Test
    public void testSyntheticParametersFollowSignatureParameterOrderNotSyntheticOrder() {

        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signature("frag", "second", "first"),
                parameters("_arg0", "alpha", "_arg1", "beta"), true);

        assertEquals(2, result.size());
        assertEquals("alpha", result.get("second"));
        assertEquals("beta", result.get("first"));
    }


    @Test
    public void testNonSyntheticParametersWithSignatureWithoutParametersReturnsSameMap() {

        final Map<String, Object> specified = parameters("a", "value", "b", 7);
        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signatureWithoutParameters("frag"), specified, false);

        assertSame(specified, result);
        assertEquals("value", result.get("a"));
        assertEquals(Integer.valueOf(7), result.get("b"));
    }


    @Test
    public void testNonSyntheticParametersWithEmptySignatureParameterListReturnsSameMap() {

        final Map<String, Object> specified = parameters("a", "value");
        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signature("frag"), specified, false);

        assertSame(specified, result);
        assertEquals("value", result.get("a"));
    }


    @Test
    public void testNonSyntheticParametersWithAllSignatureParametersPresentReturnsSameMap() {

        final Map<String, Object> specified = parameters("a", "valueA", "b", 7, "extra", "extraValue");
        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signature("frag", "a", "b"), specified, false);

        assertSame(specified, result);
        assertEquals(3, result.size());
        assertEquals("valueA", result.get("a"));
        assertEquals(Integer.valueOf(7), result.get("b"));
        assertEquals("extraValue", result.get("extra"));
    }


    @Test
    public void testNonSyntheticParametersWithNullValueForSignatureParameterAreAccepted() {

        final Map<String, Object> specified = parameters("a", null);
        final Map<String, Object> result = FragmentSignatureUtils.processParameters(
                signature("frag", "a"), specified, false);

        assertSame(specified, result);
        assertTrue(result.containsKey("a"));
        assertNull(result.get("a"));
    }


    @Test
    public void testNonSyntheticParametersMissingOneSignatureParameterThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a", "b"),
                        parameters("a", "valueA"), false));

        assertTrue(exception.getMessage().contains("frag (a,b)"));
        assertTrue(exception.getMessage().contains("declares parameter \"b\""));
        assertTrue(exception.getMessage().contains("not specified at the fragment selection"));
    }


    @Test
    public void testNonSyntheticParametersMissingAllSignatureParametersThrows() {

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> FragmentSignatureUtils.processParameters(
                        signature("frag", "a", "b"),
                        parameters("other", "value"), false));

        assertTrue(exception.getMessage().contains("frag (a,b)"));
        assertTrue(exception.getMessage().contains("declares parameter \"a\""));
    }

}
