    @Test
    @DisplayName("Null input raises a NullPointerException (pattern matcher does not accept null)")
    public void testNullInputThrowsNullPointerException() {
        assertThrows(NullPointerException.class, () -> parse(null));
    }


    @ParameterizedTest(name = "[{index}] \"{0}\" is not a message expression")
    @ValueSource(strings = {
            "hello",
            "abc",
            "1+2",
            "{abc}",
            "#abc",
            "##{abc}",
            "${abc}",
            "#{abc",
            "abc}",
            "#{}abc",
            "#{abc}def",
            "#{abc}extra",
            "#{abc}(x)",
            "x#{abc}"
    })
    @DisplayName("Inputs not matching the #{...} pattern (including text after the closing brace) return null")
    public void testNonMatchingInputReturnsNull(final String input) {
        assertNull(parse(input));
    }


    @ParameterizedTest(name = "[{index}] \"{0}\" has blank content")
    @ValueSource(strings = {
            "#{}",
            "#{ }",
            "#{  }",
            "#{\t}",
            "#{\n}",
            "#{ \t\n }"
