        assertNull(expression.getParameters());
        assertNotNull(expression.getBase());
        assertEquals("abc", expression.getBase().getStringRepresentation());
        assertEquals("#{abc}", expression.getStringRepresentation());
        assertEquals("#{abc}", expression.toString());

    }


    @ParameterizedTest(name = "[{index}] \"{0}\" parses to #{abc}")
    @ValueSource(strings = {
