        assertEquals("#{'abc'}", expression.getStringRepresentation());

        final MessageExpression withParentheses = parseAssertingNotNull("#{'literal(key)'}");
        assertFalse(withParentheses.hasParameters());
        assertEquals("'literal(key)'", withParentheses.getBase().getStringRepresentation());

    }


