    public void testEscapedQuoteInsideLiteralKey() {

        final MessageExpression expression = parseAssertingNotNull("#{'a\\'b'}");

        assertFalse(expression.hasParameters());
        assertNull(expression.getParameters());
        assertInstanceOf(TextLiteralExpression.class, expression.getBase());
        assertEquals("'a\\'b'", expression.getBase().getStringRepresentation());

    }


