        assertFalse(expression.hasParameters());
        assertInstanceOf(TextLiteralExpression.class, expression.getBase());
        assertEquals("'abc}def'", expression.getBase().getStringRepresentation());

        final MessageExpression trailing = parseAssertingNotNull("#{abc}}\n");
        assertFalse(trailing.hasParameters());
        assertEquals("'abc}'", trailing.getBase().getStringRepresentation());

    }


