        assertNull(variable.getParameters());
        assertInstanceOf(VariableExpression.class, variable.getBase());
        assertEquals("${var}", variable.getBase().getStringRepresentation());

        final MessageExpression addition = parseAssertingNotNull("#{1+2}");
        assertFalse(addition.hasParameters());
        assertInstanceOf(AdditionExpression.class, addition.getBase());
        assertEquals("1 + 2", addition.getBase().getStringRepresentation());

        final MessageExpression nested = parseAssertingNotNull("#{#{x}}");
        assertFalse(nested.hasParameters());
        assertInstanceOf(MessageExpression.class, nested.getBase());
        assertEquals("#{x}", nested.getBase().getStringRepresentation());

    }



