    // ----------------------------------------------------------------------

    @Test
    @DisplayName("A single parameter is parsed into a one-element expression sequence")
    public void testSingleParameter() {

        final MessageExpression expression = parseAssertingNotNull("#{abc(${x})}");

        assertTrue(expression.hasParameters());
        assertNotNull(expression.getParameters());
        assertEquals(1, expression.getParameters().size());
        assertEquals(1, expression.getParameters().getExpressions().size());
        assertInstanceOf(VariableExpression.class, expression.getParameters().getExpressions().get(0));
        assertEquals("${x}", expression.getParameters().getExpressions().get(0).getStringRepresentation());
        assertEquals("abc", expression.getBase().getStringRepresentation());
        assertEquals("#{abc(${x})}", expression.getStringRepresentation());

    }


    @Test
    @DisplayName("Several parameters are parsed, in order, into the expression sequence")
    public void testMultipleParameters() {

        final MessageExpression expression = parseAssertingNotNull("#{abc(${x},${y},${z})}");

        assertTrue(expression.hasParameters());
        assertEquals(3, expression.getParameters().size());
        assertEquals(List.of("${x}", "${y}", "${z}"), parameterRepresentations(expression));
        assertEquals("#{abc(${x},${y},${z})}", expression.getStringRepresentation());

    }


    @Test
    @DisplayName("Parameters can be literals, numbers, booleans and complex expressions")
    public void testParameterKinds() {

        final MessageExpression numbers = parseAssertingNotNull("#{abc(1,2)}");
        assertEquals(List.of("1", "2"), parameterRepresentations(numbers));

        final MessageExpression literal = parseAssertingNotNull("#{abc('lit')}");
        assertEquals(List.of("'lit'"), parameterRepresentations(literal));

        final MessageExpression literalWithComma = parseAssertingNotNull("#{abc('a,$b')}");
        assertEquals(List.of("'a,$b'"), parameterRepresentations(literalWithComma));

