package org.thymeleaf.standard.util;

import java.util.stream.Stream;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link StandardExpressionUtils#containsExternalAccess(String)}.
 */
public class StandardExpressionUtilsContainsExternalAccessTests {


    static Stream<Arguments> objectInstantiationExpressions() {
        return Stream.of(
                Arguments.of("new String()"),
                Arguments.of("new java.lang.StringBuilder()"),
                Arguments.of("new Integer ( 5 )"),
                Arguments.of("${new String()}"),
                // Keyword matching must be case insensitive
                Arguments.of("NEW String()"),
                Arguments.of("new Object()"),
                // Whitespace may separate the keyword from the class name
                Arguments.of("new  String()"),
                Arguments.of("new\tString()"),
                Arguments.of("new\nString()"),
                Arguments.of("new\n\nFoo"),
                // Keyword surrounded by other expression content
                Arguments.of("foo new bar"),
                Arguments.of("some new thing here"),
                Arguments.of("abc new "),
                Arguments.of("x.new Foo"));
    }


    static Stream<Arguments> staticAccessExpressions() {
        return Stream.of(
                Arguments.of("@foo@"),
                Arguments.of("@a@"),
                Arguments.of("@@"),
                Arguments.of("@foo@bar"),
                Arguments.of("@a@b"),
                Arguments.of("@foo@method()"),
                Arguments.of("@UserService@findAll()"),
                Arguments.of("@abc@ + @def@"),
                Arguments.of("abc @x@ def"),
                Arguments.of("some @x.y@ thing"),
                Arguments.of("${{@foo@}}"),
                // Whitespace and dots are tolerated inside a static access
                Arguments.of("@ x @"),
                Arguments.of("@foo @bar"),
                Arguments.of("@foo.bar@"));
    }


    static Stream<Arguments> paramAccessExpressions() {
        return Stream.of(
                Arguments.of("param.x"),
                Arguments.of("param[0]"),
                Arguments.of("${param.foo}"),
                Arguments.of("${param}"),
                Arguments.of("(param)"),
                Arguments.of(" param "),
                Arguments.of("param\n"),
                // Keyword matching must be case insensitive
                Arguments.of("PARAM.X"));
    }


    static Stream<Arguments> nonExternalExpressions() {
        return Stream.of(
                Arguments.of(""),
                Arguments.of(" "),
                Arguments.of("   "),
                Arguments.of("a"),
                Arguments.of("text"),
                Arguments.of("hello world"),
                Arguments.of("a b c"),
                Arguments.of("1+2"),
                Arguments.of("'some text'"),
                Arguments.of("${T(java.lang.Runtime)}"),
                Arguments.of("abc + def"));
    }


    static Stream<Arguments> keywordEmbeddedInIdentifierExpressions() {
        return Stream.of(
                // "new" as part of a larger identifier is not an instantiation
                Arguments.of("new"),
                Arguments.of("news"),
                Arguments.of("newFoo()"),
                Arguments.of("renew Foo"),
                Arguments.of("anew Foo"),
                Arguments.of("xnew Foo"),
                Arguments.of("_new Foo"),
                Arguments.of("1new Foo"),
                Arguments.of("abc new"),
                Arguments.of("wnew Foo"),
                Arguments.of("new("),
                // "param" as part of a larger identifier is not a param access
                Arguments.of("param"),
                Arguments.of("params"),
                Arguments.of("param1"),
                Arguments.of("x.param"),
                Arguments.of("myparam.x"));
    }


    @DisplayName("Contains external access: object instantiation")
    @ParameterizedTest(name = "[{index}] \"{0}\" contains external access")
    @MethodSource("objectInstantiationExpressions")
    void shouldDetectObjectInstantiation(final String expression) {
        assertTrue(StandardExpressionUtils.containsExternalAccess(expression));
    }


    @DisplayName("Contains external access: static method / expression object access")
    @ParameterizedTest(name = "[{index}] \"{0}\" contains external access")
    @MethodSource("staticAccessExpressions")
    void shouldDetectStaticAccess(final String expression) {
        assertTrue(StandardExpressionUtils.containsExternalAccess(expression));
    }


    @DisplayName("Contains external access: param access")
    @ParameterizedTest(name = "[{index}] \"{0}\" contains external access")
    @MethodSource("paramAccessExpressions")
    void shouldDetectParamAccess(final String expression) {
        assertTrue(StandardExpressionUtils.containsExternalAccess(expression));
    }


    @DisplayName("No external access: plain expressions")
    @ParameterizedTest(name = "[{index}] \"{0}\" does not contain external access")
    @MethodSource("nonExternalExpressions")
    void shouldNotDetectExternalAccessInPlainExpressions(final String expression) {
        assertFalse(StandardExpressionUtils.containsExternalAccess(expression));
    }


    @DisplayName("No external access: forbidden keywords embedded in larger identifiers")
    @ParameterizedTest(name = "[{index}] \"{0}\" does not contain external access")
    @MethodSource("keywordEmbeddedInIdentifierExpressions")
    void shouldNotDetectExternalAccessInsideIdentifiers(final String expression) {
        assertFalse(StandardExpressionUtils.containsExternalAccess(expression));
    }


    @Test
    @DisplayName("A single at sign is not a static access")
    void shouldNotDetectSingleAtSign() {
        assertFalse(StandardExpressionUtils.containsExternalAccess("@"));
        assertFalse(StandardExpressionUtils.containsExternalAccess("@foo"));
        assertFalse(StandardExpressionUtils.containsExternalAccess("foo@bar"));
        assertFalse(StandardExpressionUtils.containsExternalAccess("user@example.com"));
    }


    @Test
    @DisplayName("At signs separated by non-identifier characters do not form a static access")
    void shouldNotDetectAtSignsSeparatedByOtherCharacters() {
        // '(' is neither whitespace, a dot nor an identifier character, so the match is discarded
        assertFalse(StandardExpressionUtils.containsExternalAccess("@foo.(bar)@"));
        assertFalse(StandardExpressionUtils.containsExternalAccess("@abc + def@"));
    }


    @Test
    @DisplayName("Repeated invocations produce the same result")
    void shouldBeConsistentAcrossInvocations() {
        for (int i = 0; i < 3; i++) {
            assertTrue(StandardExpressionUtils.containsExternalAccess("new String()"));
            assertTrue(StandardExpressionUtils.containsExternalAccess("@java.lang.Integer@parseInt('3')"));
            assertTrue(StandardExpressionUtils.containsExternalAccess("param.x"));
            assertFalse(StandardExpressionUtils.containsExternalAccess("hello world"));
            assertFalse(StandardExpressionUtils.containsExternalAccess("@foo"));
        }
    }


    @Test
    @DisplayName("A null expression is not accepted")
    void shouldThrowNullPointerExceptionForNullExpression() {
        assertThrows(NullPointerException.class, () -> StandardExpressionUtils.containsExternalAccess(null));
    }


