        final RecordingHandler handler = new RecordingHandler();
        final Reader reader = chunkSize > 0 ? new ChunkReader(document, chunkSize) : new StringReader(document);
        parser(2, bufferSize, commentsAndLiterals, true).parseDocument(reader, bufferSize, handler);
        return handler.events.toString();
    }

