                "[/* a comment */]text",
                "[// a comment line\n]text",
                "text with 'literal' and \"another\" in it",
                "before [#elem]inside[/elem] after",
                "pre[#myelement]text"
        };
        for (final String doc : docs) {
            for (final int bufferSize : new int[] {64, 8}) {
                for (final int chunkSize : new int[] {0, 3}) {
