private static boolean isLiteralDelimiter(final char[] text, final int offset, final int i) {
    int escapes = 0;
    int j = i - 1;
    while (j >= offset && text[j--] == '\\') {
        escapes++;
    }
    return escapes % 2 == 0;
}



