public class TextParserParseDocumentTests {


    /*
     * ------------------------------------------------------------------------
     * Infrastructure
     * ------------------------------------------------------------------------
     */

    /**
     * A handler that records every event it receives as a human readable string, so that both the
     * sequence and the contents of the events can be asserted.
     */
    static final class RecordingHandler extends AbstractTextHandler {

        final List<String> events = new ArrayList<>();

        long startTimeNanos = Long.MIN_VALUE;
        long endTimeNanos = Long.MIN_VALUE;
        long totalTimeNanos = Long.MIN_VALUE;
        int startLine = -1;
        int startCol = -1;
        int endLine = -1;
        int endCol = -1;

        int documentStartCount = 0;
        int documentEndCount = 0;

        @Override
        public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
            this.documentStartCount++;
            this.startTimeNanos = startTimeNanos;
            this.startLine = line;
            this.startCol = col;
            this.events.add("documentStart[" + line + "," + col + "]");
        }

        @Override
        public void handleDocumentEnd(
                final long endTimeNanos, final long totalTimeNanos, final int line, final int col) {
            this.documentEndCount++;
            this.endTimeNanos = endTimeNanos;
            this.totalTimeNanos = totalTimeNanos;
            this.endLine = line;
            this.endCol = col;
            this.events.add("documentEnd[" + line + "," + col + "]");
        }

        @Override
        public void handleText(
                final char[] buffer, final int offset, final int len, final int line, final int col) {
            // Sanity check on the reported region: it must be a valid region of the buffer
            if (offset < 0 || len < 0 || (offset + len) > buffer.length) {
                throw new IllegalStateException(
                        "Text event reports an invalid buffer region: offset=" + offset + " len=" + len
                                + " bufferSize=" + buffer.length);
            }
            this.events.add("text[" + line + "," + col + "]:" + escape(new String(buffer, offset, len)));
        }

