        assertEquals(1, handler.documentEndCount);

        // The document start event always reports the very first position of the document
        assertEquals(1, handler.startLine);
        assertEquals(1, handler.startCol);

        // The document end position has been fast-forwarded past the trailing text that was reported
        assertEquals(1, handler.endLine);
        assertEquals(12, handler.endCol);

        // The reported timings must be coherent with the event timestamps
        assertTrue(handler.endTimeNanos >= handler.startTimeNanos);
        assertEquals(handler.endTimeNanos - handler.startTimeNanos, handler.totalTimeNanos);

    }


    @Test
    public void testEmptyDocumentProducesNoTextEvents() throws Exception {

        final RecordingHandler handler = parseDocument("", 32, 0, false);

        assertEquals(List.of("documentStart[1,1]", "documentEnd[1,1]"), handler.events);
        assertEquals(1, handler.documentStartCount);
        assertEquals(1, handler.documentEndCount);
        assertEquals(1, handler.endLine);
        assertEquals(1, handler.endCol);

    }


    @Test
    public void testTextIsReportedAsOneEventRegardlessOfLineBreaks() throws Exception {

        final RecordingHandler handler = parseDocument("line1\nline2\n", 64, 0, false);

        // Text is reported incrementally, so newlines inside it do not split the event
        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:line1\\nline2\\n", "documentEnd[3,1]"),
                handler.events);
        assertEquals(3, handler.endLine);
        assertEquals(1, handler.endCol);

    }


    @Test
    public void testTextWithoutTrailingNewlineAdvancesColumnOnly() throws Exception {

        final RecordingHandler handler = parseDocument("ab\ncd", 64, 0, false);

        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:ab\\ncd", "documentEnd[2,3]"),
                handler.events);
        assertEquals(2, handler.endLine);
        assertEquals(3, handler.endCol);

    }


    /*
     * ------------------------------------------------------------------------
     * Structures: elements, attributes, comments and literals
     * ------------------------------------------------------------------------
     */

    @Test
    public void testOpenAndCloseElementsAreReported() throws Exception {

        final RecordingHandler handler = parseDocument("[#myelement]some text[/myelement]", 64, 0, false);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "openStart[1,1]:myelement",
                        "openEnd[1,12]:myelement",
                        "text[1,13]:some text",
                        "closeStart[1,22]:myelement",
                        "closeEnd[1,33]:myelement",
                        "documentEnd[1,34]"),
                handler.events);

    }


    @Test
    public void testStandaloneElementIsReportedAsMinimized() throws Exception {

        final RecordingHandler handler = parseDocument("[#myelement /]", 64, 0, false);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "standaloneStart[1,1]:myelement:minimized=true",
                        "standaloneEnd[1,13]:myelement:minimized=true",
                        "documentEnd[1,15]"),
                handler.events);

    }


    @Test
    public void testElementAttributesAreReportedWithTheirValues() throws Exception {

        final RecordingHandler handler = parseDocument(
                "[#elem attr1=\"value1\" attr2='value2']text[/elem]", 64, 0, false);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "openStart[1,1]:elem",
                        "attribute[1,8]:attr1=\"value1\"",
                        "attribute[1,23]:attr2='value2'",
                        "openEnd[1,37]:elem",
                        "text[1,38]:text",
                        "closeStart[1,42]:elem",
                        "closeEnd[1,48]:elem",
                        "documentEnd[1,49]"),
                handler.events);

    }


    @Test
    public void testLineAndColumnAreTrackedInsideStructures() throws Exception {

        final RecordingHandler handler = parseDocument("[#elem]line1\nline2[/elem]tail", 64, 0, false);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "openStart[1,1]:elem",
                        "openEnd[1,7]:elem",
                        "text[1,8]:line1\\nline2",
                        "closeStart[2,6]:elem",
                        "closeEnd[2,12]:elem",
                        "text[2,13]:tail",
                        "documentEnd[2,17]"),
                handler.events);

    }


    @Test
    public void testCommentBlocksAreReportedWhenCommentsAreProcessed() throws Exception {

        final RecordingHandler handler = parseDocument("preamble /* c1 */ middle", 64, 0, true);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:preamble ",
                        "comment[1,10]: c1 ",
                        "text[1,18]: middle",
                        "documentEnd[1,25]"),
                handler.events);

    }


    @Test
    public void testCommentBlocksAreJustTextWhenCommentsAreNotProcessed() throws Exception {

        final RecordingHandler handler = parseDocument("preamble /* c1 */ middle", 64, 0, false);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:preamble /* c1 */ middle",
                        "documentEnd[1,25]"),
                handler.events);

    }


    @Test
    public void testCommentLineIsReportedAsTextWhenCommentsAreProcessed() throws Exception {

        final RecordingHandler handler = parseDocument("a // a comment line\nb", 64, 0, true);

        // Comment lines are not parsed specially: they are reported as mere text (including the newline)
        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:a ",
                        "text[1,3]:// a comment line\\n",
                        "text[2,1]:b",
                        "documentEnd[2,2]"),
                handler.events);

    }


    @Test
    public void testLiteralsProtectStructureSyntaxWhenLiteralsAreProcessed() throws Exception {

        // With literal processing, the '[#tag]' sequence inside the quoted literal is not a structure
        final RecordingHandler withLiterals = parseDocument("x '[#tag]' y", 64, 0, true);
        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:x '[#tag]' y",
                        "documentEnd[1,13]"),
                withLiterals.events);

        // Without literal processing, the very same text contains a perfectly valid open element
        final RecordingHandler withoutLiterals = parseDocument("x '[#tag]' y", 64, 0, false);
        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:x '",
                        "openStart[1,4]:tag",
                        "openEnd[1,9]:tag",
                        "text[1,10]:' y",
                        "documentEnd[1,13]"),
                withoutLiterals.events);

    }


    /*
     * ------------------------------------------------------------------------
     * Chunked reading, buffer growth and buffer shifting
     * ------------------------------------------------------------------------
     */

    @Test
    public void testEventStreamDoesNotDependOnBufferSizeNorReadChunking() throws Exception {

        final String[] documents = new String[] {
                "[#elem attr1=\"value1\" attr2='value2']text[/elem]",
                "[#elem]line1\nline2[/elem]tail",
                "preamble /* c1 */ middle /* c2 */ end",
                "x \"lit\nwith\nnewlines\" y [#a]z[/a]",
                "1234567890123456789012345678901234567890",
                "a\nb\nc\nd\ne\nf\ng\nh\ni\nj",
                "[#a][#b][#c]t[/c][/b][/a]",
                "[#elem /]text[#elem2/]"
        };

        for (final String document : documents) {

            final RecordingHandler reference = parseDocument(document, 128, 0, true);

            assertFalse(reference.events.isEmpty());
            assertEquals("documentStart[1,1]", reference.events.get(0));
            assertTrue(reference.events.get(reference.events.size() - 1).startsWith("documentEnd["));

            for (final int bufferSize : new int[] {6, 7, 9, 13, 100}) {
                for (final int chunkSize : new int[] {1, 2, 5, 40}) {
                    final RecordingHandler actual = parseDocument(document, bufferSize, chunkSize, true);
                    assertEquals(
                            reference.events, actual.events,
                            "Different events for document \"" + document + "\" with bufferSize=" + bufferSize
                                    + " and chunkSize=" + chunkSize);
                    assertEquals(reference.endLine, actual.endLine);
                    assertEquals(reference.endCol, actual.endCol);
                }
            }

        }

    }


    @Test
    public void testBufferIsGrownForTextLargerThanTheBuffer() throws Exception {

        final String document = "0123456789012345678901234567890123456789"; // 40 characters

        final RecordingHandler handler = parseDocument(document, 6, 0, false);

        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:" + document, "documentEnd[1,41]"),
                handler.events);

    }


    @Test
    public void testStructureLargerThanTheBufferIsParsedCorrectly() throws Exception {

        final String document = "[#elem attr1=\"value1\" attr2='value2']text[/elem]";

        final RecordingHandler reference = parseDocument(document, 128, 0, false);
        final RecordingHandler smallBuffer = parseDocument(document, 8, 3, false);

        assertEquals(reference.events, smallBuffer.events);
        assertEquals(9, reference.events.size());
        assertTrue(reference.events.contains("attribute[1,8]:attr1=\"value1\""));
        assertTrue(reference.events.contains("attribute[1,23]:attr2='value2'"));

    }


    @Test
    public void testSuggestedBufferSizeDifferentFromPoolBufferSize() throws Exception {

        // The pool only provides buffers of its own size, so a different suggested size means a non-pooled buffer
        final TextParser textParser = parser(2, 32, false, true);

        final String document = "alpha [#e]beta[/e] gamma";

        final RecordingHandler small = parse(textParser, new StringReader(document), 5);
        final RecordingHandler large = parse(textParser, new StringReader(document), 64);

        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "text[1,1]:alpha ",
                        "openStart[1,7]:e",
                        "openEnd[1,10]:e",
                        "text[1,11]:beta",
                        "closeStart[1,15]:e",
                        "closeEnd[1,18]:e",
                        "text[1,19]: gamma",
                        "documentEnd[1,25]"),
                small.events);
        assertEquals(small.events, large.events);

    }


    @Test
    public void testParserInstanceCanBeReusedForSeveralDocuments() throws Exception {

        final TextParser textParser = parser(2, 16, false, true);

        final RecordingHandler first = parse(textParser, new StringReader("[#a]first[/a]"), 16);
        final RecordingHandler second = parse(textParser, new StringReader("[#b]second[/b]"), 16);
        final RecordingHandler third = parse(textParser, new StringReader("[#a]first[/a]"), 16);

        // No leftovers from previously parsed documents must leak into the pooled buffers
        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "openStart[1,1]:a",
                        "openEnd[1,4]:a",
                        "text[1,5]:first",
                        "closeStart[1,10]:a",
                        "closeEnd[1,13]:a",
                        "documentEnd[1,14]"),
                first.events);
        assertEquals(
                List.of(
                        "documentStart[1,1]",
                        "openStart[1,1]:b",
                        "openEnd[1,4]:b",
                        "text[1,5]:second",
                        "closeStart[1,11]:b",
                        "closeEnd[1,14]:b",
                        "documentEnd[1,15]"),
                second.events);
        assertEquals(first.events, third.events);

    }


    /*
     * ------------------------------------------------------------------------
     * Invalid / incomplete input
     * ------------------------------------------------------------------------
     */

    @Test
    public void testIncompleteStructureAtEndOfDocumentThrows() throws Exception {

        final ChunkReader reader = new ChunkReader("text [#myelement", 0);

        final RecordingHandler handler = new RecordingHandler();
        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> parser(2, 16, false, true).parseDocument(reader, 16, handler));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("Incomplete structure"));
        assertTrue(exception.getMessage().contains("[#myelement"));
        assertEquals(Integer.valueOf(1), exception.getLine());
        assertEquals(Integer.valueOf(6), exception.getCol());

        // The document could not be fully parsed, so no end event was issued, and the reader was closed anyway
        assertEquals(List.of("documentStart[1,1]"), handler.events);
        assertTrue(reader.closed);

    }


    @Test
    public void testIncompleteStructureInSecondLineReportsItsPosition() throws Exception {

        final RecordingHandler handler = new RecordingHandler();
        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> parser(2, 16, false, true)
                        .parseDocument(new StringReader("line1\nline2 [#elem"), 16, handler));

        assertTrue(exception.getMessage().contains("Incomplete structure"));
        assertTrue(exception.getMessage().contains("[#elem"));
        assertEquals(Integer.valueOf(2), exception.getLine());
        assertEquals(Integer.valueOf(7), exception.getCol());
        assertEquals(List.of("documentStart[1,1]"), handler.events);

    }


    @Test
    public void testUnterminatedCommentLineAtEndOfDocumentIsReportedAsText() throws Exception {

        // A comment line that reaches the end of the document is not an incomplete structure
        final RecordingHandler handler = parseDocument("a // comment", 64, 0, true);

        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:a ", "text[1,3]:// comment", "documentEnd[1,13]"),
                handler.events);

    }


    /*
     * ------------------------------------------------------------------------
     * Exception translation and resource handling
     * ------------------------------------------------------------------------
     */

    @Test
    public void testReaderIsClosedAfterSuccessfulParsing() throws Exception {

        final ChunkReader reader = new ChunkReader("hello", 2);

        final RecordingHandler handler = parse(parser(2, 8, false, true), reader, 8);

        assertTrue(reader.closed);
        assertEquals(List.of("documentStart[1,1]", "text[1,1]:hello", "documentEnd[1,6]"), handler.events);

    }


    @Test
    public void testIOExceptionFromReaderIsWrappedInTextParseException() throws Exception {

        // The reader fails once 4 characters have already been read
        final ChunkReader reader = new ChunkReader("abcdefgh", 2, 4, false);

        final RecordingHandler handler = new RecordingHandler();
        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> parser(2, 8, false, true).parseDocument(reader, 8, handler));

        assertInstanceOf(IOException.class, exception.getCause());
        assertEquals("Simulated read failure at position 4", exception.getCause().getMessage());
        assertTrue(reader.closed);
        assertEquals(List.of("documentStart[1,1]"), handler.events);

    }


    @Test
    public void testTextParseExceptionFromHandlerIsPropagatedUnchanged() throws Exception {

        final TextParseException expected = new TextParseException("handler failure", 3, 4);
        final ChunkReader reader = new ChunkReader("hello", 2);

        final List<String> events = new ArrayList<>();
        final TextParseException actual = assertThrows(
                TextParseException.class,
                () -> parser(2, 8, false, true).parseDocument(reader, 8, new AbstractTextHandler() {
                    @Override
                    public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
                        events.add("documentStart");
                    }
                    @Override
                    public void handleText(
                            final char[] buffer, final int offset, final int len, final int line, final int col)
                            throws TextParseException {
                        throw expected;
                    }
                    @Override
                    public void handleDocumentEnd(
                            final long endTimeNanos, final long totalTimeNanos, final int line, final int col) {
                        events.add("documentEnd");
                    }
                }));

        // TextParseExceptions thrown by the handler are not wrapped
        assertSame(expected, actual);
        assertEquals(Integer.valueOf(3), actual.getLine());
        assertEquals(Integer.valueOf(4), actual.getCol());
        assertEquals(List.of("documentStart"), events);
        assertTrue(reader.closed);

    }


    @Test
    public void testRuntimeExceptionFromHandlerIsWrappedInTextParseException() throws Exception {

        final IllegalStateException failure = new IllegalStateException("handler blew up");
        final ChunkReader reader = new ChunkReader("hello", 2);

        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> parser(2, 8, false, true).parseDocument(reader, 8, new AbstractTextHandler() {
                    @Override
                    public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
                        throw failure;
                    }
                }));

        assertSame(failure, exception.getCause());
        assertEquals("handler blew up", exception.getMessage());
        assertTrue(reader.closed);

    }


    @Test
    public void testExceptionOnReaderCloseIsIgnored() throws Exception {

        final ChunkReader reader = new ChunkReader("hello", 2, Integer.MAX_VALUE, true);

        final RecordingHandler handler = parse(parser(2, 8, false, true), reader, 8);

        // Closing the reader fails, but that must not affect the result of the parsing operation
        assertTrue(reader.closed);
        assertEquals(List.of("documentStart[1,1]", "text[1,1]:hello", "documentEnd[1,6]"), handler.events);

    }


    @Test
    public void testNullBufferReleaseIsSafeWhenHandlerFailsOnDocumentStart() throws Exception {

        // The handler fails before the buffer is allocated: the "finally" block must tolerate a null buffer
        final ChunkReader reader = new ChunkReader("hello", 2);

        assertThrows(
                TextParseException.class,
                () -> parser(2, 8, false, true).parseDocument(reader, 8, new AbstractTextHandler() {
                    @Override
                    public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
                        throw new IllegalArgumentException("no document start for you");
                    }
                }));

        assertTrue(reader.closed);

    }


    @Test
    public void testHandlerReceivesOnlyValidBufferRegionsForLargeDocuments() throws Exception {

        final StringBuilder documentBuilder = new StringBuilder();
        for (int i = 0; i < 200; i++) {
            documentBuilder.append("chunk").append(i % 10).append('\n');
        }
        final String document = documentBuilder.toString();

        final RecordingHandler handler = parseDocument(document, 16, 7, false);

        // All the text has been reported, split in as many events as needed but without losing any character
        final StringBuilder recovered = new StringBuilder();
        for (final String event : handler.events) {
            if (event.startsWith("text[")) {
                recovered.append(event.substring(event.indexOf(':') + 1).replace("\\n", "\n"));
            }
        }
        assertEquals(document, recovered.toString());
        assertEquals(200 + 1, handler.endLine);
        assertEquals(1, handler.endCol);

    }


}
