package org.thymeleaf.templateparser.text;

import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;


/**
 * Tests for {@link TextParser#parseDocument(Reader, int, ITextHandler)}.
 */
public class TextParserParseDocumentTests {


    /*
     * ------------------------------------------------------------------------
     * Infrastructure
     * ------------------------------------------------------------------------
     */

    /**
     * A handler that records every event it receives as a human readable string, so that both the
     * sequence and the contents of the events can be asserted.
     */
    static final class RecordingHandler extends AbstractTextHandler {

        final List<String> events = new ArrayList<>();

        long startTimeNanos = Long.MIN_VALUE;
        long endTimeNanos = Long.MIN_VALUE;
        long totalTimeNanos = Long.MIN_VALUE;
        int startLine = -1;
        int startCol = -1;
        int endLine = -1;
        int endCol = -1;

        int documentStartCount = 0;
        int documentEndCount = 0;

        @Override
        public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
            this.documentStartCount++;
            this.startTimeNanos = startTimeNanos;
            this.startLine = line;
            this.startCol = col;
            this.events.add("documentStart[" + line + "," + col + "]");
        }

        @Override
        public void handleDocumentEnd(
                final long endTimeNanos, final long totalTimeNanos, final int line, final int col) {
            this.documentEndCount++;
            this.endTimeNanos = endTimeNanos;
            this.totalTimeNanos = totalTimeNanos;
            this.endLine = line;
            this.endCol = col;
            this.events.add("documentEnd[" + line + "," + col + "]");
        }

        @Override
        public void handleText(
                final char[] buffer, final int offset, final int len, final int line, final int col) {
            // Sanity check on the reported region: it must be a valid region of the buffer
            if (offset < 0 || len < 0 || (offset + len) > buffer.length) {
                throw new IllegalStateException(
                        "Text event reports an invalid buffer region: offset=" + offset + " len=" + len
                                + " bufferSize=" + buffer.length);
            }
            this.events.add("text[" + line + "," + col + "]:" + escape(new String(buffer, offset, len)));
        }

        @Override
        public void handleComment(
                final char[] buffer, final int contentOffset, final int contentLen,
                final int outerOffset, final int outerLen, final int line, final int col) {
            this.events.add(
                    "comment[" + line + "," + col + "]:" + escape(new String(buffer, contentOffset, contentLen)));
        }

        @Override
        public void handleStandaloneElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final boolean minimized,
                final int line, final int col) {
            this.events.add("standaloneStart[" + line + "," + col + "]:"
                    + new String(buffer, nameOffset, nameLen) + ":minimized=" + minimized);
        }

        @Override
        public void handleStandaloneElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final boolean minimized,
                final int line, final int col) {
            this.events.add("standaloneEnd[" + line + "," + col + "]:"
                    + new String(buffer, nameOffset, nameLen) + ":minimized=" + minimized);
        }

        @Override
        public void handleOpenElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("openStart[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleOpenElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("openEnd[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleCloseElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("closeStart[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleCloseElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("closeEnd[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleAttribute(
                final char[] buffer,
                final int nameOffset, final int nameLen, final int nameLine, final int nameCol,
                final int operatorOffset, final int operatorLen, final int operatorLine, final int operatorCol,
                final int valueContentOffset, final int valueContentLen,
                final int valueOuterOffset, final int valueOuterLen, final int valueLine, final int valueCol) {
            this.events.add("attribute[" + nameLine + "," + nameCol + "]:"
                    + new String(buffer, nameOffset, nameLen)
                    + new String(buffer, operatorOffset, operatorLen)
                    + escape(new String(buffer, valueOuterOffset, valueOuterLen)));
        }

        private static String escape(final String text) {
            return text.replace("\n", "\\n");
        }

    }


    /**
     * A reader that returns at most {@code chunkSize} characters per {@code read} call, so that the
     * multiple-reads / buffer-shifting logic of the parser can be exercised deterministically.
     */
    static final class ChunkReader extends Reader {

        private final String content;
        private final int chunkSize;
        private final int failAfterChars;
        private final boolean failOnClose;

        private int pos = 0;
        boolean closed = false;

        ChunkReader(final String content, final int chunkSize) {
            this(content, chunkSize, Integer.MAX_VALUE, false);
        }

        ChunkReader(final String content, final int chunkSize, final int failAfterChars, final boolean failOnClose) {
            this.content = content;
            this.chunkSize = chunkSize;
            this.failAfterChars = failAfterChars;
            this.failOnClose = failOnClose;
        }

        @Override
        public int read(final char[] cbuf, final int off, final int len) throws IOException {
            if (this.pos >= this.failAfterChars) {
                throw new IOException("Simulated read failure at position " + this.pos);
            }
            if (this.pos >= this.content.length()) {
                return -1;
            }
            final int n = Math.min(Math.min(this.chunkSize, len), this.content.length() - this.pos);
            this.content.getChars(this.pos, this.pos + n, cbuf, off);
            this.pos += n;
            return n;
        }

        @Override
        public void close() throws IOException {
            this.closed = true;
            if (this.failOnClose) {
                throw new IOException("Simulated close failure");
            }
        }

    }


    private static TextParser parser(
            final int poolSize, final int poolBufferSize,
            final boolean processCommentsAndLiterals, final boolean standardDialectPresent) {
        return new TextParser(poolSize, poolBufferSize, processCommentsAndLiterals, standardDialectPresent);
    }


    private static RecordingHandler parse(
            final TextParser textParser, final Reader reader, final int suggestedBufferSize)
            throws TextParseException {
        final RecordingHandler handler = new RecordingHandler();
        textParser.parseDocument(reader, suggestedBufferSize, handler);
        return handler;
    }


    private static RecordingHandler parseDocument(
            final String document, final int bufferSize, final int chunkSize,
            final boolean processCommentsAndLiterals) throws TextParseException {
        final Reader reader = (chunkSize > 0 ?
                new ChunkReader(document, chunkSize) : new StringReader(document));
        return parse(parser(3, bufferSize, processCommentsAndLiterals, true), reader, bufferSize);
    }


    /*
     * ------------------------------------------------------------------------
     * Plain text documents
     * ------------------------------------------------------------------------
     */

    @Test
    public void testPlainTextDocumentReportsStartTextAndEnd() throws Exception {

        final RecordingHandler handler = parseDocument("Hello World", 64, 0, false);

        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:Hello World", "documentEnd[1,12]"),
                handler.events);

        assertEquals(1, handler.documentStartCount);
        assertEquals(1, handler.documentEndCount);

        // The document start event always reports the very first position of the document
        assertEquals(1, handler.startLine);
        assertEquals(1, handler.startCol);

        // The document end position has been fast-forwarded past the trailing text that was reported
        assertEquals(1, handler.endLine);
        assertEquals(12, handler.endCol);

        // The reported timings must be coherent with the event timestamps
        assertTrue(handler.endTimeNanos >= handler.startTimeNanos);
        assertEquals(handler.endTimeNanos - handler.startTimeNanos, handler.totalTimeNanos);

    }


    @Test
    public void testEmptyDocumentProducesNoTextEvents() throws Exception {

        final RecordingHandler handler = parseDocument("", 32, 0, false);

        assertEquals(List.of("documentStart[1,1]", "documentEnd[1,1]"), handler.events);
        assertEquals(1, handler.documentStartCount);
        assertEquals(1, handler.documentEndCount);
        assertEquals(1, handler.endLine);
        assertEquals(1, handler.endCol);

    }


    @Test
    public void testTextIsReportedAsOneEventRegardlessOfLineBreaks() throws Exception {

        final RecordingHandler handler = parseDocument("line1\nline2\n", 64, 0, false);

        // Text is reported incrementally, so newlines inside it do not split the event
        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:line1\\nline2\\n", "documentEnd[3,1]"),
                handler.events);
        assertEquals(3, handler.endLine);
        assertEquals(1, handler.endCol);

    }


    @Test
    public void testTextWithoutTrailingNewlineAdvancesColumnOnly() throws Exception {

        final RecordingHandler handler = parseDocument("ab\ncd", 64, 0, false);

        assertEquals(
                List.of("documentStart[1,1]", "text[1,1]:ab\\ncd", "documentEnd[2,3]"),
                handler.events);
        assertEquals(2, handler.endLine);
        assertEquals(3, handler.endCol);

    }


