    @Test
    public void testIncompleteStructureAtEndOfDocumentThrows() throws Exception {

        final ChunkReader reader = new ChunkReader("text [#myelement", 0);

        final RecordingHandler handler = new RecordingHandler();
        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> parser(2, 16, false, true).parseDocument(reader, 16, handler));

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("Incomplete structure"));
        assertTrue(exception.getMessage().contains("[#myelement"));
        assertEquals(Integer.valueOf(1), exception.getLine());
        assertEquals(Integer.valueOf(6), exception.getCol());

