public class TextParserParseDocumentTests {


    /*
     * ------------------------------------------------------------------------
     * Infrastructure
     * ------------------------------------------------------------------------
     */

    /**
     * A handler that records every event it receives as a human readable string, so that both the
     * sequence and the contents of the events can be asserted.
     */
    static final class RecordingHandler extends AbstractTextHandler {

        final List<String> events = new ArrayList<>();

        long startTimeNanos = Long.MIN_VALUE;
        long endTimeNanos = Long.MIN_VALUE;
        long totalTimeNanos = Long.MIN_VALUE;
        int startLine = -1;
        int startCol = -1;
        int endLine = -1;
        int endCol = -1;

        int documentStartCount = 0;
        int documentEndCount = 0;

        @Override
        public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
            this.documentStartCount++;
            this.startTimeNanos = startTimeNanos;
            this.startLine = line;
            this.startCol = col;
            this.events.add("documentStart[" + line + "," + col + "]");
        }

        @Override
        public void handleDocumentEnd(
                final long endTimeNanos, final long totalTimeNanos, final int line, final int col) {
            this.documentEndCount++;
            this.endTimeNanos = endTimeNanos;
            this.totalTimeNanos = totalTimeNanos;
            this.endLine = line;
            this.endCol = col;
            this.events.add("documentEnd[" + line + "," + col + "]");
        }

        @Override
        public void handleText(
                final char[] buffer, final int offset, final int len, final int line, final int col) {
            // Sanity check on the reported region: it must be a valid region of the buffer
            if (offset < 0 || len < 0 || (offset + len) > buffer.length) {
                throw new IllegalStateException(
                        "Text event reports an invalid buffer region: offset=" + offset + " len=" + len
                                + " bufferSize=" + buffer.length);
            }
            this.events.add("text[" + line + "," + col + "]:" + escape(new String(buffer, offset, len)));
        }

        @Override
        public void handleComment(
                final char[] buffer, final int contentOffset, final int contentLen,
                final int outerOffset, final int outerLen, final int line, final int col) {
            this.events.add(
                    "comment[" + line + "," + col + "]:" + escape(new String(buffer, contentOffset, contentLen)));
        }

        @Override
        public void handleStandaloneElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final boolean minimized,
                final int line, final int col) {
            this.events.add("standaloneStart[" + line + "," + col + "]:"
                    + new String(buffer, nameOffset, nameLen) + ":minimized=" + minimized);
        }

        @Override
        public void handleStandaloneElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final boolean minimized,
                final int line, final int col) {
            this.events.add("standaloneEnd[" + line + "," + col + "]:"
                    + new String(buffer, nameOffset, nameLen) + ":minimized=" + minimized);
        }

        @Override
        public void handleOpenElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("openStart[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleOpenElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("openEnd[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleCloseElementStart(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("closeStart[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleCloseElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen, final int line, final int col) {
            this.events.add("closeEnd[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleAttribute(
                final char[] buffer,
                final int nameOffset, final int nameLen, final int nameLine, final int nameCol,
                final int operatorOffset, final int operatorLen, final int operatorLine, final int operatorCol,
                final int valueContentOffset, final int valueContentLen,
                final int valueOuterOffset, final int valueOuterLen, final int valueLine, final int valueCol) {
            this.events.add("attribute[" + nameLine + "," + nameCol + "]:"
                    + new String(buffer, nameOffset, nameLen)
                    + new String(buffer, operatorOffset, operatorLen)
                    + escape(new String(buffer, valueOuterOffset, valueOuterLen)));
        }

        private static String escape(final String text) {
            return text.replace("\n", "\\n");
        }

