    int i = 0;

    int m1 = 0;
    int n1 = 0;
    int len1 = this.values[m1].length();

    while (i < this.length) {

        // Move to the next value array if needed, including skipping those with len == 0
        while (n1 >= len1 && (m1 + 1) < this.values.length) {
