    // Reference equality and non-AggregateCharSequence arguments
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns true for the very same instance")
    public void testSameInstanceIsEqual() {
        final AggregateCharSequence a = agg("abc", "def");
        assertTrue(a.equals(a));
        // Same instance, even after the hash value has been cached
        assertTrue(a.hashCode() != 0 || a.length() == 0);
        assertTrue(a.equals(a));
    }

    @Test
    @DisplayName("equals() returns true for the same empty instance")
    public void testSameEmptyInstanceIsEqual() {
        final AggregateCharSequence a = agg();
        assertTrue(a.equals(a));
        assertEquals(0, a.length());
    }

    @Test
    @DisplayName("equals() returns false for null")
    public void testNullIsNotEqual() {
        final AggregateCharSequence a = agg("abc");
        assertFalse(a.equals(null));
        assertFalse(agg().equals(null));
    }

    @Test
    @DisplayName("equals() returns false for unrelated types")
    public void testOtherTypesAreNotEqual() {
        final AggregateCharSequence a = agg("abc", "def");

        assertFalse(a.equals("abcdef"));
        assertFalse(a.equals(new StringBuilder("abcdef")));
        assertFalse(a.equals(new StringBuffer("abcdef")));
        assertFalse(a.equals(Integer.valueOf(0)));
        assertFalse(a.equals(new Object()));

        final AggregateCharSequence empty = agg();
        assertFalse(empty.equals(""));
        assertFalse(empty.equals(new StringBuilder()));
    }


    // ----------------------------------------------------------------------
    // Single-component String fast path
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns true for two single-String sequences with equal text")
    public void testSingleStringEqual() {
        assertTrue(agg("abc").equals(agg("abc")));
        assertTrue(agg("").equals(agg("")));
        assertTrue(agg("a").equals(agg("a")));
    }

    @Test
    @DisplayName("equals() returns false for two single-String sequences with different text")
    public void testSingleStringDifferentSameLength() {
        assertFalse(agg("abc").equals(agg("abd")));
        assertFalse(agg("a").equals(agg("b")));
        assertFalse(agg("Abc").equals(agg("abc")));
    }

    @Test
    @DisplayName("equals() returns false for two single-String sequences of different length")
    public void testSingleStringDifferentLength() {
        assertFalse(agg("abc").equals(agg("ab")));
        assertFalse(agg("").equals(agg("a")));
        assertFalse(agg("a").equals(agg("")));
    }


    // ----------------------------------------------------------------------
    // Length handling and empty sequences
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns false when the aggregated lengths differ")
    public void testDifferentLengthsAreNotEqual() {
        assertFalse(agg("abc", "def").equals(agg("abc", "de")));
        assertFalse(agg("abc", "de").equals(agg("abc", "def")));
        assertFalse(agg("abc", "def").equals(agg("abcdefg")));
        assertFalse(agg("abcdef").equals(agg("abc", "def", "g")));
    }

    @Test
    @DisplayName("equals() returns true for all the representations of the empty sequence")
    public void testEmptySequencesAreEqual() {
        final AggregateCharSequence fromEmptyArray = agg();
        final AggregateCharSequence fromEmptyList = new AggregateCharSequence(Collections.<CharSequence>emptyList());
