        final AggregateCharSequence fromTwoEmptyStrings = agg("", "");
        final AggregateCharSequence fromThreeEmptyStrings = agg("", "", "");

        final AggregateCharSequence[] all =
                new AggregateCharSequence[] {
                        fromEmptyArray, fromEmptyList, fromEmptyString,
                        fromTwoEmptyStrings, fromThreeEmptyStrings};

        for (int i = 0; i < all.length; i++) {
            for (int j = 0; j < all.length; j++) {
                assertEquals(0, all[i].length());
                assertTrue(all[i].equals(all[j]),
                        "Empty sequences at positions " + i + " and " + j + " should be equal");
