        assertTrue(agg("abcdef").equals(agg("abc", "def")));
        assertTrue(agg("a", "b", "c").equals(agg("ab", "c")));
        assertTrue(agg("aab", "b").equals(agg("aa", "bb")));
        assertTrue(agg("abcd", "efgh", "ijkl").equals(agg("abcde", "fghijkl")));
    }

