                agg("a"),
                agg("abc"),
                agg("abc", "def"),
                agg("abcdef"),
                agg("ab", "cdef"),
                agg("", "abc", ""),
                agg("abd", "def"),
                agg("abc", "de"),
                agg(new StringBuilder("abc"), "def")
        };

        for (int i = 0; i < sequences.length; i++) {
            for (int j = 0; j < sequences.length; j++) {
                final boolean forward = sequences[i].equals(sequences[j]);
                final boolean backward = sequences[j].equals(sequences[i]);
                assertEquals(forward, backward,
                        "equals() must be symmetric for indices " + i + " and " + j);
                if (forward) {
                    assertEquals(sequences[i].length(), sequences[j].length());
                    assertEquals(sequences[i].hashCode(), sequences[j].hashCode(),
                            "Equal sequences must have equal hash codes (indices " + i + " and " + j + ")");
                }
            }
        }
    }

    @Test
    @DisplayName("equals() is reflexive for every sequence")
    public void testReflexivity() {
        final AggregateCharSequence[] sequences = new AggregateCharSequence[] {
                agg(),
                agg(""),
                agg("abc"),
                agg("abc", "def"),
                agg(new StringBuilder("abc"), "def", new StringBuilder("ghi"))
        };

        for (final AggregateCharSequence sequence : sequences) {
            assertTrue(sequence.equals(sequence));
            // Reflexivity also holds after the hash has been cached
            sequence.hashCode();
            assertTrue(sequence.equals(sequence));
        }
    }

    @Test
    @DisplayName("equals() is transitive for equal sequences with different partitions")
    public void testTransitivity() {
        final AggregateCharSequence a = agg("abc", "def");
        final AggregateCharSequence b = agg("ab", "cd", "ef");
        final AggregateCharSequence c = agg("a", "b", "c", "d", "e", "f");

        assertTrue(a.equals(b));
        assertTrue(b.equals(c));
        assertTrue(a.equals(c));
        assertTrue(c.equals(a));
    }


    private static final class PlainCharSequence implements CharSequence {

        private final String text;

        PlainCharSequence(final String text) {
            super();
            this.text = text;
        }

        public int length() {
            return this.text.length();
        }

        public char charAt(final int index) {
            return this.text.charAt(index);
        }

        public CharSequence subSequence(final int start, final int end) {
            return new PlainCharSequence(this.text.substring(start, end));
        }

        @Override
        public String toString() {
            return this.text;
        }

    }

