package org.thymeleaf.util;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

class EvaluationUtilsEvaluateAsListTests {

    @Test
    void nullValueReturnsAnEmptyUnmodifiableList() {
        final List<Object> result = EvaluationUtils.evaluateAsList(null);

        assertNotNull(result);
        assertTrue(result.isEmpty());
        assertListIsUnmodifiable(result);
    }

    @Test
    void nonIterableNonMapNonArrayValuesAreReturnedAsSingleElementLists() {
        final Object marker = new Object();
        final List<Object> markerResult = EvaluationUtils.evaluateAsList(marker);

        assertEquals(1, markerResult.size());
        assertSame(marker, markerResult.get(0));
        assertListIsUnmodifiable(markerResult);

        final List<Object> stringResult = EvaluationUtils.evaluateAsList("text");
        assertEquals(Collections.singletonList("text"), stringResult);
        assertListIsUnmodifiable(stringResult);
    }

    @Test
    void iterableIsCopiedInIterationOrderIncludingDuplicatesAndNulls() {
        final Object first = new Object();
        final Iterable<Object> source = Arrays.asList(first, null, first);

        final List<Object> result = EvaluationUtils.evaluateAsList(source);

        assertEquals(3, result.size());
        assertSame(first, result.get(0));
        assertNull(result.get(1));
        assertSame(first, result.get(2));
        assertNotSame(source, result);
        assertListIsUnmodifiable(result);
    }

    @Test
    void iterableResultIsASnapshotOfTheSource() {
        final List<String> source = new ArrayList<String>();
        source.add("original");

        final List<Object> result = EvaluationUtils.evaluateAsList(source);
        source.add("later");
        source.set(0, "changed");

        assertEquals(Collections.singletonList("original"), result);
    }

    @Test
    void mapIsConvertedToIndependentEntryObjectsInIterationOrder() {
        final Map<String, Integer> source = new LinkedHashMap<String, Integer>();
        source.put("one", Integer.valueOf(1));
        source.put("two", Integer.valueOf(2));

        final List<Object> result = EvaluationUtils.evaluateAsList(source);

        assertEquals(2, result.size());
        final Map.Entry<Object, Object> first = asEntry(result.get(0));
        final Map.Entry<Object, Object> second = asEntry(result.get(1));
        assertEquals(new AbstractMap.SimpleImmutableEntry<String, Integer>("one", Integer.valueOf(1)), first);
        assertEquals(new AbstractMap.SimpleImmutableEntry<String, Integer>("two", Integer.valueOf(2)), second);
        assertNotSame(first, second);

        final Map.Entry<String, Integer> originalFirst = source.entrySet().iterator().next();
        assertNotSame(originalFirst, first);
        assertThrows(UnsupportedOperationException.class,
                () -> first.setValue(Integer.valueOf(99)));

        assertListIsUnmodifiable(result);
    }

    @Test
    void mapResultIsASnapshotOfKeysAndValues() {
        final Map<String, Integer> source = new LinkedHashMap<String, Integer>();
        source.put("number", Integer.valueOf(1));

        final List<Object> result = EvaluationUtils.evaluateAsList(source);
        source.put("number", Integer.valueOf(2));
        source.put("other", Integer.valueOf(3));

        assertEquals(1, result.size());
        final Map.Entry<Object, Object> entry = asEntry(result.get(0));
        assertEquals("number", entry.getKey());
        assertEquals(Integer.valueOf(1), entry.getValue());
    }

    @Test
    void mapWithNullKeyAndNullValueIsPreserved() {
        final Map<String, String> source = new LinkedHashMap<String, String>();
        source.put(null, null);
        source.put("key", null);

        final List<Object> result = EvaluationUtils.evaluateAsList(source);

        assertEquals(2, result.size());
        final Map.Entry<Object, Object> nullEntry = asEntry(result.get(0));
        assertNull(nullEntry.getKey());
        assertNull(nullEntry.getValue());
        final Map.Entry<Object, Object> keyOnlyEntry = asEntry(result.get(1));
        assertEquals("key", keyOnlyEntry.getKey());
        assertNull(keyOnlyEntry.getValue());
    }

    @Test
    void enumMapProducesDistinctEntriesRatherThanReusingIteratorEntryInstances() {
        final EnumMap<TestKey, String> source = new EnumMap<TestKey, String>(TestKey.class);
        source.put(TestKey.FIRST, "first value");
        source.put(TestKey.SECOND, "second value");

        final List<Object> result = EvaluationUtils.evaluateAsList(source);

        assertEquals(2, result.size());
        final Map.Entry<Object, Object> first = asEntry(result.get(0));
        final Map.Entry<Object, Object> second = asEntry(result.get(1));
        assertNotSame(first, second);
        assertEquals(TestKey.FIRST, first.getKey());
        assertEquals("first value", first.getValue());
        assertEquals(TestKey.SECOND, second.getKey());
        assertEquals("second value", second.getValue());
        assertNotSame(source.entrySet().toArray()[0], first);
        assertNotSame(source.entrySet().toArray()[1], second);
    }

    @Test
    void byteArrayIsBoxedInOrder() {
        assertBoxedArray(EvaluationUtils.evaluateAsList(new byte[] {Byte.MIN_VALUE, (byte) -1, (byte) 0, Byte.MAX_VALUE}),
                Byte.valueOf(Byte.MIN_VALUE), Byte.valueOf((byte) -1), Byte.valueOf((byte) 0), Byte.valueOf(Byte.MAX_VALUE));
    }

    @Test
    void shortArrayIsBoxedInOrder() {
        assertBoxedArray(EvaluationUtils.evaluateAsList(new short[] {Short.MIN_VALUE, (short) -1, (short) 0, Short.MAX_VALUE}),
                Short.valueOf(Short.MIN_VALUE), Short.valueOf((short) -1), Short.valueOf((short) 0), Short.valueOf(Short.MAX_VALUE));
    }

    @Test
    void intArrayIsBoxedInOrder() {
        assertBoxedArray(EvaluationUtils.evaluateAsList(new int[] {Integer.MIN_VALUE, -1, 0, Integer.MAX_VALUE}),
                Integer.valueOf(Integer.MIN_VALUE), Integer.valueOf(-1), Integer.valueOf(0), Integer.valueOf(Integer.MAX_VALUE));
    }

    @Test
    void longArrayIsBoxedInOrder() {
        assertBoxedArray(EvaluationUtils.evaluateAsList(new long[] {Long.MIN_VALUE, -1L, 0L, Long.MAX_VALUE}),
                Long.valueOf(Long.MIN_VALUE), Long.valueOf(-1L), Long.valueOf(0L), Long.valueOf(Long.MAX_VALUE));
