package org.thymeleaf.util;

import org.junit.jupiter.api.Test;
import org.thymeleaf.util.VersionUtils.VersionSpec;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;


public class VersionUtilsParseVersionTests {


    private static final String BUILD_TIMESTAMP = "2026-01-02T03:04:05Z";


    private static VersionSpec assertKnownVersion(
            final VersionSpec spec,
            final int expectedMajor, final int expectedMinor, final int expectedPatch,
            final String expectedQualifier,
            final String expectedVersionCore, final String expectedVersion,
            final String expectedBuildTimestamp) {

        assertFalse(spec.isUnknown(), "Expected a known version");
        assertEquals(expectedMajor, spec.getMajor(), "Unexpected major version");
        assertEquals(expectedMinor, spec.getMinor(), "Unexpected minor version");
        assertEquals(expectedPatch, spec.getPatch(), "Unexpected patch version");

        if (expectedQualifier == null) {
            assertFalse(spec.hasQualifier(), "Expected no qualifier");
            assertNull(spec.getQualifier(), "Expected null qualifier");
        } else {
            assertTrue(spec.hasQualifier(), "Expected a qualifier");
            assertEquals(expectedQualifier, spec.getQualifier(), "Unexpected qualifier");
        }

        if (expectedBuildTimestamp == null) {
            assertFalse(spec.hasBuildTimestamp(), "Expected no build timestamp");
            assertNull(spec.getBuildTimestamp(), "Expected null build timestamp");
        } else {
            assertTrue(spec.hasBuildTimestamp(), "Expected a build timestamp");
            assertEquals(expectedBuildTimestamp, spec.getBuildTimestamp(), "Unexpected build timestamp");
        }

        assertEquals(expectedVersionCore, spec.getVersionCore(), "Unexpected version core");
        assertEquals(expectedVersion, spec.getVersion(), "Unexpected version");
        assertEquals(
                (expectedBuildTimestamp != null) ?
                        expectedVersion + " (" + expectedBuildTimestamp + ")" : expectedVersion,
                spec.getFullVersion(), "Unexpected full version");

        return spec;
    }


    private static VersionSpec assertUnknownVersion(
            final VersionSpec spec, final String expectedBuildTimestamp) {

        assertTrue(spec.isUnknown(), "Expected an UNKNOWN version");
        assertEquals(0, spec.getMajor(), "UNKNOWN major should be 0");
        assertEquals(0, spec.getMinor(), "UNKNOWN minor should be 0");
        assertEquals(0, spec.getPatch(), "UNKNOWN patch should be 0");
        assertFalse(spec.hasQualifier(), "UNKNOWN version should have no qualifier");
        assertNull(spec.getQualifier(), "UNKNOWN qualifier should be null");

        if (expectedBuildTimestamp == null) {
            assertFalse(spec.hasBuildTimestamp(), "Expected no build timestamp");
            assertNull(spec.getBuildTimestamp(), "Expected null build timestamp");
        } else {
            assertTrue(spec.hasBuildTimestamp(), "Expected a build timestamp");
            assertEquals(expectedBuildTimestamp, spec.getBuildTimestamp(), "Unexpected build timestamp");
        }

        assertEquals("UNKNOWN", spec.getVersionCore(), "UNKNOWN version core should be 'UNKNOWN'");
        assertEquals("UNKNOWN", spec.getVersion(), "UNKNOWN version should be 'UNKNOWN'");
        assertEquals(
                (expectedBuildTimestamp != null) ?
                        "UNKNOWN (" + expectedBuildTimestamp + ")" : "UNKNOWN",
                spec.getFullVersion(), "Unexpected full version for UNKNOWN version");
        // Even with all-zero components, an UNKNOWN version is never a stable release.
        assertFalse(spec.isStableRelease(), "UNKNOWN version is never a stable release");

        return spec;
    }


    // ---------------------------------------------------------------------
    // Null / empty / blank versions
    // ---------------------------------------------------------------------

    @Test
    public void testNullVersionWithNullBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion(null, null), null);
    }

    @Test
    public void testNullVersionWithBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion(null, BUILD_TIMESTAMP), BUILD_TIMESTAMP);
    }

    @Test
    public void testEmptyVersionWithNullBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion("", null), null);
    }

    @Test
    public void testEmptyVersionWithBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion("", BUILD_TIMESTAMP), BUILD_TIMESTAMP);
    }

    @Test
    public void testBlankVersionWithNullBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion("   \t  ", null), null);
    }

    @Test
    public void testBlankVersionWithBuildTimestamp() {
        assertUnknownVersion(VersionUtils.parseVersion("   ", BUILD_TIMESTAMP), BUILD_TIMESTAMP);
    }


