    // ---------------------------------------------------------------------

    @Test
    public void testMajorOnlyVersion() {
        final VersionSpec spec = assertKnownVersion(
                VersionUtils.parseVersion("1", null),
                1, 0, 0, null, "1", "1", null);
        assertTrue(spec.isStableRelease(), "A plain numeric version should be stable");
        assertTrue(spec.isAtLeast(1), "1 should be at least 1");
        assertFalse(spec.isAtLeast(2), "1 should not be at least 2");
    }

